insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (106, 7, 88, 99, 'سورة الأعراف ٨٨ – ٩٩', '«ربنا افتح بيننا وبين قومنا بالحق»، وسنة الله في الأمم، و«ولو أن أهل القرى آمنوا واتقوا»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 106) = $j$[{"lbl": "الآيتان ٨٨ – ٨٩", "q": "۞قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لَنُخۡرِجَنَّكَ يَٰشُعَيۡبُ وَٱلَّذِينَ ءَامَنُواْ مَعَكَ مِن قَرۡيَتِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۚ قَالَ أَوَلَوۡ كُنَّا كَٰرِهِينَ ﴿٨٨﴾ قَدِ ٱفۡتَرَيۡنَا عَلَى ٱللَّهِ كَذِبًا إِنۡ عُدۡنَا فِي مِلَّتِكُم بَعۡدَ إِذۡ نَجَّىٰنَا ٱللَّهُ مِنۡهَاۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَاۚ وَسِعَ رَبُّنَا كُلَّ شَيۡءٍ عِلۡمًاۚ عَلَى ٱللَّهِ تَوَكَّلۡنَاۚ رَبَّنَا ٱفۡتَحۡ بَيۡنَنَا وَبَيۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَيۡرُ ٱلۡفَٰتِحِينَ ﴿٨٩﴾", "w": [["الملأ", "أشراف القوم الذين يملؤون المجلس إذا جلسوا، والعين إذا نُظر إليهم."], ["استكبروا", "تكلّفوا الكبر وهم حقيرون، حتى لا يقبلوا الحق."], ["من قريتنا", "مدينتنا."], ["على الله توكلنا", "فوّضنا أمرنا، واعتمدنا في حمايتنا عليه."], ["ربنا افتح بيننا", "يا ربنا احكم بيننا."], ["وأنت خير الفاتحين", "وأنت خير الحاكمين."]], "m": "بعد أن أمر شعيب قومه ونهاهم ووعظهم، قال الملأ الذين استكبروا مهدّدين مقسمين: لنخرجنّك يا شعيب والذين آمنوا معك من قريتنا أو لتعودنّ في ملتنا، وهكذا سنة الطغاة: إذا غُلبوا بالحجج فزعوا إلى القوة. فرد شعيب: أوَلو كنا كارهين؟ قد افترينا على الله كذباً إن عدنا في ملتكم بعد إذ نجّانا الله منها، إذ أخبرهم أن الله أمرهم بعبادته وحده وأرسله إليهم، فلو ارتدّ كان كمن كذب على الله. وما يكون لنا أن نعود فيها إلا أن يشاء الله ربنا، فمشيئته نافذة، وسع ربنا كل شيء علماً، على الله توكّلنا في الثبات على دينه، ربنا احكم بيننا وبين قومنا بالحق وأنت خير الحاكمين.", "h": ["بيان سنة بشرية: أن الظلمة والمتكبّرين يجادلون بالباطل، حتى إذا أعياهم الجدال وأُفحموا بالحجج، بدل أن يسلّموا بالحق فيستريحوا ويُريحوا، يفزعون إلى القوة بطرد أهل الحق ونفيهم أو إكراههم على قبول الباطل.", "لا يصح من أهل الحق بعد أن عرفوه ودعوا إليه أن يتنكّروا له ويقبلوا الباطل بدله.", "يُستحب الاستثناء في كل ما عزم عليه المؤمن مستقبلاً، وإن لم يُرده أو حتى يفكّر فيه.", "وجوب التوكل على الله عند تهديد العدو وتخويفه، والمضي في سبيل الحق.", "مشروعية الدعاء وسؤال الله تعالى الحكم بين أهل الحق وأهل الباطل، لأن الله يحكم بالحق وهو خير الحاكمين."], "k": "«على الله توكلنا»… حين يضغط عليّ الناس لأترك الحق، إلى من أفزع؟"}, {"lbl": "الآيات ٩٠ – ٩٣", "q": "وَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ لَئِنِ ٱتَّبَعۡتُمۡ شُعَيۡبًا إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ ﴿٩٠﴾ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ ﴿٩١﴾ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَاۚ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَانُواْ هُمُ ٱلۡخَٰسِرِينَ ﴿٩٢﴾ فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَٰلَٰتِ رَبِّي وَنَصَحۡتُ لَكُمۡۖ فَكَيۡفَ ءَاسَىٰ عَلَىٰ قَوۡمٖ كَٰفِرِينَ ﴿٩٣﴾", "w": [["لئن اتبعتم شعيباً", "على ما جاء به من الدين والهدى."], ["الرجفة", "الحركة العنيفة كالزلزلة."], ["جاثمين", "باركين على ركبهم ميتين."], ["كأن لم يغنوا فيها", "كأن لم يعمروها ويقيموا فيها زمناً طويلاً."], ["الخاسرين", "إذ هلكوا في الدنيا وأُدخلوا النار في الآخرة."], ["آسى", "أحزن وآسف شديد الأسف."]], "m": "بعد أن أيأس شعيب قومه من العودة إلى دينهم وفزع إلى الله، كأن الناس اضطربوا، وقال بعضهم: اتركوا الرجل وما هو عليه، فقال الملأ الذين استكبروا مقسمين: لئن اتبعتم شعيباً على دينه من التوحيد والعدل ورفع الظلم إنكم إذاً لخاسرون. فأخذتهم الرجفة استجابة لدعوة شعيب، فأصبحوا في دارهم جاثمين هلكى. الذين كذّبوا شعيباً كأن لم يعمروا تلك الديار زمناً طويلاً، الذين كذّبوا شعيباً كانوا هم الخاسرين، أما الذين صدّقوه فهم المفلحون. وودّعهم كما ودّع صالح قومه: فتولّى عنهم وقال: يا قوم لقد أبلغتكم رسالات ربي ونصحت لكم فأبيتم إلا التكذيب حتى هلكتم، فكيف آسى على قوم كافرين؟", "h": ["ثمرة الصبر والثبات النصر العاجل أو الآجل.", "نهاية الظلم والطغيان الدمار والخسران.", "لا أسى ولا حزن على من أهلكه الله تعالى بظلمه وفساده في الأرض.", "مشروعية توبيخ الظالمين بعد هلاكهم، كما فعل رسول الله ﷺ بأهل القليب."], "k": "«إنكم إذاً لخاسرون»… قالوها لمن اتبع الحق؛ فهل أخاف خسارة الدنيا إن اتبعته؟"}, {"lbl": "الآيتان ٩٤ – ٩٥", "q": "وَمَآ أَرۡسَلۡنَا فِي قَرۡيَةٖ مِّن نَّبِيٍّ إِلَّآ أَخَذۡنَآ أَهۡلَهَا بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَضَّرَّعُونَ ﴿٩٤﴾ ثُمَّ بَدَّلۡنَا مَكَانَ ٱلسَّيِّئَةِ ٱلۡحَسَنَةَ حَتَّىٰ عَفَواْ وَّقَالُواْ قَدۡ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذۡنَٰهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ ﴿٩٥﴾", "w": [["في قرية", "القرية: المدينة الجامعة لأعيان البلاد ورؤسائها."], ["بالبأساء", "بالشدة كالقحط والجوع والحروب."], ["والضراء", "الحالة المضرّة كالأمراض والغلاء وشدة المؤونة."], ["يضّرّعون", "يدعون الله ويتضرّعون إليه ليكشف عنهم السوء."], ["مكان السيئة الحسنة", "بدل الغلاء الرخاء، وبدل الخوف الأمن، وبدل المرض الصحة."], ["أخذناهم بغتة", "أنزلنا بهم العقوبة فجأة."]], "m": "على إثر قصص خمسة أنبياء، ذكر الله سنته في الأمم السابقة عظة لكفار قريش وذكرى للمؤمنين: وما أرسلنا في قرية من كبريات المدن من نبي فكذّبه قومه إلا أخذنا أهلها بألوان من العذاب التأديبي، كالقحط والجوع وشظف العيش والأمراض والحروب، لعلهم يرجعون إلى الحق. ثم بدّلنا ما بهم من بأساء وضراء يسراً ورخاء وعافية، فكثرت أموالهم وأولادهم وعظم سلطانهم، وقالوا إذا وُعظوا: قد مسّ آباءنا الضراء والسراء، إنما هي الأيام دول: يوم عسر وآخر يسر، فيحق عليهم العذاب، فأخذناهم بغتة وهم لا يشعرون، فيتم هلاكهم ويصبحون حديث عبرة لمن بعدهم.", "h": ["بيان سنة الله تعالى في الأمم السابقة.", "تخويف كفار قريش بما دلّت عليه هذه السنة من أخذ الله تعالى المصرّين على الكفر.", "التذكير والوعظ بتاريخ الأمم السابقة المنبئ عن أسباب هلاكهم وخسرانهم ليتجنّبها العقلاء، كما قال تعالى: «لقد كان في قصصهم عبرة لأولي الألباب»."], "k": "«لعلهم يضّرّعون»… حين تصيبني شدّة، هل أراها رسالة تدعوني للرجوع إلى ربي؟"}, {"lbl": "الآيات ٩٦ – ١٠٠", "q": "وَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰٓ ءَامَنُواْ وَٱتَّقَوۡاْ لَفَتَحۡنَا عَلَيۡهِم بَرَكَٰتٖ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ وَلَٰكِن كَذَّبُواْ فَأَخَذۡنَٰهُم بِمَا كَانُواْ يَكۡسِبُونَ ﴿٩٦﴾ أَفَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا بَيَٰتٗا وَهُمۡ نَآئِمُونَ ﴿٩٧﴾ أَوَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا ضُحٗى وَهُمۡ يَلۡعَبُونَ ﴿٩٨﴾ أَفَأَمِنُواْ مَكۡرَ ٱللَّهِۚ فَلَا يَأۡمَنُ مَكۡرَ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡخَٰسِرُونَ ﴿٩٩﴾ أَوَلَمۡ يَهۡدِ لِلَّذِينَ يَرِثُونَ ٱلۡأَرۡضَ مِنۢ بَعۡدِ أَهۡلِهَآ أَن لَّوۡ نَشَآءُ أَصَبۡنَٰهُم بِذُنُوبِهِمۡۚ وَنَطۡبَعُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَسۡمَعُونَ ﴿١٠٠﴾", "w": [["آمنوا واتقوا", "آمنوا بالله ورسوله ووعد الله ووعيده، واتقوه تعالى بطاعته."], ["بركات من السماء والأرض", "جمع بركة، وهي دوام الخير وبقاؤه، كالعلم والإلهام والمطر من السماء، والنبات والخيرات من الأرض."], ["يكسبون", "من الشرك والمعاصي."], ["مكر الله", "استدراجه تعالى لهم بإغداق النعم عليهم من صحة ومال حتى يأخذهم."], ["أوَلم يهدِ لهم", "أوَلم يبيّن لهم؟ بمعنى يتبيّن لهم."], ["بذنوبهم", "بسبب ذنوبهم."]], "m": "بعدما بيّن سنته في أخذ المكذّبين، فتح باب التوبة والرجاء: ولو أن أهل القرى المكذّبين، كمكة والطائف وغيرهما، آمنوا بالله ورسوله ولقائه، واتقوه في الشرك والمعصية، لفتحنا عليهم بركات من السماء والأرض، ولكن كذّب الأولون فأخذناهم بما كانوا يكسبون، وأهل القرى اليوم إما أن يعتبروا فيؤمنوا، وإما أن يصرّوا فينزل بهم ما نزل بمن قبلهم. ثم أنكر عليهم غفلتهم متعجّباً: أفأمن أهل القرى أن يأتيهم عذابنا بياتاً وهم نائمون؟ أوَأمنوا أن يأتيهم ضحى وهم في أعمالهم التي لا تعود عليهم بخير كأنها لعب أطفال؟ أفأمنوا مكر الله، أغرّهم إمهالنا واستدراجنا؟ فلا يأمن مكر الله إلا القوم الخاسرون. أوَلم يتبيّن للذين يرثون الأرض من بعد أهلها أنّا لو نشاء أصبناهم بذنوبهم كما أصبنا من قبلهم، ونطبع على قلوبهم فهم لا يسمعون ما يقال لهم حتى يهلكوا.", "h": ["عرض الرحمن تبارك وتعالى رحمته على عباده، ولم يطلب منهم أكثر من الإيمان والتقوى.", "حرمة الغفلة، ووجوب الذكر واليقظة.", "حرمة الأمن من مكر الله تعالى.", "إذا أمنت الأمة مكر الله تهيّأت للخسران وحلّ بها لا محالة.", "وجوب الاعتبار بما أصاب الأولين، وذلك بترك ما كان سبباً لهلاكهم."], "k": "«أفأمنوا مكر الله»… النعم تتوالى عليّ وأنا مقيم على ذنب؛ أهي كرامة أم استدراج؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 106;
insert into public.tdb_cards(topic, i, body) select 106, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٨٨ – ٨٩", "q": "۞قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لَنُخۡرِجَنَّكَ يَٰشُعَيۡبُ وَٱلَّذِينَ ءَامَنُواْ مَعَكَ مِن قَرۡيَتِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۚ قَالَ أَوَلَوۡ كُنَّا كَٰرِهِينَ ﴿٨٨﴾ قَدِ ٱفۡتَرَيۡنَا عَلَى ٱللَّهِ كَذِبًا إِنۡ عُدۡنَا فِي مِلَّتِكُم بَعۡدَ إِذۡ نَجَّىٰنَا ٱللَّهُ مِنۡهَاۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَاۚ وَسِعَ رَبُّنَا كُلَّ شَيۡءٍ عِلۡمًاۚ عَلَى ٱللَّهِ تَوَكَّلۡنَاۚ رَبَّنَا ٱفۡتَحۡ بَيۡنَنَا وَبَيۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَيۡرُ ٱلۡفَٰتِحِينَ ﴿٨٩﴾", "w": [["الملأ", "أشراف القوم الذين يملؤون المجلس إذا جلسوا، والعين إذا نُظر إليهم."], ["استكبروا", "تكلّفوا الكبر وهم حقيرون، حتى لا يقبلوا الحق."], ["من قريتنا", "مدينتنا."], ["على الله توكلنا", "فوّضنا أمرنا، واعتمدنا في حمايتنا عليه."], ["ربنا افتح بيننا", "يا ربنا احكم بيننا."], ["وأنت خير الفاتحين", "وأنت خير الحاكمين."]], "m": "بعد أن أمر شعيب قومه ونهاهم ووعظهم، قال الملأ الذين استكبروا مهدّدين مقسمين: لنخرجنّك يا شعيب والذين آمنوا معك من قريتنا أو لتعودنّ في ملتنا، وهكذا سنة الطغاة: إذا غُلبوا بالحجج فزعوا إلى القوة. فرد شعيب: أوَلو كنا كارهين؟ قد افترينا على الله كذباً إن عدنا في ملتكم بعد إذ نجّانا الله منها، إذ أخبرهم أن الله أمرهم بعبادته وحده وأرسله إليهم، فلو ارتدّ كان كمن كذب على الله. وما يكون لنا أن نعود فيها إلا أن يشاء الله ربنا، فمشيئته نافذة، وسع ربنا كل شيء علماً، على الله توكّلنا في الثبات على دينه، ربنا احكم بيننا وبين قومنا بالحق وأنت خير الحاكمين.", "h": ["بيان سنة بشرية: أن الظلمة والمتكبّرين يجادلون بالباطل، حتى إذا أعياهم الجدال وأُفحموا بالحجج، بدل أن يسلّموا بالحق فيستريحوا ويُريحوا، يفزعون إلى القوة بطرد أهل الحق ونفيهم أو إكراههم على قبول الباطل.", "لا يصح من أهل الحق بعد أن عرفوه ودعوا إليه أن يتنكّروا له ويقبلوا الباطل بدله.", "يُستحب الاستثناء في كل ما عزم عليه المؤمن مستقبلاً، وإن لم يُرده أو حتى يفكّر فيه.", "وجوب التوكل على الله عند تهديد العدو وتخويفه، والمضي في سبيل الحق.", "مشروعية الدعاء وسؤال الله تعالى الحكم بين أهل الحق وأهل الباطل، لأن الله يحكم بالحق وهو خير الحاكمين."], "k": "«على الله توكلنا»… حين يضغط عليّ الناس لأترك الحق، إلى من أفزع؟"}, {"lbl": "الآيات ٩٠ – ٩٣", "q": "وَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ لَئِنِ ٱتَّبَعۡتُمۡ شُعَيۡبًا إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ ﴿٩٠﴾ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ ﴿٩١﴾ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَاۚ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَانُواْ هُمُ ٱلۡخَٰسِرِينَ ﴿٩٢﴾ فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَٰلَٰتِ رَبِّي وَنَصَحۡتُ لَكُمۡۖ فَكَيۡفَ ءَاسَىٰ عَلَىٰ قَوۡمٖ كَٰفِرِينَ ﴿٩٣﴾", "w": [["لئن اتبعتم شعيباً", "على ما جاء به من الدين والهدى."], ["الرجفة", "الحركة العنيفة كالزلزلة."], ["جاثمين", "باركين على ركبهم ميتين."], ["كأن لم يغنوا فيها", "كأن لم يعمروها ويقيموا فيها زمناً طويلاً."], ["الخاسرين", "إذ هلكوا في الدنيا وأُدخلوا النار في الآخرة."], ["آسى", "أحزن وآسف شديد الأسف."]], "m": "بعد أن أيأس شعيب قومه من العودة إلى دينهم وفزع إلى الله، كأن الناس اضطربوا، وقال بعضهم: اتركوا الرجل وما هو عليه، فقال الملأ الذين استكبروا مقسمين: لئن اتبعتم شعيباً على دينه من التوحيد والعدل ورفع الظلم إنكم إذاً لخاسرون. فأخذتهم الرجفة استجابة لدعوة شعيب، فأصبحوا في دارهم جاثمين هلكى. الذين كذّبوا شعيباً كأن لم يعمروا تلك الديار زمناً طويلاً، الذين كذّبوا شعيباً كانوا هم الخاسرين، أما الذين صدّقوه فهم المفلحون. وودّعهم كما ودّع صالح قومه: فتولّى عنهم وقال: يا قوم لقد أبلغتكم رسالات ربي ونصحت لكم فأبيتم إلا التكذيب حتى هلكتم، فكيف آسى على قوم كافرين؟", "h": ["ثمرة الصبر والثبات النصر العاجل أو الآجل.", "نهاية الظلم والطغيان الدمار والخسران.", "لا أسى ولا حزن على من أهلكه الله تعالى بظلمه وفساده في الأرض.", "مشروعية توبيخ الظالمين بعد هلاكهم، كما فعل رسول الله ﷺ بأهل القليب."], "k": "«إنكم إذاً لخاسرون»… قالوها لمن اتبع الحق؛ فهل أخاف خسارة الدنيا إن اتبعته؟"}, {"lbl": "الآيتان ٩٤ – ٩٥", "q": "وَمَآ أَرۡسَلۡنَا فِي قَرۡيَةٖ مِّن نَّبِيٍّ إِلَّآ أَخَذۡنَآ أَهۡلَهَا بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَضَّرَّعُونَ ﴿٩٤﴾ ثُمَّ بَدَّلۡنَا مَكَانَ ٱلسَّيِّئَةِ ٱلۡحَسَنَةَ حَتَّىٰ عَفَواْ وَّقَالُواْ قَدۡ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذۡنَٰهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ ﴿٩٥﴾", "w": [["في قرية", "القرية: المدينة الجامعة لأعيان البلاد ورؤسائها."], ["بالبأساء", "بالشدة كالقحط والجوع والحروب."], ["والضراء", "الحالة المضرّة كالأمراض والغلاء وشدة المؤونة."], ["يضّرّعون", "يدعون الله ويتضرّعون إليه ليكشف عنهم السوء."], ["مكان السيئة الحسنة", "بدل الغلاء الرخاء، وبدل الخوف الأمن، وبدل المرض الصحة."], ["أخذناهم بغتة", "أنزلنا بهم العقوبة فجأة."]], "m": "على إثر قصص خمسة أنبياء، ذكر الله سنته في الأمم السابقة عظة لكفار قريش وذكرى للمؤمنين: وما أرسلنا في قرية من كبريات المدن من نبي فكذّبه قومه إلا أخذنا أهلها بألوان من العذاب التأديبي، كالقحط والجوع وشظف العيش والأمراض والحروب، لعلهم يرجعون إلى الحق. ثم بدّلنا ما بهم من بأساء وضراء يسراً ورخاء وعافية، فكثرت أموالهم وأولادهم وعظم سلطانهم، وقالوا إذا وُعظوا: قد مسّ آباءنا الضراء والسراء، إنما هي الأيام دول: يوم عسر وآخر يسر، فيحق عليهم العذاب، فأخذناهم بغتة وهم لا يشعرون، فيتم هلاكهم ويصبحون حديث عبرة لمن بعدهم.", "h": ["بيان سنة الله تعالى في الأمم السابقة.", "تخويف كفار قريش بما دلّت عليه هذه السنة من أخذ الله تعالى المصرّين على الكفر.", "التذكير والوعظ بتاريخ الأمم السابقة المنبئ عن أسباب هلاكهم وخسرانهم ليتجنّبها العقلاء، كما قال تعالى: «لقد كان في قصصهم عبرة لأولي الألباب»."], "k": "«لعلهم يضّرّعون»… حين تصيبني شدّة، هل أراها رسالة تدعوني للرجوع إلى ربي؟"}, {"lbl": "الآيات ٩٦ – ١٠٠", "q": "وَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰٓ ءَامَنُواْ وَٱتَّقَوۡاْ لَفَتَحۡنَا عَلَيۡهِم بَرَكَٰتٖ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ وَلَٰكِن كَذَّبُواْ فَأَخَذۡنَٰهُم بِمَا كَانُواْ يَكۡسِبُونَ ﴿٩٦﴾ أَفَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا بَيَٰتٗا وَهُمۡ نَآئِمُونَ ﴿٩٧﴾ أَوَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا ضُحٗى وَهُمۡ يَلۡعَبُونَ ﴿٩٨﴾ أَفَأَمِنُواْ مَكۡرَ ٱللَّهِۚ فَلَا يَأۡمَنُ مَكۡرَ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡخَٰسِرُونَ ﴿٩٩﴾ أَوَلَمۡ يَهۡدِ لِلَّذِينَ يَرِثُونَ ٱلۡأَرۡضَ مِنۢ بَعۡدِ أَهۡلِهَآ أَن لَّوۡ نَشَآءُ أَصَبۡنَٰهُم بِذُنُوبِهِمۡۚ وَنَطۡبَعُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَسۡمَعُونَ ﴿١٠٠﴾", "w": [["آمنوا واتقوا", "آمنوا بالله ورسوله ووعد الله ووعيده، واتقوه تعالى بطاعته."], ["بركات من السماء والأرض", "جمع بركة، وهي دوام الخير وبقاؤه، كالعلم والإلهام والمطر من السماء، والنبات والخيرات من الأرض."], ["يكسبون", "من الشرك والمعاصي."], ["مكر الله", "استدراجه تعالى لهم بإغداق النعم عليهم من صحة ومال حتى يأخذهم."], ["أوَلم يهدِ لهم", "أوَلم يبيّن لهم؟ بمعنى يتبيّن لهم."], ["بذنوبهم", "بسبب ذنوبهم."]], "m": "بعدما بيّن سنته في أخذ المكذّبين، فتح باب التوبة والرجاء: ولو أن أهل القرى المكذّبين، كمكة والطائف وغيرهما، آمنوا بالله ورسوله ولقائه، واتقوه في الشرك والمعصية، لفتحنا عليهم بركات من السماء والأرض، ولكن كذّب الأولون فأخذناهم بما كانوا يكسبون، وأهل القرى اليوم إما أن يعتبروا فيؤمنوا، وإما أن يصرّوا فينزل بهم ما نزل بمن قبلهم. ثم أنكر عليهم غفلتهم متعجّباً: أفأمن أهل القرى أن يأتيهم عذابنا بياتاً وهم نائمون؟ أوَأمنوا أن يأتيهم ضحى وهم في أعمالهم التي لا تعود عليهم بخير كأنها لعب أطفال؟ أفأمنوا مكر الله، أغرّهم إمهالنا واستدراجنا؟ فلا يأمن مكر الله إلا القوم الخاسرون. أوَلم يتبيّن للذين يرثون الأرض من بعد أهلها أنّا لو نشاء أصبناهم بذنوبهم كما أصبنا من قبلهم، ونطبع على قلوبهم فهم لا يسمعون ما يقال لهم حتى يهلكوا.", "h": ["عرض الرحمن تبارك وتعالى رحمته على عباده، ولم يطلب منهم أكثر من الإيمان والتقوى.", "حرمة الغفلة، ووجوب الذكر واليقظة.", "حرمة الأمن من مكر الله تعالى.", "إذا أمنت الأمة مكر الله تهيّأت للخسران وحلّ بها لا محالة.", "وجوب الاعتبار بما أصاب الأولين، وذلك بترك ما كان سبباً لهلاكهم."], "k": "«أفأمنوا مكر الله»… النعم تتوالى عليّ وأنا مقيم على ذنب؛ أهي كرامة أم استدراج؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (107, 7, 100, 122, 'سورة الأعراف ١٠٠ – ١٢٢', '«تلك القرى نقصّ عليك من أنبائها»، وموسى ﵇ مع فرعون والسحرة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 107) = $j$[{"lbl": "الآيتان ١٠١ – ١٠٢", "q": "تِلۡكَ ٱلۡقُرَىٰ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآئِهَاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَمَا كَانُواْ لِيُؤۡمِنُواْ بِمَا كَذَّبُواْ مِن قَبۡلُۚ كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلۡكَٰفِرِينَ ﴿١٠١﴾ وَمَا وَجَدۡنَا لِأَكۡثَرِهِم مِّنۡ عَهۡدٖۖ وَإِن وَجَدۡنَآ أَكۡثَرَهُمۡ لَفَٰسِقِينَ ﴿١٠٢﴾", "w": [["تلك القرى", "الإشارة إلى قرى قوم نوح وهود وصالح ولوط وشعيب."], ["من أنبائها", "من أخبارها."], ["بالبيّنات", "بالحجج والبراهين الدالة على توحيد الله وصدق رسله."], ["بما كذّبوا من قبل", "بما كُتب عليهم في كتاب المقادير."], ["وما وجدنا لأكثرهم من عهد", "لم نجد لأكثرهم وفاءً بعهودهم التي أُخذت عليهم يوم أُخذ الميثاق."]], "m": "يخاطب الرب رسوله ﷺ: تلك القرى نقصّ عليك من أخبارها مع أنبيائها، كيف دعتهم رسلهم وكيف ردّوا دعوة الله واستكبروا، وكيف كان حكمنا فيهم، لعل قومك يذّكّرون فيؤمنون. ولقد جاءتهم رسلهم بالحجج الواضحات، فما كانوا ليؤمنوا بما كذّبوا به في علم الله وقدره، إذ علم أنهم لا يؤمنون فكتب ذلك عليهم، كذلك يطبع الله على قلوب الكافرين فلا يؤمنون حتى يأخذهم العذاب. وهذا الحكم قائم على أن الله علم من كل إنسان قبل خلقه ما يرغب فيه ويؤثره ويعمله باختياره، فكتب ذلك عليه، فهو لا يعمل إلا به. وما وجدنا لأكثر تلك الأمم من وفاء بالعهد الذي أخذناه عليهم، وإن وجدنا أكثرهم لفاسقين خارجين عن طاعتنا، فأحللنا بهم نقمتنا.", "h": ["تقرير الوحي الإلهي وإثبات نبوة محمد ﷺ، لأن ما قصّ من أنباء الأولين لا يتأتّى إلا بوحي إلهي.", "وجود البيّنات مهما كانت قوية واضحة غير كافٍ في إيمان من لم يشأ الله هدايته.", "المؤمن من آمن في الأزل، والكافر من كفر فيه.", "الطبع على قلوب الكافرين سببه اختيارهم للكفر والشر والفساد، وإصرارهم على ذلك كيفما كانت الحال."], "k": "«وما وجدنا لأكثرهم من عهد»… ما العهود التي قطعتها مع ربي، وهل وفّيت بها؟"}, {"lbl": "الآيات ١٠٣ – ١٠٨", "q": "ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَظَلَمُواْ بِهَاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ ﴿١٠٣﴾ وَقَالَ مُوسَىٰ يَٰفِرۡعَوۡنُ إِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ﴿١٠٤﴾ حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ قَدۡ جِئۡتُكُم بِبَيِّنَةٖ مِّن رَّبِّكُمۡ فَأَرۡسِلۡ مَعِيَ بَنِيٓ إِسۡرَـٰٓءِيلَ ﴿١٠٥﴾ قَالَ إِن كُنتَ جِئۡتَ بِـَٔايَةٖ فَأۡتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿١٠٦﴾ فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ ﴿١٠٧﴾ وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيۡضَآءُ لِلنَّـٰظِرِينَ ﴿١٠٨﴾", "w": [["ثم بعثنا من بعدهم", "من بعد نوح وهود وصالح ولوط وشعيب."], ["موسى", "موسى بن عمران، من ذرية يعقوب بن إسحاق بن إبراهيم ﵈."], ["بآياتنا", "هي تسع آيات: العصا، واليد، والسنون المجدبة، والدم، والطوفان، والجراد، والقمّل، والضفادع، والطمس على الأموال."], ["إلى فرعون", "ملك مصر، الوليد بن مصعب بن الريان."], ["فظلموا بها", "ظلموا أنفسهم بالآيات وما تحمله من هدى، حيث كفروا بها."], ["بيّنة من ربكم", "حجة قاطعة وبرهان ساطع على أني رسول الله إليكم."], ["ونزع يده", "أخرجها بسرعة من جيبه."]], "m": "هذا القصص السادس: موسى ﵇ مع فرعون وملئه، يقصّه الله على نبيه ليثبّت به فؤاده ويقرّر نبوته ويعظ أمته. ثم بعثنا من بعدهم موسى بن عمران بتسع آيات إلى فرعون وملئه من رجالات دولته، فظلموا بها: جحدوها وكفروا بها، واستمرّوا على فسادهم حتى أُغرقوا، فانظر كيف كان عاقبة المفسدين. وأتى موسى فرعون فقال: يا فرعون إني رسول من رب العالمين، جدير بي ألا أقول على الله إلا الحق، قد جئتكم ببيّنة من ربكم، فأرسل معي بني إسرائيل إلى أرض الشام التي كتب الله لهم، وكانت دار آبائهم. قال فرعون: إن كنت جئت بآية فأتِ بها إن كنت من الصادقين، فألقى موسى عصاه فإذا هي ثعبان مبين، حية عظيمة تهتز، ونزع يده من جيبه فإذا هي بيضاء للناظرين بياضاً غير معهود مثله في أيدي الناس.", "h": ["بيان سوء عاقبة المفسدين بالشرك والمعاصي.", "تذكير موسى فرعون بأسلوب لطيف بأنه ليس رباً، بل هناك رب العالمين، وهو الله رب موسى وهارون والناس أجمعين.", "تقرير مبدأ الصدق لدى الرسل ﵈.", "ظهور آيتين لموسى: العصا واليد."], "k": "«حقيق على أن لا أقول على الله إلا الحق»… هل أتحرّى الصدق في كل ما أنسبه إلى ديني؟"}, {"lbl": "الآيات ١٠٩ – ١١٢", "q": "قَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٞ ﴿١٠٩﴾ يُرِيدُ أَن يُخۡرِجَكُم مِّنۡ أَرۡضِكُمۡۖ فَمَاذَا تَأۡمُرُونَ ﴿١١٠﴾ قَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَأَرۡسِلۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ ﴿١١١﴾ يَأۡتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمٖ ﴿١١٢﴾", "w": [["من أرضكم", "من بلادكم، يستولي عليها ويحكمكم."], ["فماذا تأمرون", "أشيروا بما ترون الصواب في حل هذا المشكل."], ["أرجِه", "أمهله وأخاه، لا تعجل عليهما قبل اتخاذ ما يلزم من الاحتياطات."], ["في المدائن", "مدن المملكة الفرعونية."], ["حاشرين", "رجالاً يجمعون السحرة الخبراء في فن السحر للمناظرة."]], "m": "لما رأى الملأ من قوم فرعون آيتي العصا واليد قالوا: إن هذا لساحر عليم، وذلك لما رأوا العصا تتحول حية واليد بيضاء، واتهموه سياسياً: يريد أن يخرجكم من أرضكم ليستولي عليها هو وقومه بنو إسرائيل. فقال فرعون: فماذا تأمرون؟ قالوا: أرجِه وأخاه، أوقفهما عندك، وأرسل في المدائن حاشرين من الشرط يجمعون أهل الفن من السحرة من كافة أنحاء الإقليم المصري، وأجرِ معه مناظرة، فإذا انهزم انتهى أمره وأمنّا خطره على بلادنا.", "h": ["جهل الملأ بالآيات أدّى بهم إلى أن قالوا: إن موسى ساحر عليم.", "مكر الملأ وخبثهم، إذ اتهموا موسى سياسياً بأنه يريد الملك، وهو كذب بحت، وإنما يريد إخراج بني إسرائيل من مصر حيث طال استعبادهم وامتهانهم، وهم أبناء الأنبياء.", "فضيحة فرعون، حيث نسي دعواه الربوبية فاستشار الملأ في شأنه، إذ الرب الحق لا يستشير عباده فيما يريد فعله.", "السحر صناعة من الصناعات، يُتعلّم ويبرع فيها المرء ويتقدّم حتى يتفوّق على غيره.", "حرمة السحر وحرمة تعلّمه، ووجوب إقامة الحد على من ظهر عليه وعُرف به."], "k": "«يريد أن يخرجكم من أرضكم»… كم مرة يُشوَّه الحق بتهمة سياسية؛ فهل أتثبّت قبل أن أصدّق؟"}, {"lbl": "الآيات ١١٣ – ١١٦", "q": "وَجَآءَ ٱلسَّحَرَةُ فِرۡعَوۡنَ قَالُوٓاْ إِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ ﴿١١٣﴾ قَالَ نَعَمۡ وَإِنَّكُمۡ لَمِنَ ٱلۡمُقَرَّبِينَ ﴿١١٤﴾ قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ نَحۡنُ ٱلۡمُلۡقِينَ ﴿١١٥﴾ قَالَ أَلۡقُواْۖ فَلَمَّآ أَلۡقَوۡاْ سَحَرُوٓاْ أَعۡيُنَ ٱلنَّاسِ وَٱسۡتَرۡهَبُوهُمۡ وَجَآءُو بِسِحۡرٍ عَظِيمٖ ﴿١١٦﴾", "w": [["السحرة", "جمع ساحر، وهو من يتقن فن السحر ويؤثّر في أعين الناس."], ["إن لنا لأجراً", "ثواباً من عندك تعطيناه إن نحن غلبنا."], ["سحروا أعين الناس", "حيث صار النظّارة في الميدان يشاهدون عصيّ السحرة وحبالهم حيات وثعابين تملأ الساحة."], ["واسترهبوهم", "أدخلوا الرهب والرعب في قلوب الناس من قوة أثر السحر في عيونهم."]], "m": "وصل خبراء السحر، وعرفوا أن الموقف صعب على فرعون، فطالبوه بالأجر العظيم: إن لنا لأجراً إن كنا نحن الغالبين، قال: نعم، وزادهم: وإنكم لمن المقرّبين من خواصّي ورجال قصري. وتقدّموا واثقين بقوتهم: يا موسى إما أن تُلقي وإما أن نكون نحن الملقين، قال: ألقوا، فلما ألقوا سحروا أعين الناس واسترهبوهم وجاؤوا بسحر عظيم، حتى أوجس موسى في نفسه خيفة، فنهاه ربه وأعلمه أنه الغالب.", "h": ["مشروعية طلب الأجرة على العمل الذي يقوم به الإنسان خارجاً عن نطاق العبادة.", "مشروعية الترقيات الحكومية لذي الخدمة الجلّى للدولة.", "تأثير السحر على أعين الناس حقيقة، بحيث يرون الشيء على خلاف ما هو عليه، إذ العصي والحبال استحالت في أعين الناس حيات وثعابين."], "k": "«وجاؤوا بسحر عظيم»… كم من باطل يبهر العيون اليوم؛ فهل أثق أن الحق سيبتلعه؟"}, {"lbl": "الآيات ١١٧ – ١٢٢", "q": "۞وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَلۡقِ عَصَاكَۖ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ ﴿١١٧﴾ فَوَقَعَ ٱلۡحَقُّ وَبَطَلَ مَا كَانُواْ يَعۡمَلُونَ ﴿١١٨﴾ فَغُلِبُواْ هُنَالِكَ وَٱنقَلَبُواْ صَٰغِرِينَ ﴿١١٩﴾ وَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ ﴿١٢٠﴾ قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ ﴿١٢١﴾ رَبِّ مُوسَىٰ وَهَٰرُونَ ﴿١٢٢﴾", "w": [["تلقف", "تأخذ بسرعة فائقة وحذق عجيب."], ["ما يأفكون", "ما يقلبون بسحرهم وتمويههم."], ["فوقع الحق", "ثبت وظهر."], ["صاغرين", "ذليلين."]], "m": "بعد أن ألقى السحرة حبالهم وعصيّهم وانقلبت بالتمويه حيات، ورهب الناس، وظن فرعون وملؤه أنهم غالبون، أوحى الله إلى موسى أن ألقِ عصاك، فإذا هي تلقف ما يأفكون، تبتلعه، فوقع الحق وثبت، وبطل ما كانوا يعملون من السحر والتمويه، فغُلب فرعون وملؤه هنالك في ساحة المباراة، وانقلبوا إلى ديارهم صاغرين مهزومين. وأُلقي السحرة ساجدين بعد أن بهرتهم الآية الكبرى، كأنما ألقاهم أحد على وجه الأرض، قالوا: آمنّا برب العالمين رب موسى وهارون، وفي ذلك كفرهم بربوبية فرعون الباطلة، لأن الإيمان بالله يستلزم الكفر بما عداه.", "h": ["بيان سنته تعالى في أن الحق والباطل إذا التقيا في أي ميدان فالغلبة للحق دائماً.", "بطلان السحر وعدم فلاح أهله، لقوله تعالى: «ولا يفلح الساحر حيث أتى».", "فضل العلم وأنه سبب الهداية، فإيمان السحرة كان ثمرة العلم، إذ عرفوا أن ما جاء به موسى ليس سحراً، وإنما هو آية من الله فآمنوا.", "مظهر من مظاهر القضاء والقدر، فالسحرة أصبحوا كافرين وأمسوا مسلمين."], "k": "«وأُلقي السحرة ساجدين»… أصبحوا كافرين وأمسوا مؤمنين؛ فلا أيأس من أحد، ولا آمن على نفسي."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 107;
insert into public.tdb_cards(topic, i, body) select 107, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١٠١ – ١٠٢", "q": "تِلۡكَ ٱلۡقُرَىٰ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآئِهَاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَمَا كَانُواْ لِيُؤۡمِنُواْ بِمَا كَذَّبُواْ مِن قَبۡلُۚ كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلۡكَٰفِرِينَ ﴿١٠١﴾ وَمَا وَجَدۡنَا لِأَكۡثَرِهِم مِّنۡ عَهۡدٖۖ وَإِن وَجَدۡنَآ أَكۡثَرَهُمۡ لَفَٰسِقِينَ ﴿١٠٢﴾", "w": [["تلك القرى", "الإشارة إلى قرى قوم نوح وهود وصالح ولوط وشعيب."], ["من أنبائها", "من أخبارها."], ["بالبيّنات", "بالحجج والبراهين الدالة على توحيد الله وصدق رسله."], ["بما كذّبوا من قبل", "بما كُتب عليهم في كتاب المقادير."], ["وما وجدنا لأكثرهم من عهد", "لم نجد لأكثرهم وفاءً بعهودهم التي أُخذت عليهم يوم أُخذ الميثاق."]], "m": "يخاطب الرب رسوله ﷺ: تلك القرى نقصّ عليك من أخبارها مع أنبيائها، كيف دعتهم رسلهم وكيف ردّوا دعوة الله واستكبروا، وكيف كان حكمنا فيهم، لعل قومك يذّكّرون فيؤمنون. ولقد جاءتهم رسلهم بالحجج الواضحات، فما كانوا ليؤمنوا بما كذّبوا به في علم الله وقدره، إذ علم أنهم لا يؤمنون فكتب ذلك عليهم، كذلك يطبع الله على قلوب الكافرين فلا يؤمنون حتى يأخذهم العذاب. وهذا الحكم قائم على أن الله علم من كل إنسان قبل خلقه ما يرغب فيه ويؤثره ويعمله باختياره، فكتب ذلك عليه، فهو لا يعمل إلا به. وما وجدنا لأكثر تلك الأمم من وفاء بالعهد الذي أخذناه عليهم، وإن وجدنا أكثرهم لفاسقين خارجين عن طاعتنا، فأحللنا بهم نقمتنا.", "h": ["تقرير الوحي الإلهي وإثبات نبوة محمد ﷺ، لأن ما قصّ من أنباء الأولين لا يتأتّى إلا بوحي إلهي.", "وجود البيّنات مهما كانت قوية واضحة غير كافٍ في إيمان من لم يشأ الله هدايته.", "المؤمن من آمن في الأزل، والكافر من كفر فيه.", "الطبع على قلوب الكافرين سببه اختيارهم للكفر والشر والفساد، وإصرارهم على ذلك كيفما كانت الحال."], "k": "«وما وجدنا لأكثرهم من عهد»… ما العهود التي قطعتها مع ربي، وهل وفّيت بها؟"}, {"lbl": "الآيات ١٠٣ – ١٠٨", "q": "ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَظَلَمُواْ بِهَاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ ﴿١٠٣﴾ وَقَالَ مُوسَىٰ يَٰفِرۡعَوۡنُ إِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ﴿١٠٤﴾ حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ قَدۡ جِئۡتُكُم بِبَيِّنَةٖ مِّن رَّبِّكُمۡ فَأَرۡسِلۡ مَعِيَ بَنِيٓ إِسۡرَـٰٓءِيلَ ﴿١٠٥﴾ قَالَ إِن كُنتَ جِئۡتَ بِـَٔايَةٖ فَأۡتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿١٠٦﴾ فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ ﴿١٠٧﴾ وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيۡضَآءُ لِلنَّـٰظِرِينَ ﴿١٠٨﴾", "w": [["ثم بعثنا من بعدهم", "من بعد نوح وهود وصالح ولوط وشعيب."], ["موسى", "موسى بن عمران، من ذرية يعقوب بن إسحاق بن إبراهيم ﵈."], ["بآياتنا", "هي تسع آيات: العصا، واليد، والسنون المجدبة، والدم، والطوفان، والجراد، والقمّل، والضفادع، والطمس على الأموال."], ["إلى فرعون", "ملك مصر، الوليد بن مصعب بن الريان."], ["فظلموا بها", "ظلموا أنفسهم بالآيات وما تحمله من هدى، حيث كفروا بها."], ["بيّنة من ربكم", "حجة قاطعة وبرهان ساطع على أني رسول الله إليكم."], ["ونزع يده", "أخرجها بسرعة من جيبه."]], "m": "هذا القصص السادس: موسى ﵇ مع فرعون وملئه، يقصّه الله على نبيه ليثبّت به فؤاده ويقرّر نبوته ويعظ أمته. ثم بعثنا من بعدهم موسى بن عمران بتسع آيات إلى فرعون وملئه من رجالات دولته، فظلموا بها: جحدوها وكفروا بها، واستمرّوا على فسادهم حتى أُغرقوا، فانظر كيف كان عاقبة المفسدين. وأتى موسى فرعون فقال: يا فرعون إني رسول من رب العالمين، جدير بي ألا أقول على الله إلا الحق، قد جئتكم ببيّنة من ربكم، فأرسل معي بني إسرائيل إلى أرض الشام التي كتب الله لهم، وكانت دار آبائهم. قال فرعون: إن كنت جئت بآية فأتِ بها إن كنت من الصادقين، فألقى موسى عصاه فإذا هي ثعبان مبين، حية عظيمة تهتز، ونزع يده من جيبه فإذا هي بيضاء للناظرين بياضاً غير معهود مثله في أيدي الناس.", "h": ["بيان سوء عاقبة المفسدين بالشرك والمعاصي.", "تذكير موسى فرعون بأسلوب لطيف بأنه ليس رباً، بل هناك رب العالمين، وهو الله رب موسى وهارون والناس أجمعين.", "تقرير مبدأ الصدق لدى الرسل ﵈.", "ظهور آيتين لموسى: العصا واليد."], "k": "«حقيق على أن لا أقول على الله إلا الحق»… هل أتحرّى الصدق في كل ما أنسبه إلى ديني؟"}, {"lbl": "الآيات ١٠٩ – ١١٢", "q": "قَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٞ ﴿١٠٩﴾ يُرِيدُ أَن يُخۡرِجَكُم مِّنۡ أَرۡضِكُمۡۖ فَمَاذَا تَأۡمُرُونَ ﴿١١٠﴾ قَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَأَرۡسِلۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ ﴿١١١﴾ يَأۡتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمٖ ﴿١١٢﴾", "w": [["من أرضكم", "من بلادكم، يستولي عليها ويحكمكم."], ["فماذا تأمرون", "أشيروا بما ترون الصواب في حل هذا المشكل."], ["أرجِه", "أمهله وأخاه، لا تعجل عليهما قبل اتخاذ ما يلزم من الاحتياطات."], ["في المدائن", "مدن المملكة الفرعونية."], ["حاشرين", "رجالاً يجمعون السحرة الخبراء في فن السحر للمناظرة."]], "m": "لما رأى الملأ من قوم فرعون آيتي العصا واليد قالوا: إن هذا لساحر عليم، وذلك لما رأوا العصا تتحول حية واليد بيضاء، واتهموه سياسياً: يريد أن يخرجكم من أرضكم ليستولي عليها هو وقومه بنو إسرائيل. فقال فرعون: فماذا تأمرون؟ قالوا: أرجِه وأخاه، أوقفهما عندك، وأرسل في المدائن حاشرين من الشرط يجمعون أهل الفن من السحرة من كافة أنحاء الإقليم المصري، وأجرِ معه مناظرة، فإذا انهزم انتهى أمره وأمنّا خطره على بلادنا.", "h": ["جهل الملأ بالآيات أدّى بهم إلى أن قالوا: إن موسى ساحر عليم.", "مكر الملأ وخبثهم، إذ اتهموا موسى سياسياً بأنه يريد الملك، وهو كذب بحت، وإنما يريد إخراج بني إسرائيل من مصر حيث طال استعبادهم وامتهانهم، وهم أبناء الأنبياء.", "فضيحة فرعون، حيث نسي دعواه الربوبية فاستشار الملأ في شأنه، إذ الرب الحق لا يستشير عباده فيما يريد فعله.", "السحر صناعة من الصناعات، يُتعلّم ويبرع فيها المرء ويتقدّم حتى يتفوّق على غيره.", "حرمة السحر وحرمة تعلّمه، ووجوب إقامة الحد على من ظهر عليه وعُرف به."], "k": "«يريد أن يخرجكم من أرضكم»… كم مرة يُشوَّه الحق بتهمة سياسية؛ فهل أتثبّت قبل أن أصدّق؟"}, {"lbl": "الآيات ١١٣ – ١١٦", "q": "وَجَآءَ ٱلسَّحَرَةُ فِرۡعَوۡنَ قَالُوٓاْ إِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ ﴿١١٣﴾ قَالَ نَعَمۡ وَإِنَّكُمۡ لَمِنَ ٱلۡمُقَرَّبِينَ ﴿١١٤﴾ قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ نَحۡنُ ٱلۡمُلۡقِينَ ﴿١١٥﴾ قَالَ أَلۡقُواْۖ فَلَمَّآ أَلۡقَوۡاْ سَحَرُوٓاْ أَعۡيُنَ ٱلنَّاسِ وَٱسۡتَرۡهَبُوهُمۡ وَجَآءُو بِسِحۡرٍ عَظِيمٖ ﴿١١٦﴾", "w": [["السحرة", "جمع ساحر، وهو من يتقن فن السحر ويؤثّر في أعين الناس."], ["إن لنا لأجراً", "ثواباً من عندك تعطيناه إن نحن غلبنا."], ["سحروا أعين الناس", "حيث صار النظّارة في الميدان يشاهدون عصيّ السحرة وحبالهم حيات وثعابين تملأ الساحة."], ["واسترهبوهم", "أدخلوا الرهب والرعب في قلوب الناس من قوة أثر السحر في عيونهم."]], "m": "وصل خبراء السحر، وعرفوا أن الموقف صعب على فرعون، فطالبوه بالأجر العظيم: إن لنا لأجراً إن كنا نحن الغالبين، قال: نعم، وزادهم: وإنكم لمن المقرّبين من خواصّي ورجال قصري. وتقدّموا واثقين بقوتهم: يا موسى إما أن تُلقي وإما أن نكون نحن الملقين، قال: ألقوا، فلما ألقوا سحروا أعين الناس واسترهبوهم وجاؤوا بسحر عظيم، حتى أوجس موسى في نفسه خيفة، فنهاه ربه وأعلمه أنه الغالب.", "h": ["مشروعية طلب الأجرة على العمل الذي يقوم به الإنسان خارجاً عن نطاق العبادة.", "مشروعية الترقيات الحكومية لذي الخدمة الجلّى للدولة.", "تأثير السحر على أعين الناس حقيقة، بحيث يرون الشيء على خلاف ما هو عليه، إذ العصي والحبال استحالت في أعين الناس حيات وثعابين."], "k": "«وجاؤوا بسحر عظيم»… كم من باطل يبهر العيون اليوم؛ فهل أثق أن الحق سيبتلعه؟"}, {"lbl": "الآيات ١١٧ – ١٢٢", "q": "۞وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَلۡقِ عَصَاكَۖ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ ﴿١١٧﴾ فَوَقَعَ ٱلۡحَقُّ وَبَطَلَ مَا كَانُواْ يَعۡمَلُونَ ﴿١١٨﴾ فَغُلِبُواْ هُنَالِكَ وَٱنقَلَبُواْ صَٰغِرِينَ ﴿١١٩﴾ وَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ ﴿١٢٠﴾ قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ ﴿١٢١﴾ رَبِّ مُوسَىٰ وَهَٰرُونَ ﴿١٢٢﴾", "w": [["تلقف", "تأخذ بسرعة فائقة وحذق عجيب."], ["ما يأفكون", "ما يقلبون بسحرهم وتمويههم."], ["فوقع الحق", "ثبت وظهر."], ["صاغرين", "ذليلين."]], "m": "بعد أن ألقى السحرة حبالهم وعصيّهم وانقلبت بالتمويه حيات، ورهب الناس، وظن فرعون وملؤه أنهم غالبون، أوحى الله إلى موسى أن ألقِ عصاك، فإذا هي تلقف ما يأفكون، تبتلعه، فوقع الحق وثبت، وبطل ما كانوا يعملون من السحر والتمويه، فغُلب فرعون وملؤه هنالك في ساحة المباراة، وانقلبوا إلى ديارهم صاغرين مهزومين. وأُلقي السحرة ساجدين بعد أن بهرتهم الآية الكبرى، كأنما ألقاهم أحد على وجه الأرض، قالوا: آمنّا برب العالمين رب موسى وهارون، وفي ذلك كفرهم بربوبية فرعون الباطلة، لأن الإيمان بالله يستلزم الكفر بما عداه.", "h": ["بيان سنته تعالى في أن الحق والباطل إذا التقيا في أي ميدان فالغلبة للحق دائماً.", "بطلان السحر وعدم فلاح أهله، لقوله تعالى: «ولا يفلح الساحر حيث أتى».", "فضل العلم وأنه سبب الهداية، فإيمان السحرة كان ثمرة العلم، إذ عرفوا أن ما جاء به موسى ليس سحراً، وإنما هو آية من الله فآمنوا.", "مظهر من مظاهر القضاء والقدر، فالسحرة أصبحوا كافرين وأمسوا مسلمين."], "k": "«وأُلقي السحرة ساجدين»… أصبحوا كافرين وأمسوا مؤمنين؛ فلا أيأس من أحد، ولا آمن على نفسي."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (108, 7, 123, 137, 'سورة الأعراف ١٢٣ – ١٣٧', '«ربنا أفرغ علينا صبراً»، «استعينوا بالله واصبروا»، وآيات العذاب على آل فرعون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 108) = $j$[{"lbl": "الآيات ١٢٣ – ١٢٦", "q": "قَالَ فِرۡعَوۡنُ ءَامَنتُم بِهِۦ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّ هَٰذَا لَمَكۡرٞ مَّكَرۡتُمُوهُ فِي ٱلۡمَدِينَةِ لِتُخۡرِجُواْ مِنۡهَآ أَهۡلَهَاۖ فَسَوۡفَ تَعۡلَمُونَ ﴿١٢٣﴾ لَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ ثُمَّ لَأُصَلِّبَنَّكُمۡ أَجۡمَعِينَ ﴿١٢٤﴾ قَالُوٓاْ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ ﴿١٢٥﴾ وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتۡنَاۚ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَتَوَفَّنَا مُسۡلِمِينَ ﴿١٢٦﴾", "w": [["آمنتم به", "صدّقتموه فيما جاء به ودعا إليه."], ["لمكر مكرتموه", "حيلة احتلتموها وتواطأتم مع موسى عليها."], ["من خلاف", "بأن يقطع اليد اليمنى والرجل اليسرى أو العكس."], ["ثم لأصلّبنّكم", "التصليب: الشد على خشبة حتى الموت."], ["منقلبون", "راجعون."], ["وما تنقم منا", "وما تكره منا وتنكر علينا إلا إيماننا بآيات ربنا لما جاءتنا."], ["أفرغ علينا صبراً", "أفض علينا صبراً قوياً حتى نثبت على ما توعّدنا به فرعون من العذاب، ولا نرتدّ بعد إيماننا."]], "m": "بعد أن آمن السحرة وسجدوا لله رب العالمين، حاكمهم فرعون: آمنتم به قبل أن آذن لكم؟ عبارة فيها رائحة الهزيمة والحمق، فالإيمان إذعان باطني لا علاقة له بالإذن. إن هذا لمكر مكرتموه مع موسى في المدينة قبل المباراة لتخرجوا منها أهلها وتستولوا عليها، فسوف تعلمون: لأقطّعنّ أيديكم وأرجلكم من خلاف، ثم لأصلّبنّكم أجمعين على الأخشاب نكالاً وعبرة. قالوا: إنا إلى ربنا منقلبون، فقتلك إيانا يقرّبنا من ربنا ونحن في شوق إلى لقائه، وما تنقم منا جرماً أجرمناه أو فساداً أشعناه، إلا أن آمنّا بآيات ربنا لما جاءتنا، وهذا لا عار فيه، ثم أقبلوا على الله ضارعين: ربنا أفرغ علينا صبراً حتى نتحمّل العذاب في ذاتك، وتوفّنا مسلمين. ونفّذ فرعون جريمته، ولكن أحدث ذلك اضطراباً في البلاد لم يكن يتوقّعه.", "h": ["القلوب المظلمة بالكفر والجرائم أصحابها لا يتورّعون عن الكذب واتهام الأبرياء.", "فضيلة الاسترجاع: أن يقول «إنا لله وإنا إليه راجعون»، حيث فزع إليها السحرة لما هدّدهم فرعون، إذ قالوا: «إنا إلى ربنا منقلبون»، فهان عليهم ما هُدّدوا به.", "مشروعية سؤال الصبر على البلاء للثبات على الإيمان.", "فضل الوفاة على الإسلام، وأنه مطلب عالٍ لأهل الإيمان."], "k": "«وتوفّنا مسلمين»… هل أسأل ربي حسن الخاتمة كل يوم كما سألها السحرة في ساعتهم الأولى؟"}, {"lbl": "الآيات ١٢٧ – ١٢٩", "q": "وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ أَتَذَرُ مُوسَىٰ وَقَوۡمَهُۥ لِيُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَيَذَرَكَ وَءَالِهَتَكَۚ قَالَ سَنُقَتِّلُ أَبۡنَآءَهُمۡ وَنَسۡتَحۡيِۦ نِسَآءَهُمۡ وَإِنَّا فَوۡقَهُمۡ قَٰهِرُونَ ﴿١٢٧﴾ قَالَ مُوسَىٰ لِقَوۡمِهِ ٱسۡتَعِينُواْ بِٱللَّهِ وَٱصۡبِرُوٓاْۖ إِنَّ ٱلۡأَرۡضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ ﴿١٢٨﴾ قَالُوٓاْ أُوذِينَا مِن قَبۡلِ أَن تَأۡتِيَنَا وَمِنۢ بَعۡدِ مَا جِئۡتَنَاۚ قَالَ عَسَىٰ رَبُّكُمۡ أَن يُهۡلِكَ عَدُوَّكُمۡ وَيَسۡتَخۡلِفَكُمۡ فِي ٱلۡأَرۡضِ فَيَنظُرَ كَيۡفَ تَعۡمَلُونَ ﴿١٢٩﴾", "w": [["قال الملأ", "أي لفرعون."], ["وقومه", "أي بني إسرائيل."], ["ليفسدوا في الأرض", "في البلاد، بالدعوة إلى مخالفتك وترك طاعتك."], ["وآلهتك", "أصناماً صغاراً وضعها ليعبدها الناس، وقال: أنا ربكم الأعلى."], ["نستحيي نساءهم", "نُبقي على نسائهم لا نذبحهنّ كما نذبح الأطفال الذكور."], ["ويستخلفكم في الأرض", "يجعلكم خلفاء فيها تخلفون الظالمين بعد هلاكهم."]], "m": "بعد انتصار موسى وإيمان السحرة ظهر أمره واتبعه ستمائة ألف من بني إسرائيل، فخاف قوم فرعون وقالوا محرّضين: أتذر موسى وقومه ليفسدوا في أرض مصر بالدعوة إلى مخالفتك، ويذرك وآلهتك التي كنت تدعو الناس لعبادتها لتقرّبهم إليك؟ قال فرعون: سنقتّل أبناءهم ونستحيي نساءهم كما كنا نفعل، وإنا فوقهم قاهرون، كلمة يعوّض بها ما فقد من جبروته بعد هزيمته. فقال موسى لقومه وقد أرعبهم التهديد: استعينوا بالله على ما قد ينالكم من ظلم فرعون، واصبروا، إن الأرض لله يورثها من يشاء من عباده والعاقبة للمتقين، فمتى صبرتم واتقيتم أهلك عدوكم وأورثكم أرضه، وقد تم ذلك حرفياً. قالوا بكلمة الآيس المهزوم نفسياً لطول ما عانوا: أوذينا من قبل أن تأتينا ومن بعد ما جئتنا، فأحيا موسى الأمل في نفوسهم: عسى ربكم أن يهلك عدوكم ويستخلفكم في الأرض فينظر كيف تعملون، وقد تم ذلك كاملاً بلا نقصان.", "h": ["خطر بطانة السوء على الملوك والرؤساء، تجلّت في إثارة فرعون ودفعه إلى البطش بقولهم: «أتذر موسى وقومه ليفسدوا في الأرض…».", "بيان فضيلة الصبر والتقوى، وأنهما مفتاح النصر وإكسير الكمال البشري.", "النفوس المريضة علاجها عسير، ولكن بالصبر والمثابرة تُشفى إن شاء الله تعالى.", "بيان صدق ما رجاه موسى من ربه، حيث تحقّق بحذافيره.", "استحسان رفع معنويات المؤمنين بذكر حسن العاقبة، والتبشير بوعد الله لأوليائه أهل الإيمان والتقوى."], "k": "«فينظر كيف تعملون»… إن مكّنني الله في شيء بعد ضيق، فكيف سيجدني أعمل؟"}, {"lbl": "الآيات ١٣٠ – ١٣٣", "q": "وَلَقَدۡ أَخَذۡنَآ ءَالَ فِرۡعَوۡنَ بِٱلسِّنِينَ وَنَقۡصٖ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَذَّكَّرُونَ ﴿١٣٠﴾ فَإِذَا جَآءَتۡهُمُ ٱلۡحَسَنَةُ قَالُواْ لَنَا هَٰذِهِۦۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَطَّيَّرُواْ بِمُوسَىٰ وَمَن مَّعَهُۥٓۗ أَلَآ إِنَّمَا طَـٰٓئِرُهُمۡ عِندَ ٱللَّهِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿١٣١﴾ وَقَالُواْ مَهۡمَا تَأۡتِنَا بِهِۦ مِنۡ ءَايَةٖ لِّتَسۡحَرَنَا بِهَا فَمَا نَحۡنُ لَكَ بِمُؤۡمِنِينَ ﴿١٣٢﴾ فَأَرۡسَلۡنَا عَلَيۡهِمُ ٱلطُّوفَانَ وَٱلۡجَرَادَ وَٱلۡقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٖ مُّفَصَّلَٰتٖ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ ﴿١٣٣﴾", "w": [["أخذنا آل فرعون بالسنين", "عاقبناهم بسني الجدب والقحط."], ["الحسنة", "ما يحسن من خصب ورخاء وكثرة رزق وعافية."], ["سيئة", "ضد الحسنة، وهي الجدب والغلاء والمرض."], ["يطّيّروا بموسى", "يتشاءموا بموسى وقومه."], ["الطوفان والجراد", "الطوفان: الفيضانات المغرقة، والجراد معروف بأكل الزرع والثمار."], ["والقمّل والضفادع", "القمّل يجوز أن يكون القمل المعروف، أو السوس في الحبوب، والضفادع حيوان يوجد في المياه والمستنقعات."], ["والدم", "قد يكون دم رعاف أو نزيف، أو تحوّل ماء الشرب إلى دم عبيط في أوانيهم وأفواههم، آية لموسى ﵇."], ["فاستكبروا وكانوا قوماً مجرمين", "حيث لم يؤمنوا بهذه الآيات، مفسدين حيث حُكم بإهلاكهم."]], "m": "لما حملهم الكبر على مواصلة الكفر، أصابهم الرب بجفاف وقحط سنوات لعلهم يذّكّرون، فلم يذّكّروا، فحوّل جدبهم خصباً وبلاءهم عافية، فقالوا في الرخاء: هذه لنا نحن مستحقّوها، وفي البلاء: هذه من شؤم موسى ومن معه، ألا إنما طائرهم عند الله، فهو جاعل للحسنة أسبابها وهي الإيمان والتقوى، وللسيئة أسبابها وهي الكفر والمعاصي، ولكن أكثرهم لا يعلمون. ولجّوا في العناد: مهما تأتنا به من آية لتسحرنا بها فما نحن لك بمؤمنين. فدعا موسى ربه: يا رب إن فرعون علا في الأرض وبغى، وإن قومه نقضوا العهد، فخذهم بعقوبة تكون لهم نقمة ولقومي عظة ولمن بعدهم آية، فأرسل عليهم الطوفان فكادوا يغرقون، فجاؤوا موسى يطلبون رفعه ويعدون بالإيمان وإرسال بني إسرائيل، فرُفع عنهم فتنكّروا، ثم الجراد فأكل زروعهم وثمارهم، فوعدوا ثم نكثوا، وهكذا حتى تمّت الآيات الخمس مفصّلات، فاستكبروا وكانوا قوماً مجرمين لا خير فيهم ولا عهد لهم.", "h": ["من تدبير الله تعالى أخذه عباده بالشدائد لعلهم يذّكّرون فيتّعظون ويتوبون.", "بطلان التطيّر مطلقاً، وإنما الشؤم في المعاصي بمخالفة شرع الله، فيترتّب على الفسق والعصيان البلاء والعذاب.", "الجهل سبب الكفر والمعاصي، وسوء الأخلاق، وفساد الأحوال.", "عدم إيمان آل فرعون مع توارد الآيات عليهم دالّ على أن إيمانهم لم يسبق به القدر، كما هو دالّ على أن الآيات المعجزات لا تستلزم الإيمان بالضرورة.", "التنديد بالإجرام، وهو إفساد النفس بالشرك والمعاصي."], "k": "«قالوا لنا هذه… يطّيّروا بموسى»… هل أنسب الخير لنفسي، والشر لغيري؟"}, {"lbl": "الآيات ١٣٤ – ١٣٧", "q": "وَلَمَّا وَقَعَ عَلَيۡهِمُ ٱلرِّجۡزُ قَالُواْ يَٰمُوسَى ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَۖ لَئِن كَشَفۡتَ عَنَّا ٱلرِّجۡزَ لَنُؤۡمِنَنَّ لَكَ وَلَنُرۡسِلَنَّ مَعَكَ بَنِيٓ إِسۡرَـٰٓءِيلَ ﴿١٣٤﴾ فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلرِّجۡزَ إِلَىٰٓ أَجَلٍ هُم بَٰلِغُوهُ إِذَا هُمۡ يَنكُثُونَ ﴿١٣٥﴾ فَٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ فِي ٱلۡيَمِّ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنۡهَا غَٰفِلِينَ ﴿١٣٦﴾ وَأَوۡرَثۡنَا ٱلۡقَوۡمَ ٱلَّذِينَ كَانُواْ يُسۡتَضۡعَفُونَ مَشَٰرِقَ ٱلۡأَرۡضِ وَمَغَٰرِبَهَا ٱلَّتِي بَٰرَكۡنَا فِيهَاۖ وَتَمَّتۡ كَلِمَتُ رَبِّكَ ٱلۡحُسۡنَىٰ عَلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ بِمَا صَبَرُواْۖ وَدَمَّرۡنَا مَا كَانَ يَصۡنَعُ فِرۡعَوۡنُ وَقَوۡمُهُۥ وَمَا كَانُواْ يَعۡرِشُونَ ﴿١٣٧﴾", "w": [["الرجز", "العذاب، وهو الخمسة المذكورة في الآية (١٣٣)."], ["إلى أجل هم بالغوه إذا هم ينكثون", "كانوا إذا سألوا موسى أن يدعو ربه ليرفع عنهم العذاب ووعدوا بالإيمان وإرسال بني إسرائيل، رفعه الله، فيمكثون زمناً، ثم يطالبهم موسى فيأبون وينكثون عهدهم."], ["فانتقمنا منهم", "أنزلنا بهم نقمتنا فأغرقناهم في اليم، وهو البحر."], ["الذين كانوا يُستضعفون", "هم بنو إسرائيل."], ["مشارق الأرض ومغاربها", "هي أرض مصر والشام."], ["وتمّت كلمة ربك الحسنى", "وعده تعالى لهم في قوله: «ونريد أن نمنّ على الذين استُضعفوا في الأرض ونجعلهم أئمة ونجعلهم الوارثين»."], ["وما كانوا يعرشون", "ما يرفعون من مباني الدور والقصور العالية."]], "m": "هذه الآيات الأخيرة في قصص موسى مع فرعون: ولما وقع عليهم العذاب: الطوفان فالجراد فالقمّل فالضفادع فالدم، قالوا: يا موسى ادعُ لنا ربك بما عهد عندك، لئن كشفت عنا الرجز لنؤمننّ لك ولنرسلنّ معك بني إسرائيل، فلما كشفنا عنهم الرجز إلى أجل هم بالغوه إذا هم ينكثون، وكان هذا بين كل آية وآية، حتى دقّت ساعة هلاكهم، فانتقمنا منهم فأغرقناهم في اليم: فرعون وجنده ورجال دولته وأشراف بلاده، بأنهم كذّبوا بآياتنا وكانوا عنها غافلين، كما هي حال قريش. وأورثنا بني إسرائيل الذين كانوا يُستضعفون مشارق الأرض ومغاربها التي باركنا فيها: أرض الشام أولاً، ثم مصر، إذ دخلوا فلسطين بعد وفاة موسى وهارون، غزا بهم يوشع بن نون العمالقة فيها، وتمّت كلمة ربك الحسنى على بني إسرائيل بما صبروا، ودمّرنا ما كان يصنع فرعون وقومه من سلاح وعتاد ومبانٍ شداد، وما كانوا يعرشون من صروح عالية وحدائق أعناب، وهنا انتهى قصص موسى مع فرعون وكانت العاقبة له.", "h": ["ضعف الإنسان يظهر عند نزول البلاء به، حيث يفزع إلى الله يدعوه ويضرع إليه، وعند رفعه حيث ينسى ما نزل به ويعود إلى ما كان عليه، إلا من آمن وعمل صالحاً فإنه يخرج من دائرة الضعف، حيث يصبر عند البلاء ويشكر عند الرخاء.", "سبب العذاب في الدنيا والآخرة التكذيب بآيات الله بعدم الإيمان والعمل بها، والغفلة عنها حيث لا يُتدبّر ولا يُتفكّر فيها وفيما نزلت لأجله.", "مظاهر قدرة الله، وصادق وعده، وعظيم منّته على خلقه، وحسن تدبيره فيهم، فسبحانه من إله عليم حكيم رؤوف رحيم."], "k": "«بما صبروا»… بالصبر ورث المستضعفون الأرض؛ فما الضيق الذي أحتاج أن أصبر عليه اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 108;
insert into public.tdb_cards(topic, i, body) select 108, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٢٣ – ١٢٦", "q": "قَالَ فِرۡعَوۡنُ ءَامَنتُم بِهِۦ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّ هَٰذَا لَمَكۡرٞ مَّكَرۡتُمُوهُ فِي ٱلۡمَدِينَةِ لِتُخۡرِجُواْ مِنۡهَآ أَهۡلَهَاۖ فَسَوۡفَ تَعۡلَمُونَ ﴿١٢٣﴾ لَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ ثُمَّ لَأُصَلِّبَنَّكُمۡ أَجۡمَعِينَ ﴿١٢٤﴾ قَالُوٓاْ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ ﴿١٢٥﴾ وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتۡنَاۚ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَتَوَفَّنَا مُسۡلِمِينَ ﴿١٢٦﴾", "w": [["آمنتم به", "صدّقتموه فيما جاء به ودعا إليه."], ["لمكر مكرتموه", "حيلة احتلتموها وتواطأتم مع موسى عليها."], ["من خلاف", "بأن يقطع اليد اليمنى والرجل اليسرى أو العكس."], ["ثم لأصلّبنّكم", "التصليب: الشد على خشبة حتى الموت."], ["منقلبون", "راجعون."], ["وما تنقم منا", "وما تكره منا وتنكر علينا إلا إيماننا بآيات ربنا لما جاءتنا."], ["أفرغ علينا صبراً", "أفض علينا صبراً قوياً حتى نثبت على ما توعّدنا به فرعون من العذاب، ولا نرتدّ بعد إيماننا."]], "m": "بعد أن آمن السحرة وسجدوا لله رب العالمين، حاكمهم فرعون: آمنتم به قبل أن آذن لكم؟ عبارة فيها رائحة الهزيمة والحمق، فالإيمان إذعان باطني لا علاقة له بالإذن. إن هذا لمكر مكرتموه مع موسى في المدينة قبل المباراة لتخرجوا منها أهلها وتستولوا عليها، فسوف تعلمون: لأقطّعنّ أيديكم وأرجلكم من خلاف، ثم لأصلّبنّكم أجمعين على الأخشاب نكالاً وعبرة. قالوا: إنا إلى ربنا منقلبون، فقتلك إيانا يقرّبنا من ربنا ونحن في شوق إلى لقائه، وما تنقم منا جرماً أجرمناه أو فساداً أشعناه، إلا أن آمنّا بآيات ربنا لما جاءتنا، وهذا لا عار فيه، ثم أقبلوا على الله ضارعين: ربنا أفرغ علينا صبراً حتى نتحمّل العذاب في ذاتك، وتوفّنا مسلمين. ونفّذ فرعون جريمته، ولكن أحدث ذلك اضطراباً في البلاد لم يكن يتوقّعه.", "h": ["القلوب المظلمة بالكفر والجرائم أصحابها لا يتورّعون عن الكذب واتهام الأبرياء.", "فضيلة الاسترجاع: أن يقول «إنا لله وإنا إليه راجعون»، حيث فزع إليها السحرة لما هدّدهم فرعون، إذ قالوا: «إنا إلى ربنا منقلبون»، فهان عليهم ما هُدّدوا به.", "مشروعية سؤال الصبر على البلاء للثبات على الإيمان.", "فضل الوفاة على الإسلام، وأنه مطلب عالٍ لأهل الإيمان."], "k": "«وتوفّنا مسلمين»… هل أسأل ربي حسن الخاتمة كل يوم كما سألها السحرة في ساعتهم الأولى؟"}, {"lbl": "الآيات ١٢٧ – ١٢٩", "q": "وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ أَتَذَرُ مُوسَىٰ وَقَوۡمَهُۥ لِيُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَيَذَرَكَ وَءَالِهَتَكَۚ قَالَ سَنُقَتِّلُ أَبۡنَآءَهُمۡ وَنَسۡتَحۡيِۦ نِسَآءَهُمۡ وَإِنَّا فَوۡقَهُمۡ قَٰهِرُونَ ﴿١٢٧﴾ قَالَ مُوسَىٰ لِقَوۡمِهِ ٱسۡتَعِينُواْ بِٱللَّهِ وَٱصۡبِرُوٓاْۖ إِنَّ ٱلۡأَرۡضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ ﴿١٢٨﴾ قَالُوٓاْ أُوذِينَا مِن قَبۡلِ أَن تَأۡتِيَنَا وَمِنۢ بَعۡدِ مَا جِئۡتَنَاۚ قَالَ عَسَىٰ رَبُّكُمۡ أَن يُهۡلِكَ عَدُوَّكُمۡ وَيَسۡتَخۡلِفَكُمۡ فِي ٱلۡأَرۡضِ فَيَنظُرَ كَيۡفَ تَعۡمَلُونَ ﴿١٢٩﴾", "w": [["قال الملأ", "أي لفرعون."], ["وقومه", "أي بني إسرائيل."], ["ليفسدوا في الأرض", "في البلاد، بالدعوة إلى مخالفتك وترك طاعتك."], ["وآلهتك", "أصناماً صغاراً وضعها ليعبدها الناس، وقال: أنا ربكم الأعلى."], ["نستحيي نساءهم", "نُبقي على نسائهم لا نذبحهنّ كما نذبح الأطفال الذكور."], ["ويستخلفكم في الأرض", "يجعلكم خلفاء فيها تخلفون الظالمين بعد هلاكهم."]], "m": "بعد انتصار موسى وإيمان السحرة ظهر أمره واتبعه ستمائة ألف من بني إسرائيل، فخاف قوم فرعون وقالوا محرّضين: أتذر موسى وقومه ليفسدوا في أرض مصر بالدعوة إلى مخالفتك، ويذرك وآلهتك التي كنت تدعو الناس لعبادتها لتقرّبهم إليك؟ قال فرعون: سنقتّل أبناءهم ونستحيي نساءهم كما كنا نفعل، وإنا فوقهم قاهرون، كلمة يعوّض بها ما فقد من جبروته بعد هزيمته. فقال موسى لقومه وقد أرعبهم التهديد: استعينوا بالله على ما قد ينالكم من ظلم فرعون، واصبروا، إن الأرض لله يورثها من يشاء من عباده والعاقبة للمتقين، فمتى صبرتم واتقيتم أهلك عدوكم وأورثكم أرضه، وقد تم ذلك حرفياً. قالوا بكلمة الآيس المهزوم نفسياً لطول ما عانوا: أوذينا من قبل أن تأتينا ومن بعد ما جئتنا، فأحيا موسى الأمل في نفوسهم: عسى ربكم أن يهلك عدوكم ويستخلفكم في الأرض فينظر كيف تعملون، وقد تم ذلك كاملاً بلا نقصان.", "h": ["خطر بطانة السوء على الملوك والرؤساء، تجلّت في إثارة فرعون ودفعه إلى البطش بقولهم: «أتذر موسى وقومه ليفسدوا في الأرض…».", "بيان فضيلة الصبر والتقوى، وأنهما مفتاح النصر وإكسير الكمال البشري.", "النفوس المريضة علاجها عسير، ولكن بالصبر والمثابرة تُشفى إن شاء الله تعالى.", "بيان صدق ما رجاه موسى من ربه، حيث تحقّق بحذافيره.", "استحسان رفع معنويات المؤمنين بذكر حسن العاقبة، والتبشير بوعد الله لأوليائه أهل الإيمان والتقوى."], "k": "«فينظر كيف تعملون»… إن مكّنني الله في شيء بعد ضيق، فكيف سيجدني أعمل؟"}, {"lbl": "الآيات ١٣٠ – ١٣٣", "q": "وَلَقَدۡ أَخَذۡنَآ ءَالَ فِرۡعَوۡنَ بِٱلسِّنِينَ وَنَقۡصٖ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَذَّكَّرُونَ ﴿١٣٠﴾ فَإِذَا جَآءَتۡهُمُ ٱلۡحَسَنَةُ قَالُواْ لَنَا هَٰذِهِۦۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَطَّيَّرُواْ بِمُوسَىٰ وَمَن مَّعَهُۥٓۗ أَلَآ إِنَّمَا طَـٰٓئِرُهُمۡ عِندَ ٱللَّهِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿١٣١﴾ وَقَالُواْ مَهۡمَا تَأۡتِنَا بِهِۦ مِنۡ ءَايَةٖ لِّتَسۡحَرَنَا بِهَا فَمَا نَحۡنُ لَكَ بِمُؤۡمِنِينَ ﴿١٣٢﴾ فَأَرۡسَلۡنَا عَلَيۡهِمُ ٱلطُّوفَانَ وَٱلۡجَرَادَ وَٱلۡقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٖ مُّفَصَّلَٰتٖ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ ﴿١٣٣﴾", "w": [["أخذنا آل فرعون بالسنين", "عاقبناهم بسني الجدب والقحط."], ["الحسنة", "ما يحسن من خصب ورخاء وكثرة رزق وعافية."], ["سيئة", "ضد الحسنة، وهي الجدب والغلاء والمرض."], ["يطّيّروا بموسى", "يتشاءموا بموسى وقومه."], ["الطوفان والجراد", "الطوفان: الفيضانات المغرقة، والجراد معروف بأكل الزرع والثمار."], ["والقمّل والضفادع", "القمّل يجوز أن يكون القمل المعروف، أو السوس في الحبوب، والضفادع حيوان يوجد في المياه والمستنقعات."], ["والدم", "قد يكون دم رعاف أو نزيف، أو تحوّل ماء الشرب إلى دم عبيط في أوانيهم وأفواههم، آية لموسى ﵇."], ["فاستكبروا وكانوا قوماً مجرمين", "حيث لم يؤمنوا بهذه الآيات، مفسدين حيث حُكم بإهلاكهم."]], "m": "لما حملهم الكبر على مواصلة الكفر، أصابهم الرب بجفاف وقحط سنوات لعلهم يذّكّرون، فلم يذّكّروا، فحوّل جدبهم خصباً وبلاءهم عافية، فقالوا في الرخاء: هذه لنا نحن مستحقّوها، وفي البلاء: هذه من شؤم موسى ومن معه، ألا إنما طائرهم عند الله، فهو جاعل للحسنة أسبابها وهي الإيمان والتقوى، وللسيئة أسبابها وهي الكفر والمعاصي، ولكن أكثرهم لا يعلمون. ولجّوا في العناد: مهما تأتنا به من آية لتسحرنا بها فما نحن لك بمؤمنين. فدعا موسى ربه: يا رب إن فرعون علا في الأرض وبغى، وإن قومه نقضوا العهد، فخذهم بعقوبة تكون لهم نقمة ولقومي عظة ولمن بعدهم آية، فأرسل عليهم الطوفان فكادوا يغرقون، فجاؤوا موسى يطلبون رفعه ويعدون بالإيمان وإرسال بني إسرائيل، فرُفع عنهم فتنكّروا، ثم الجراد فأكل زروعهم وثمارهم، فوعدوا ثم نكثوا، وهكذا حتى تمّت الآيات الخمس مفصّلات، فاستكبروا وكانوا قوماً مجرمين لا خير فيهم ولا عهد لهم.", "h": ["من تدبير الله تعالى أخذه عباده بالشدائد لعلهم يذّكّرون فيتّعظون ويتوبون.", "بطلان التطيّر مطلقاً، وإنما الشؤم في المعاصي بمخالفة شرع الله، فيترتّب على الفسق والعصيان البلاء والعذاب.", "الجهل سبب الكفر والمعاصي، وسوء الأخلاق، وفساد الأحوال.", "عدم إيمان آل فرعون مع توارد الآيات عليهم دالّ على أن إيمانهم لم يسبق به القدر، كما هو دالّ على أن الآيات المعجزات لا تستلزم الإيمان بالضرورة.", "التنديد بالإجرام، وهو إفساد النفس بالشرك والمعاصي."], "k": "«قالوا لنا هذه… يطّيّروا بموسى»… هل أنسب الخير لنفسي، والشر لغيري؟"}, {"lbl": "الآيات ١٣٤ – ١٣٧", "q": "وَلَمَّا وَقَعَ عَلَيۡهِمُ ٱلرِّجۡزُ قَالُواْ يَٰمُوسَى ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَۖ لَئِن كَشَفۡتَ عَنَّا ٱلرِّجۡزَ لَنُؤۡمِنَنَّ لَكَ وَلَنُرۡسِلَنَّ مَعَكَ بَنِيٓ إِسۡرَـٰٓءِيلَ ﴿١٣٤﴾ فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلرِّجۡزَ إِلَىٰٓ أَجَلٍ هُم بَٰلِغُوهُ إِذَا هُمۡ يَنكُثُونَ ﴿١٣٥﴾ فَٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ فِي ٱلۡيَمِّ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنۡهَا غَٰفِلِينَ ﴿١٣٦﴾ وَأَوۡرَثۡنَا ٱلۡقَوۡمَ ٱلَّذِينَ كَانُواْ يُسۡتَضۡعَفُونَ مَشَٰرِقَ ٱلۡأَرۡضِ وَمَغَٰرِبَهَا ٱلَّتِي بَٰرَكۡنَا فِيهَاۖ وَتَمَّتۡ كَلِمَتُ رَبِّكَ ٱلۡحُسۡنَىٰ عَلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ بِمَا صَبَرُواْۖ وَدَمَّرۡنَا مَا كَانَ يَصۡنَعُ فِرۡعَوۡنُ وَقَوۡمُهُۥ وَمَا كَانُواْ يَعۡرِشُونَ ﴿١٣٧﴾", "w": [["الرجز", "العذاب، وهو الخمسة المذكورة في الآية (١٣٣)."], ["إلى أجل هم بالغوه إذا هم ينكثون", "كانوا إذا سألوا موسى أن يدعو ربه ليرفع عنهم العذاب ووعدوا بالإيمان وإرسال بني إسرائيل، رفعه الله، فيمكثون زمناً، ثم يطالبهم موسى فيأبون وينكثون عهدهم."], ["فانتقمنا منهم", "أنزلنا بهم نقمتنا فأغرقناهم في اليم، وهو البحر."], ["الذين كانوا يُستضعفون", "هم بنو إسرائيل."], ["مشارق الأرض ومغاربها", "هي أرض مصر والشام."], ["وتمّت كلمة ربك الحسنى", "وعده تعالى لهم في قوله: «ونريد أن نمنّ على الذين استُضعفوا في الأرض ونجعلهم أئمة ونجعلهم الوارثين»."], ["وما كانوا يعرشون", "ما يرفعون من مباني الدور والقصور العالية."]], "m": "هذه الآيات الأخيرة في قصص موسى مع فرعون: ولما وقع عليهم العذاب: الطوفان فالجراد فالقمّل فالضفادع فالدم، قالوا: يا موسى ادعُ لنا ربك بما عهد عندك، لئن كشفت عنا الرجز لنؤمننّ لك ولنرسلنّ معك بني إسرائيل، فلما كشفنا عنهم الرجز إلى أجل هم بالغوه إذا هم ينكثون، وكان هذا بين كل آية وآية، حتى دقّت ساعة هلاكهم، فانتقمنا منهم فأغرقناهم في اليم: فرعون وجنده ورجال دولته وأشراف بلاده، بأنهم كذّبوا بآياتنا وكانوا عنها غافلين، كما هي حال قريش. وأورثنا بني إسرائيل الذين كانوا يُستضعفون مشارق الأرض ومغاربها التي باركنا فيها: أرض الشام أولاً، ثم مصر، إذ دخلوا فلسطين بعد وفاة موسى وهارون، غزا بهم يوشع بن نون العمالقة فيها، وتمّت كلمة ربك الحسنى على بني إسرائيل بما صبروا، ودمّرنا ما كان يصنع فرعون وقومه من سلاح وعتاد ومبانٍ شداد، وما كانوا يعرشون من صروح عالية وحدائق أعناب، وهنا انتهى قصص موسى مع فرعون وكانت العاقبة له.", "h": ["ضعف الإنسان يظهر عند نزول البلاء به، حيث يفزع إلى الله يدعوه ويضرع إليه، وعند رفعه حيث ينسى ما نزل به ويعود إلى ما كان عليه، إلا من آمن وعمل صالحاً فإنه يخرج من دائرة الضعف، حيث يصبر عند البلاء ويشكر عند الرخاء.", "سبب العذاب في الدنيا والآخرة التكذيب بآيات الله بعدم الإيمان والعمل بها، والغفلة عنها حيث لا يُتدبّر ولا يُتفكّر فيها وفيما نزلت لأجله.", "مظاهر قدرة الله، وصادق وعده، وعظيم منّته على خلقه، وحسن تدبيره فيهم، فسبحانه من إله عليم حكيم رؤوف رحيم."], "k": "«بما صبروا»… بالصبر ورث المستضعفون الأرض؛ فما الضيق الذي أحتاج أن أصبر عليه اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (109, 7, 138, 149, 'سورة الأعراف ١٣٨ – ١٤٩', '«اجعل لنا إلهاً»، ميقات موسى ﵇ و«رب أرني أنظر إليك»، وعجل بني إسرائيل', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 109) = $j$[{"lbl": "الآيات ١٣٨ – ١٤١", "q": "وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَـٰٓءِيلَ ٱلۡبَحۡرَ فَأَتَوۡاْ عَلَىٰ قَوۡمٖ يَعۡكُفُونَ عَلَىٰٓ أَصۡنَامٖ لَّهُمۡۚ قَالُواْ يَٰمُوسَى ٱجۡعَل لَّنَآ إِلَٰهٗا كَمَا لَهُمۡ ءَالِهَةٞۚ قَالَ إِنَّكُمۡ قَوۡمٞ تَجۡهَلُونَ ﴿١٣٨﴾ إِنَّ هَـٰٓؤُلَآءِ مُتَبَّرٞ مَّا هُمۡ فِيهِ وَبَٰطِلٞ مَّا كَانُواْ يَعۡمَلُونَ ﴿١٣٩﴾ قَالَ أَغَيۡرَ ٱللَّهِ أَبۡغِيكُمۡ إِلَٰهٗا وَهُوَ فَضَّلَكُمۡ عَلَى ٱلۡعَٰلَمِينَ ﴿١٤٠﴾ وَإِذۡ أَنجَيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ يُقَتِّلُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ ﴿١٤١﴾", "w": [["وجاوزنا ببني إسرائيل البحر", "قطعنا بهم البحر فاجتازوه إلى ساحله."], ["يعكفون على أصنام لهم", "يجلسون إلى تماثيل بقر منحوتة من حجر."], ["اجعل لنا إلهاً", "معبوداً، يريدون تمثالاً كالذي شاهدوا."], ["تجهلون", "أي أن العبادة لا تكون إلا لله تعالى."], ["وإذ نجّيناكم", "اذكروا نعم الله عليكم بإنجائه إياكم من آل فرعون."], ["يسومونكم سوء العذاب", "يوردونكم موارد الردى والهلاك بما يصيبونكم به من عذاب."]], "m": "هذه بداية قصص جديد لموسى مع قومه بعد هلاك فرعون: لما جاوز الله ببني إسرائيل البحر ونزلوا على شاطئه سالمين، مرّوا بأناس يعكفون على تماثيل أبقار حجرية يعبدونها، فقالوا: يا موسى اجعل لنا إلهاً كما لهم آلهة، كلمة دالة على جهل بالله وآياته، فجابههم: إنكم قوم تجهلون، إن هؤلاء متبّر ما هم فيه، في هلاك وخسار، وباطل ما كانوا يعملون، أغير الله أطلب لكم إلهاً، وهو فضّلكم على العالمين؟ أهكذا يكون شكركم؟ واذكروا إذ أنجيناكم من آل فرعون، رجال حكمه وشرطه وجيوشه، يسومونكم سوء العذاب، يقتّلون أبناءكم حتى لا تكثروا، ويستحيون نساءكم للامتهان والخدمة، وفي ذلكم التعذيب والإنجاء منه بلاء من ربكم عظيم يتطلّب شكركم لا كفركم.", "h": ["طلب بني إسرائيل من موسى ﵇ أن يجعل لهم إلهاً دالّ على جهل تام، فالعلة في هذا الطلب العجيب هي الجهل بالله تعالى وأسمائه وصفاته، يشهد لهذا أن مسلمة الفتح لما خرج بهم رسول الله ﷺ إلى حنين مرّوا بسدرة فقالوا: اجعل لنا ذات أنواط كما لهم ذات أنواط، فقال: «سبحان الله! ما زدتم أن قلتم كما قال بنو إسرائيل لموسى: اجعل لنا إلهاً كما لهم آلهة»، ويشهد لذلك أن آلاف الأشجار والمزارات في بلاد المسلمين تُزار ويُتبرّك بها وتُقدّم لها القرابين، ولا علة لذلك سوى جهل المسلمين بربهم عز وجل.", "إنكار المنكر عند وجوده والعثور عليه، بالأسلوب الذي يغيّره.", "استحباب التذكير بأيام الله، خيرها وشرها، لاستجلاب الموعظة للناس لعلهم يتوبون.", "الرب تعالى يبتلي بالخير والشر، وفي كل ذلك خير لمن صبر وشكر."], "k": "«اجعل لنا إلهاً كما لهم آلهة»… هل أقلّد الناس فيما يعظّمونه، دون أن أزنه بالتوحيد؟"}, {"lbl": "الآيات ١٤٢ – ١٤٥", "q": "۞وَوَٰعَدۡنَا مُوسَىٰ ثَلَٰثِينَ لَيۡلَةٗ وَأَتۡمَمۡنَٰهَا بِعَشۡرٖ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرۡبَعِينَ لَيۡلَةٗۚ وَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخۡلُفۡنِي فِي قَوۡمِي وَأَصۡلِحۡ وَلَا تَتَّبِعۡ سَبِيلَ ٱلۡمُفۡسِدِينَ ﴿١٤٢﴾ وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِيٓ أَنظُرۡ إِلَيۡكَۚ قَالَ لَن تَرَىٰنِي وَلَٰكِنِ ٱنظُرۡ إِلَى ٱلۡجَبَلِ فَإِنِ ٱسۡتَقَرَّ مَكَانَهُۥ فَسَوۡفَ تَرَىٰنِيۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلۡجَبَلِ جَعَلَهُۥ دَكّٗا وَخَرَّ مُوسَىٰ صَعِقٗاۚ فَلَمَّآ أَفَاقَ قَالَ سُبۡحَٰنَكَ تُبۡتُ إِلَيۡكَ وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِينَ ﴿١٤٣﴾ قَالَ يَٰمُوسَىٰٓ إِنِّي ٱصۡطَفَيۡتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِي وَبِكَلَٰمِي فَخُذۡ مَآ ءَاتَيۡتُكَ وَكُن مِّنَ ٱلشَّـٰكِرِينَ ﴿١٤٤﴾ وَكَتَبۡنَا لَهُۥ فِي ٱلۡأَلۡوَاحِ مِن كُلِّ شَيۡءٖ مَّوۡعِظَةٗ وَتَفۡصِيلٗا لِّكُلِّ شَيۡءٖ فَخُذۡهَا بِقُوَّةٖ وَأۡمُرۡ قَوۡمَكَ يَأۡخُذُواْ بِأَحۡسَنِهَاۚ سَأُوْرِيكُمۡ دَارَ ٱلۡفَٰسِقِينَ ﴿١٤٥﴾", "w": [["ميقات", "الميقات: الوقت المعيّن."], ["اخلفني في قومي", "كن خليفتي فيهم."], ["المفسدين", "الذين يعملون بالمعاصي."], ["استقرّ مكانه", "ثبت ولم يتحوّل."], ["وخرّ", "سقط على الأرض."], ["أفاق", "ذهب عنه الإغماء وعاد إليه وعيه."], ["اصطفيتك", "اخترتك."]], "m": "بعد أن أدّب موسى قومه على طلبهم الباطل، واعده ربه أن يناجيه بجبل الطور ثلاثين ليلة، وكانت شهر ذي القعدة، وأتمّها بعشر من ذي الحجة، فتم ميقات ربه أربعين ليلة، واستخلف أخاه هارون: اخلفني في قومي وأصلح ولا تتبع سبيل المفسدين، وكان ذلك ليأتيهم بكتاب يتضمّن شريعة كاملة يُساسون بها. ولما جاء موسى لميقاتنا وكلّمه ربه بلا واسطة، يسمع كلامه ولا يرى ذاته، تاقت نفسه لرؤيته فقال: رب أرني أنظر إليك، قال: لن تراني، ولكن انظر إلى جبل الطور فإن استقر مكانه بعد أن أتجلّى له فسوف تراني، فلما تجلّى ربه للجبل جعله دكاً، وخرّ موسى صعقاً مغشياً عليه، فلما أفاق قال: سبحانك تنزيهاً لك، تبت إليك فلا أسألك مثل هذا، وأنا أول المؤمنين بك وبجلالك، وأنا عاجز عن رؤيتك في دار التكليف. قال: يا موسى إني اصطفيتك على الناس برسالاتي وبكلامي، فخذ ما آتيتك وكن من الشاكرين بطاعتي. وكتبنا له في الألواح من كل شيء من أمور الدين والدنيا موعظة وتفصيلاً لكل شيء، فخذها بقوة، بعزم وجد في العمل بحلالها وحرامها، وأمر قومك يأخذوا بأحسنها، بعزائمها لا برخصها، تعويداً لهم على تحمّل العظائم بعد طول ضعف، سأريكم دار الفاسقين: وعيد لمن ترك شرائع الألواح بأن جزاءه جهنم.", "h": ["المحافظة على المواعيد أمر محبوب للشارع، مرغّب فيه، وهو من سمات الصادقين.", "جواز الاستخلاف في الأرض في مهام الأمور، فضلاً عما هو دون ذلك.", "مشروعية الوصية للخلفاء بما هو خير.", "إمكان رؤية الله تعالى، وهي ثابتة في الآخرة لأهل الجنة.", "استحالة رؤية الله تعالى في الدنيا لضعف الإنسان عن ذلك.", "وجود الأمة القابلة لأحكام الله قبل وجود الشرع الذي يحكمها."], "k": "«فخذها بقوة»… هل آخذ ديني بعزم وجد، أم أبحث دائماً عن أسهل الرخص؟"}, {"lbl": "الآيتان ١٤٦ – ١٤٧", "q": "سَأَصۡرِفُ عَنۡ ءَايَٰتِيَ ٱلَّذِينَ يَتَكَبَّرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَا وَإِن يَرَوۡاْ سَبِيلَ ٱلرُّشۡدِ لَا يَتَّخِذُوهُ سَبِيلٗا وَإِن يَرَوۡاْ سَبِيلَ ٱلۡغَيِّ يَتَّخِذُوهُ سَبِيلٗاۚ ذَٰلِكَ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنۡهَا غَٰفِلِينَ ﴿١٤٦﴾ وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآءِ ٱلۡأٓخِرَةِ حَبِطَتۡ أَعۡمَٰلُهُمۡۚ هَلۡ يُجۡزَوۡنَ إِلَّا مَا كَانُواْ يَعۡمَلُونَ ﴿١٤٧﴾", "w": [["يتكبّرون", "يعلون ويترفّعون، فيمنعون الحقوق ويحتقرون الناس."], ["سبيل الغيّ", "طريق الضلال القائم على الشرك والمعاصي."], ["وكانوا عنها غافلين", "لا يلتفتون إليها ولا ينظرون فيها، ولا يتفكّرون فيما تدل عليه."], ["حبطت أعمالهم", "فسدت فلا ينتفعون بها، لأنها أعمال مشرك، والشرك محبط للعمل."]], "m": "هاتان الآيتان تحملان تعليلاً صائباً لكل انحراف وفساد وظلم وقع في الأرض ويقع إلى نهاية الحياة، وهو التكذيب بآيات الله والغفلة عنها، سواء كان الحامل عليه الكبر أو الظلم أو التقليد أو العناد، إلا أن الكبر أقوى عوامل الصرف عنها: سأصرف عن آياتي الذين يتكبّرون في الأرض بغير الحق، ومن صرفه الله حسب سنته لا يقبل ولا يرجع. وإن يروا كل آية لا يؤمنوا بها، وإن يروا سبيل الرشد لا يتخذوه سبيلاً، وإن يروا سبيل الغي يتخذوه سبيلاً، ذلك بأنهم كذّبوا بآياتنا وكانوا عنها غافلين غير مبالين بها. والذين كذّبوا بآياتنا ولقاء الآخرة حبطت أعمالهم، إذ لم تقم على العدل والحق، فهي باطلة لا تكسبهم خيراً، وهي أعمال سوء يُجزون بها، هل يُجزون إلا ما كانوا يعملون؟", "h": ["بيان سنة الله تعالى في صرف العباد عن آيات الله حتى يهلكوا كما هلك فرعون وآله.", "من أقوى عوامل الصرف عن آيات الله الكبر.", "التكذيب بآيات الله والغفلة عنها هما سبب كل ضلال وشر وظلم وفساد.", "بطلان كل عمل لم يسلك فيه صاحبه سبيل الرشد، التي هي سبيل الله التي تحدّدها الآيات القرآنية وتبيّن معالمها وترفع أعلامها."], "k": "«سأصرف عن آياتي الذين يتكبّرون»… هل في قلبي كبر يحجبني عن آية تدعوني إلى التغيير؟"}, {"lbl": "الآيتان ١٤٨ – ١٤٩", "q": "وَٱتَّخَذَ قَوۡمُ مُوسَىٰ مِنۢ بَعۡدِهِۦ مِنۡ حُلِيِّهِمۡ عِجۡلٗا جَسَدٗا لَّهُۥ خُوَارٌۚ أَلَمۡ يَرَوۡاْ أَنَّهُۥ لَا يُكَلِّمُهُمۡ وَلَا يَهۡدِيهِمۡ سَبِيلًاۘ ٱتَّخَذُوهُ وَكَانُواْ ظَٰلِمِينَ ﴿١٤٨﴾ وَلَمَّا سُقِطَ فِيٓ أَيۡدِيهِمۡ وَرَأَوۡاْ أَنَّهُمۡ قَدۡ ضَلُّواْ قَالُواْ لَئِن لَّمۡ يَرۡحَمۡنَا رَبُّنَا وَيَغۡفِرۡ لَنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ﴿١٤٩﴾", "w": [["من حُليّهم", "جمع حَلْي، وهو ما تتحلّى به المرأة لزوجها من أساور ونحوها."], ["عجلاً جسداً", "العجل ولد البقرة، والجسد: ذاتاً لا مجرد صورة."], ["له خوار", "الخوار صوت البقر، كالرغاء صوت الإبل."], ["ولما سُقط في أيديهم", "ندموا على عبادته لأنها عبادة باطلة."]], "m": "بعد أن اعترض السياق ببيان سبب هلاك العباد، عاد إلى قصص موسى: واتخذ قوم موسى من بعد غيبته في جبل الطور من حليّ نسائهم عجلاً جسداً له خوار، وذلك أن السامري طلب من نسائهم حليّهم بحجة واهية أنه مستعار من نساء الأقباط ولا يحل تملّكه، وكان صائغاً، فصهره وأخرج لهم منه عجلاً ذاتاً له صوت كصوت البقر، وقال: هذا إلهكم وإله موسى، ولم يقل وإله هارون خوفاً أن يكذّبه وهو معهم. ألم يروا أنه لا يكلّمهم ولا يهديهم سبيلاً؟ توبيخ لغباوتهم، اتخذوه إلهاً وكانوا ظالمين. ولما انكشف لهم خطؤهم ندموا ندماً شديداً ورأوا أنهم قد ضلّوا، فصاحوا معلنين توبتهم: لئن لم يرحمنا ربنا ويغفر لنا هذا الذنب العظيم لنكوننّ من الخاسرين.", "h": ["بيان سنة من سنن الكون، وهي أن المرء يتأثّر بما يرى ويسمع، والرؤية أكثر تأثيراً في النفس من السماع، فرؤية بني إسرائيل للأبقار الآلهة هي التي جعلتهم يقبلون عجل السامري، ومن هنا كان منظر الأشياء في التلفاز وشاشات الفيديو مؤثّراً جداً، وكم أفسد من عقول، ولوّث من نفوس، وأفسد من أخلاق.", "تقبيح الغباء والجمود في الفكر، وذلك لقول الله تعالى: «ألم يروا أنه لا يكلّمهم».", "إذا أراد الله بعبده خيراً ألهمه التوبة بعد المعصية، فندم واستغفر."], "k": "«لئن لم يرحمنا ربنا ويغفر لنا»… هل أسرع إلى الندم والاستغفار حين أكتشف خطئي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 109;
insert into public.tdb_cards(topic, i, body) select 109, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٣٨ – ١٤١", "q": "وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَـٰٓءِيلَ ٱلۡبَحۡرَ فَأَتَوۡاْ عَلَىٰ قَوۡمٖ يَعۡكُفُونَ عَلَىٰٓ أَصۡنَامٖ لَّهُمۡۚ قَالُواْ يَٰمُوسَى ٱجۡعَل لَّنَآ إِلَٰهٗا كَمَا لَهُمۡ ءَالِهَةٞۚ قَالَ إِنَّكُمۡ قَوۡمٞ تَجۡهَلُونَ ﴿١٣٨﴾ إِنَّ هَـٰٓؤُلَآءِ مُتَبَّرٞ مَّا هُمۡ فِيهِ وَبَٰطِلٞ مَّا كَانُواْ يَعۡمَلُونَ ﴿١٣٩﴾ قَالَ أَغَيۡرَ ٱللَّهِ أَبۡغِيكُمۡ إِلَٰهٗا وَهُوَ فَضَّلَكُمۡ عَلَى ٱلۡعَٰلَمِينَ ﴿١٤٠﴾ وَإِذۡ أَنجَيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ يُقَتِّلُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ ﴿١٤١﴾", "w": [["وجاوزنا ببني إسرائيل البحر", "قطعنا بهم البحر فاجتازوه إلى ساحله."], ["يعكفون على أصنام لهم", "يجلسون إلى تماثيل بقر منحوتة من حجر."], ["اجعل لنا إلهاً", "معبوداً، يريدون تمثالاً كالذي شاهدوا."], ["تجهلون", "أي أن العبادة لا تكون إلا لله تعالى."], ["وإذ نجّيناكم", "اذكروا نعم الله عليكم بإنجائه إياكم من آل فرعون."], ["يسومونكم سوء العذاب", "يوردونكم موارد الردى والهلاك بما يصيبونكم به من عذاب."]], "m": "هذه بداية قصص جديد لموسى مع قومه بعد هلاك فرعون: لما جاوز الله ببني إسرائيل البحر ونزلوا على شاطئه سالمين، مرّوا بأناس يعكفون على تماثيل أبقار حجرية يعبدونها، فقالوا: يا موسى اجعل لنا إلهاً كما لهم آلهة، كلمة دالة على جهل بالله وآياته، فجابههم: إنكم قوم تجهلون، إن هؤلاء متبّر ما هم فيه، في هلاك وخسار، وباطل ما كانوا يعملون، أغير الله أطلب لكم إلهاً، وهو فضّلكم على العالمين؟ أهكذا يكون شكركم؟ واذكروا إذ أنجيناكم من آل فرعون، رجال حكمه وشرطه وجيوشه، يسومونكم سوء العذاب، يقتّلون أبناءكم حتى لا تكثروا، ويستحيون نساءكم للامتهان والخدمة، وفي ذلكم التعذيب والإنجاء منه بلاء من ربكم عظيم يتطلّب شكركم لا كفركم.", "h": ["طلب بني إسرائيل من موسى ﵇ أن يجعل لهم إلهاً دالّ على جهل تام، فالعلة في هذا الطلب العجيب هي الجهل بالله تعالى وأسمائه وصفاته، يشهد لهذا أن مسلمة الفتح لما خرج بهم رسول الله ﷺ إلى حنين مرّوا بسدرة فقالوا: اجعل لنا ذات أنواط كما لهم ذات أنواط، فقال: «سبحان الله! ما زدتم أن قلتم كما قال بنو إسرائيل لموسى: اجعل لنا إلهاً كما لهم آلهة»، ويشهد لذلك أن آلاف الأشجار والمزارات في بلاد المسلمين تُزار ويُتبرّك بها وتُقدّم لها القرابين، ولا علة لذلك سوى جهل المسلمين بربهم عز وجل.", "إنكار المنكر عند وجوده والعثور عليه، بالأسلوب الذي يغيّره.", "استحباب التذكير بأيام الله، خيرها وشرها، لاستجلاب الموعظة للناس لعلهم يتوبون.", "الرب تعالى يبتلي بالخير والشر، وفي كل ذلك خير لمن صبر وشكر."], "k": "«اجعل لنا إلهاً كما لهم آلهة»… هل أقلّد الناس فيما يعظّمونه، دون أن أزنه بالتوحيد؟"}, {"lbl": "الآيات ١٤٢ – ١٤٥", "q": "۞وَوَٰعَدۡنَا مُوسَىٰ ثَلَٰثِينَ لَيۡلَةٗ وَأَتۡمَمۡنَٰهَا بِعَشۡرٖ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرۡبَعِينَ لَيۡلَةٗۚ وَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخۡلُفۡنِي فِي قَوۡمِي وَأَصۡلِحۡ وَلَا تَتَّبِعۡ سَبِيلَ ٱلۡمُفۡسِدِينَ ﴿١٤٢﴾ وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِيٓ أَنظُرۡ إِلَيۡكَۚ قَالَ لَن تَرَىٰنِي وَلَٰكِنِ ٱنظُرۡ إِلَى ٱلۡجَبَلِ فَإِنِ ٱسۡتَقَرَّ مَكَانَهُۥ فَسَوۡفَ تَرَىٰنِيۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلۡجَبَلِ جَعَلَهُۥ دَكّٗا وَخَرَّ مُوسَىٰ صَعِقٗاۚ فَلَمَّآ أَفَاقَ قَالَ سُبۡحَٰنَكَ تُبۡتُ إِلَيۡكَ وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِينَ ﴿١٤٣﴾ قَالَ يَٰمُوسَىٰٓ إِنِّي ٱصۡطَفَيۡتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِي وَبِكَلَٰمِي فَخُذۡ مَآ ءَاتَيۡتُكَ وَكُن مِّنَ ٱلشَّـٰكِرِينَ ﴿١٤٤﴾ وَكَتَبۡنَا لَهُۥ فِي ٱلۡأَلۡوَاحِ مِن كُلِّ شَيۡءٖ مَّوۡعِظَةٗ وَتَفۡصِيلٗا لِّكُلِّ شَيۡءٖ فَخُذۡهَا بِقُوَّةٖ وَأۡمُرۡ قَوۡمَكَ يَأۡخُذُواْ بِأَحۡسَنِهَاۚ سَأُوْرِيكُمۡ دَارَ ٱلۡفَٰسِقِينَ ﴿١٤٥﴾", "w": [["ميقات", "الميقات: الوقت المعيّن."], ["اخلفني في قومي", "كن خليفتي فيهم."], ["المفسدين", "الذين يعملون بالمعاصي."], ["استقرّ مكانه", "ثبت ولم يتحوّل."], ["وخرّ", "سقط على الأرض."], ["أفاق", "ذهب عنه الإغماء وعاد إليه وعيه."], ["اصطفيتك", "اخترتك."]], "m": "بعد أن أدّب موسى قومه على طلبهم الباطل، واعده ربه أن يناجيه بجبل الطور ثلاثين ليلة، وكانت شهر ذي القعدة، وأتمّها بعشر من ذي الحجة، فتم ميقات ربه أربعين ليلة، واستخلف أخاه هارون: اخلفني في قومي وأصلح ولا تتبع سبيل المفسدين، وكان ذلك ليأتيهم بكتاب يتضمّن شريعة كاملة يُساسون بها. ولما جاء موسى لميقاتنا وكلّمه ربه بلا واسطة، يسمع كلامه ولا يرى ذاته، تاقت نفسه لرؤيته فقال: رب أرني أنظر إليك، قال: لن تراني، ولكن انظر إلى جبل الطور فإن استقر مكانه بعد أن أتجلّى له فسوف تراني، فلما تجلّى ربه للجبل جعله دكاً، وخرّ موسى صعقاً مغشياً عليه، فلما أفاق قال: سبحانك تنزيهاً لك، تبت إليك فلا أسألك مثل هذا، وأنا أول المؤمنين بك وبجلالك، وأنا عاجز عن رؤيتك في دار التكليف. قال: يا موسى إني اصطفيتك على الناس برسالاتي وبكلامي، فخذ ما آتيتك وكن من الشاكرين بطاعتي. وكتبنا له في الألواح من كل شيء من أمور الدين والدنيا موعظة وتفصيلاً لكل شيء، فخذها بقوة، بعزم وجد في العمل بحلالها وحرامها، وأمر قومك يأخذوا بأحسنها، بعزائمها لا برخصها، تعويداً لهم على تحمّل العظائم بعد طول ضعف، سأريكم دار الفاسقين: وعيد لمن ترك شرائع الألواح بأن جزاءه جهنم.", "h": ["المحافظة على المواعيد أمر محبوب للشارع، مرغّب فيه، وهو من سمات الصادقين.", "جواز الاستخلاف في الأرض في مهام الأمور، فضلاً عما هو دون ذلك.", "مشروعية الوصية للخلفاء بما هو خير.", "إمكان رؤية الله تعالى، وهي ثابتة في الآخرة لأهل الجنة.", "استحالة رؤية الله تعالى في الدنيا لضعف الإنسان عن ذلك.", "وجود الأمة القابلة لأحكام الله قبل وجود الشرع الذي يحكمها."], "k": "«فخذها بقوة»… هل آخذ ديني بعزم وجد، أم أبحث دائماً عن أسهل الرخص؟"}, {"lbl": "الآيتان ١٤٦ – ١٤٧", "q": "سَأَصۡرِفُ عَنۡ ءَايَٰتِيَ ٱلَّذِينَ يَتَكَبَّرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَا وَإِن يَرَوۡاْ سَبِيلَ ٱلرُّشۡدِ لَا يَتَّخِذُوهُ سَبِيلٗا وَإِن يَرَوۡاْ سَبِيلَ ٱلۡغَيِّ يَتَّخِذُوهُ سَبِيلٗاۚ ذَٰلِكَ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنۡهَا غَٰفِلِينَ ﴿١٤٦﴾ وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآءِ ٱلۡأٓخِرَةِ حَبِطَتۡ أَعۡمَٰلُهُمۡۚ هَلۡ يُجۡزَوۡنَ إِلَّا مَا كَانُواْ يَعۡمَلُونَ ﴿١٤٧﴾", "w": [["يتكبّرون", "يعلون ويترفّعون، فيمنعون الحقوق ويحتقرون الناس."], ["سبيل الغيّ", "طريق الضلال القائم على الشرك والمعاصي."], ["وكانوا عنها غافلين", "لا يلتفتون إليها ولا ينظرون فيها، ولا يتفكّرون فيما تدل عليه."], ["حبطت أعمالهم", "فسدت فلا ينتفعون بها، لأنها أعمال مشرك، والشرك محبط للعمل."]], "m": "هاتان الآيتان تحملان تعليلاً صائباً لكل انحراف وفساد وظلم وقع في الأرض ويقع إلى نهاية الحياة، وهو التكذيب بآيات الله والغفلة عنها، سواء كان الحامل عليه الكبر أو الظلم أو التقليد أو العناد، إلا أن الكبر أقوى عوامل الصرف عنها: سأصرف عن آياتي الذين يتكبّرون في الأرض بغير الحق، ومن صرفه الله حسب سنته لا يقبل ولا يرجع. وإن يروا كل آية لا يؤمنوا بها، وإن يروا سبيل الرشد لا يتخذوه سبيلاً، وإن يروا سبيل الغي يتخذوه سبيلاً، ذلك بأنهم كذّبوا بآياتنا وكانوا عنها غافلين غير مبالين بها. والذين كذّبوا بآياتنا ولقاء الآخرة حبطت أعمالهم، إذ لم تقم على العدل والحق، فهي باطلة لا تكسبهم خيراً، وهي أعمال سوء يُجزون بها، هل يُجزون إلا ما كانوا يعملون؟", "h": ["بيان سنة الله تعالى في صرف العباد عن آيات الله حتى يهلكوا كما هلك فرعون وآله.", "من أقوى عوامل الصرف عن آيات الله الكبر.", "التكذيب بآيات الله والغفلة عنها هما سبب كل ضلال وشر وظلم وفساد.", "بطلان كل عمل لم يسلك فيه صاحبه سبيل الرشد، التي هي سبيل الله التي تحدّدها الآيات القرآنية وتبيّن معالمها وترفع أعلامها."], "k": "«سأصرف عن آياتي الذين يتكبّرون»… هل في قلبي كبر يحجبني عن آية تدعوني إلى التغيير؟"}, {"lbl": "الآيتان ١٤٨ – ١٤٩", "q": "وَٱتَّخَذَ قَوۡمُ مُوسَىٰ مِنۢ بَعۡدِهِۦ مِنۡ حُلِيِّهِمۡ عِجۡلٗا جَسَدٗا لَّهُۥ خُوَارٌۚ أَلَمۡ يَرَوۡاْ أَنَّهُۥ لَا يُكَلِّمُهُمۡ وَلَا يَهۡدِيهِمۡ سَبِيلًاۘ ٱتَّخَذُوهُ وَكَانُواْ ظَٰلِمِينَ ﴿١٤٨﴾ وَلَمَّا سُقِطَ فِيٓ أَيۡدِيهِمۡ وَرَأَوۡاْ أَنَّهُمۡ قَدۡ ضَلُّواْ قَالُواْ لَئِن لَّمۡ يَرۡحَمۡنَا رَبُّنَا وَيَغۡفِرۡ لَنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ﴿١٤٩﴾", "w": [["من حُليّهم", "جمع حَلْي، وهو ما تتحلّى به المرأة لزوجها من أساور ونحوها."], ["عجلاً جسداً", "العجل ولد البقرة، والجسد: ذاتاً لا مجرد صورة."], ["له خوار", "الخوار صوت البقر، كالرغاء صوت الإبل."], ["ولما سُقط في أيديهم", "ندموا على عبادته لأنها عبادة باطلة."]], "m": "بعد أن اعترض السياق ببيان سبب هلاك العباد، عاد إلى قصص موسى: واتخذ قوم موسى من بعد غيبته في جبل الطور من حليّ نسائهم عجلاً جسداً له خوار، وذلك أن السامري طلب من نسائهم حليّهم بحجة واهية أنه مستعار من نساء الأقباط ولا يحل تملّكه، وكان صائغاً، فصهره وأخرج لهم منه عجلاً ذاتاً له صوت كصوت البقر، وقال: هذا إلهكم وإله موسى، ولم يقل وإله هارون خوفاً أن يكذّبه وهو معهم. ألم يروا أنه لا يكلّمهم ولا يهديهم سبيلاً؟ توبيخ لغباوتهم، اتخذوه إلهاً وكانوا ظالمين. ولما انكشف لهم خطؤهم ندموا ندماً شديداً ورأوا أنهم قد ضلّوا، فصاحوا معلنين توبتهم: لئن لم يرحمنا ربنا ويغفر لنا هذا الذنب العظيم لنكوننّ من الخاسرين.", "h": ["بيان سنة من سنن الكون، وهي أن المرء يتأثّر بما يرى ويسمع، والرؤية أكثر تأثيراً في النفس من السماع، فرؤية بني إسرائيل للأبقار الآلهة هي التي جعلتهم يقبلون عجل السامري، ومن هنا كان منظر الأشياء في التلفاز وشاشات الفيديو مؤثّراً جداً، وكم أفسد من عقول، ولوّث من نفوس، وأفسد من أخلاق.", "تقبيح الغباء والجمود في الفكر، وذلك لقول الله تعالى: «ألم يروا أنه لا يكلّمهم».", "إذا أراد الله بعبده خيراً ألهمه التوبة بعد المعصية، فندم واستغفر."], "k": "«لئن لم يرحمنا ربنا ويغفر لنا»… هل أسرع إلى الندم والاستغفار حين أكتشف خطئي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (110, 7, 150, 157, 'سورة الأعراف ١٥٠ – ١٥٧', 'غضب موسى ﵇ والألواح، و«ورحمتي وسعت كل شيء»، و«الذين يتبعون الرسول النبي الأمي»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 110) = $j$[{"lbl": "الآيات ١٥٠ – ١٥٤", "q": "وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗا قَالَ بِئۡسَمَا خَلَفۡتُمُونِي مِنۢ بَعۡدِيٓۖ أَعَجِلۡتُمۡ أَمۡرَ رَبِّكُمۡۖ وَأَلۡقَى ٱلۡأَلۡوَاحَ وَأَخَذَ بِرَأۡسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيۡهِۚ قَالَ ٱبۡنَ أُمَّ إِنَّ ٱلۡقَوۡمَ ٱسۡتَضۡعَفُونِي وَكَادُواْ يَقۡتُلُونَنِي فَلَا تُشۡمِتۡ بِيَ ٱلۡأَعۡدَآءَ وَلَا تَجۡعَلۡنِي مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿١٥٠﴾ قَالَ رَبِّ ٱغۡفِرۡ لِي وَلِأَخِي وَأَدۡخِلۡنَا فِي رَحۡمَتِكَۖ وَأَنتَ أَرۡحَمُ ٱلرَّـٰحِمِينَ ﴿١٥١﴾ إِنَّ ٱلَّذِينَ ٱتَّخَذُواْ ٱلۡعِجۡلَ سَيَنَالُهُمۡ غَضَبٞ مِّن رَّبِّهِمۡ وَذِلَّةٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُفۡتَرِينَ ﴿١٥٢﴾ وَٱلَّذِينَ عَمِلُواْ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُواْ مِنۢ بَعۡدِهَا وَءَامَنُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٞ ﴿١٥٣﴾ وَلَمَّا سَكَتَ عَن مُّوسَى ٱلۡغَضَبُ أَخَذَ ٱلۡأَلۡوَاحَۖ وَفِي نُسۡخَتِهَا هُدٗى وَرَحۡمَةٞ لِّلَّذِينَ هُمۡ لِرَبِّهِمۡ يَرۡهَبُونَ ﴿١٥٤﴾", "w": [["ولما رجع موسى", "أي من جبل الطور بعد مرور أكثر من أربعين يوماً."], ["أسفاً", "حزيناً شديد الحزن والغضب."], ["أعجلتم أمر ربكم", "استعجلتم؟"], ["قال ابن أمّ", "أصلها: يا ابن أمي، وهارون شقيق موسى، وإنما ناداه بأمه لأنه أكثر استعطافاً."], ["فلا تُشمت بي الأعداء", "لا تجعل الأعداء يفرحون بإهانتك أو ضربك لي."], ["اتخذوا العجل", "أي إلهاً عبدوه."], ["المفترين", "الكاذبين على الله تعالى بالشرك به، أي يجعل شريك له."], ["ولما سكت عن موسى الغضب", "زال غضبه وسكنت نفسه من القلق والاضطراب."], ["أخذ الألواح", "أي من الأرض بعد أن طرحها فتكسّرت."], ["وفي نسختها", "وفيما نسخه منها بعد تكسّرها."], ["يرهبون", "يخافون ربهم ويخشون عقابه فلا يعصونه."]], "m": "لما رجع موسى من مناجاته، وقد أخبره ربه أنه فتن قومه من بعده وأن السامري أضلّهم، رجع غضبان أسفاً، فقال: بئسما خلفتموني من بعدي، أعجلتم أمر ربكم فلم تُتمّوا ميعاد الأربعين، فقلتم مات موسى وعبدتم العجل؟ وألقى الألواح فتكسّرت، وأخذ برأس أخيه يجرّه إليه يؤنّبه على تفريطه في الخلافة، فاعتذر هارون: يا ابن أمّ إن القوم استضعفوني وكادوا يقتلونني، فلا تؤذني فيفرح بي الأعداء، ولا تجعلني مع القوم الظالمين بعبادة العجل. فرقّ له موسى وقال: رب اغفر لي ولأخي وأدخلنا في رحمتك، وأنت أرحم الراحمين، متوسّلاً بها. إن الذين اتخذوا العجل إلهاً سينالهم غضب من ربهم وذلة في الحياة الدنيا، وكذلك نجزي المفترين. والذين عملوا السيئات، وهي هنا سيئة الشرك، ثم تابوا من بعدها وآمنوا صادقين، إن ربك من بعدها لغفور رحيم. ولما سكت عن موسى الغضب أخذ الألواح، وفي نسختها هدى ورحمة للذين هم لربهم يرهبون، وخُصّوا بالذكر لأنهم الذين يجدون فيها الهدى والرحمة لإيمانهم وتقواهم.", "h": ["الغضب من طباع البشر، فلا يُلام عليه المرء مهما بلغ من الكمال كالأنبياء، ولكن أهل الكمال لا يخرج بهم الغضب إلى حد أن يقولوا أو يعملوا ما ليس بخير وصلاح.", "مشروعية الاعتذار، وقبول العذر من أهل المروءات.", "مشروعية التوسّل بأسماء الله وصفاته.", "كل وعيد لله تعالى توعّد به عبداً من عباده مقيّد بعدم توبة المتوعَّد.", "كل رحمة وهدى ونور في كتاب الله لا ينتفع به إلا أهل الإيمان والتقوى."], "k": "«ولما سكت عن موسى الغضب»… ماذا أفعل حين أغضب: أتركه يقودني، أم أنتظر حتى يسكت ثم أعود إلى الحق؟"}, {"lbl": "الآيات ١٥٥ – ١٥٧", "q": "وَٱخۡتَارَ مُوسَىٰ قَوۡمَهُۥ سَبۡعِينَ رَجُلٗا لِّمِيقَٰتِنَاۖ فَلَمَّآ أَخَذَتۡهُمُ ٱلرَّجۡفَةُ قَالَ رَبِّ لَوۡ شِئۡتَ أَهۡلَكۡتَهُم مِّن قَبۡلُ وَإِيَّـٰيَۖ أَتُهۡلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآۖ إِنۡ هِيَ إِلَّا فِتۡنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهۡدِي مَن تَشَآءُۖ أَنتَ وَلِيُّنَا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَاۖ وَأَنتَ خَيۡرُ ٱلۡغَٰفِرِينَ ﴿١٥٥﴾ ۞وَٱكۡتُبۡ لَنَا فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ إِنَّا هُدۡنَآ إِلَيۡكَۚ قَالَ عَذَابِيٓ أُصِيبُ بِهِۦ مَنۡ أَشَآءُۖ وَرَحۡمَتِي وَسِعَتۡ كُلَّ شَيۡءٖۚ فَسَأَكۡتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤۡمِنُونَ ﴿١٥٦﴾ ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِيَّ ٱلۡأُمِّيَّ ٱلَّذِي يَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ يَأۡمُرُهُم بِٱلۡمَعۡرُوفِ وَيَنۡهَىٰهُمۡ عَنِ ٱلۡمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيۡهِمُ ٱلۡخَبَـٰٓئِثَ وَيَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَٱلۡأَغۡلَٰلَ ٱلَّتِي كَانَتۡ عَلَيۡهِمۡۚ فَٱلَّذِينَ ءَامَنُواْ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُواْ ٱلنُّورَ ٱلَّذِيٓ أُنزِلَ مَعَهُۥٓ أُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿١٥٧﴾", "w": [["واختار موسى قومه سبعين رجلاً", "أخذ خيار قومه، وهم سبعون رجلاً."], ["أخذتهم الرجفة", "الصاعقة التي رجفت لها القلوب."], ["السفهاء", "جمع سفيه، وهو الذي لا رشد له في سائر تصرّفاته."], ["إن هي إلا فتنتك", "ما هي إلا اختبارك لأهل الطاعة من أهل المعصية."], ["أنت ولينا", "المتولّي أمرنا، وليس لنا من ولي سواك."], ["هُدنا إليك", "رجعنا إليك وتبنا."], ["الأمي", "الذي لا يقرأ ولا يكتب."], ["المعروف والمنكر", "المعروف: ما عرفه الشرع، والمنكر: ما أنكره الشرع."], ["ويحرّم عليهم الخبائث", "بإذن الله، والخبائث جمع خبيثة كالميتة."], ["ويضع عنهم إصرهم والأغلال", "الإصر: العهد، والأغلال: الشدائد في الدين."], ["وعزّروه", "وقّروه وعظّموه."], ["واتبعوا النور الذي أُنزل معه", "القرآن الكريم."], ["هم المفلحون", "الفائزون، أي الناجون من النار الداخلون الجنة."]], "m": "بعد عبادة العجل وقّت الله لموسى وقتاً يأتيه فيه مع خيار بني إسرائيل يطلب لهم التوبة، فاختار موسى قومه سبعين رجلاً، فلما انتهى بهم إلى جبل الطور وأخذ يناجي ربه وهم يسمعون، قالوا: لن نؤمن لك حتى نرى الله جهرة، فأخذتهم صيحة رجفت لها قلوبهم فماتوا كلهم. فأسف موسى وقال: رب لو شئت أهلكتهم من قبل وإياي، أتهلكنا بما فعل السفهاء منا؟ إن هي إلا فتنتك تضل بها من تشاء وتهدي من تشاء، أنت ولينا فاغفر لنا وارحمنا وأنت خير الغافرين، واكتب لنا في هذه الدنيا حسنة بتوفيقنا للصالحات، وفي الآخرة، إنا هُدنا إليك. قال: عذابي أصيب به من أشاء ممن يفسقون عن أمري، ورحمتي وسعت كل شيء، فسأكتبها للذين يتقون ويؤتون الزكاة والذين هم بآياتنا يؤمنون، وبهذا القيد خرج إبليس واليهود وسائر أهل الملل، ودخلت أمة الإسلام، إلا من آمن من أهل الكتاب: الذين يتبعون الرسول النبي الأمي محمداً ﷺ، الذي يجدونه مكتوباً عندهم في التوراة والإنجيل بصفاته، يأمرهم بالمعروف وينهاهم عن المنكر، ويحل لهم الطيبات التي حُرّمت عليهم بظلمهم، ويحرّم عليهم الخبائث، ويضع عنهم إصرهم والأغلال التي كانت عليهم من التكاليف الشاقة، كقتل النفس بالنفس بلا عفو ولا دية، فالذين آمنوا به وعزّروه ونصروه واتبعوا القرآن أولئك هم المفلحون.", "h": ["وجوب التوبة من كل ذنب، ومشروعية صلاة ركعتين وسؤال الله تعالى عقبها أن يقبل توبة التائب ويغفر ذنبه.", "كل سلوك ينافي الشرع فهو من السفه المذموم، وصاحبه قد يوصف بأنه سفيه.", "الهداية والإضلال كلاهما بيد الله تعالى، فعلى العبد أن يطلب الهداية من الله ويسأله ألا يُضلّه.", "رحمة الله تعالى بأمة محمد ﷺ، فلا تنال اليهود ولا النصارى ولا غيرهم.", "بيان شرف النبي محمد ﷺ وأمته.", "بيان فضل تزكية النفس بعمل الصالحات وإبعادها عن المدسّيات من الذنوب.", "بيان فضل التقوى، والأمر بالمعروف والنهي عن المنكر.", "وجوب توقير النبي ﷺ وتعظيمه ونصرته، واتباع الكتاب الذي جاء به والسنن التي سنّها."], "k": "«ورحمتي وسعت كل شيء»… رحمة واسعة؛ فهل أتّصف بما يُدخلني فيها: التقوى والزكاة والإيمان بالآيات؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 110;
insert into public.tdb_cards(topic, i, body) select 110, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٥٠ – ١٥٤", "q": "وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗا قَالَ بِئۡسَمَا خَلَفۡتُمُونِي مِنۢ بَعۡدِيٓۖ أَعَجِلۡتُمۡ أَمۡرَ رَبِّكُمۡۖ وَأَلۡقَى ٱلۡأَلۡوَاحَ وَأَخَذَ بِرَأۡسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيۡهِۚ قَالَ ٱبۡنَ أُمَّ إِنَّ ٱلۡقَوۡمَ ٱسۡتَضۡعَفُونِي وَكَادُواْ يَقۡتُلُونَنِي فَلَا تُشۡمِتۡ بِيَ ٱلۡأَعۡدَآءَ وَلَا تَجۡعَلۡنِي مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿١٥٠﴾ قَالَ رَبِّ ٱغۡفِرۡ لِي وَلِأَخِي وَأَدۡخِلۡنَا فِي رَحۡمَتِكَۖ وَأَنتَ أَرۡحَمُ ٱلرَّـٰحِمِينَ ﴿١٥١﴾ إِنَّ ٱلَّذِينَ ٱتَّخَذُواْ ٱلۡعِجۡلَ سَيَنَالُهُمۡ غَضَبٞ مِّن رَّبِّهِمۡ وَذِلَّةٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُفۡتَرِينَ ﴿١٥٢﴾ وَٱلَّذِينَ عَمِلُواْ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُواْ مِنۢ بَعۡدِهَا وَءَامَنُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٞ ﴿١٥٣﴾ وَلَمَّا سَكَتَ عَن مُّوسَى ٱلۡغَضَبُ أَخَذَ ٱلۡأَلۡوَاحَۖ وَفِي نُسۡخَتِهَا هُدٗى وَرَحۡمَةٞ لِّلَّذِينَ هُمۡ لِرَبِّهِمۡ يَرۡهَبُونَ ﴿١٥٤﴾", "w": [["ولما رجع موسى", "أي من جبل الطور بعد مرور أكثر من أربعين يوماً."], ["أسفاً", "حزيناً شديد الحزن والغضب."], ["أعجلتم أمر ربكم", "استعجلتم؟"], ["قال ابن أمّ", "أصلها: يا ابن أمي، وهارون شقيق موسى، وإنما ناداه بأمه لأنه أكثر استعطافاً."], ["فلا تُشمت بي الأعداء", "لا تجعل الأعداء يفرحون بإهانتك أو ضربك لي."], ["اتخذوا العجل", "أي إلهاً عبدوه."], ["المفترين", "الكاذبين على الله تعالى بالشرك به، أي يجعل شريك له."], ["ولما سكت عن موسى الغضب", "زال غضبه وسكنت نفسه من القلق والاضطراب."], ["أخذ الألواح", "أي من الأرض بعد أن طرحها فتكسّرت."], ["وفي نسختها", "وفيما نسخه منها بعد تكسّرها."], ["يرهبون", "يخافون ربهم ويخشون عقابه فلا يعصونه."]], "m": "لما رجع موسى من مناجاته، وقد أخبره ربه أنه فتن قومه من بعده وأن السامري أضلّهم، رجع غضبان أسفاً، فقال: بئسما خلفتموني من بعدي، أعجلتم أمر ربكم فلم تُتمّوا ميعاد الأربعين، فقلتم مات موسى وعبدتم العجل؟ وألقى الألواح فتكسّرت، وأخذ برأس أخيه يجرّه إليه يؤنّبه على تفريطه في الخلافة، فاعتذر هارون: يا ابن أمّ إن القوم استضعفوني وكادوا يقتلونني، فلا تؤذني فيفرح بي الأعداء، ولا تجعلني مع القوم الظالمين بعبادة العجل. فرقّ له موسى وقال: رب اغفر لي ولأخي وأدخلنا في رحمتك، وأنت أرحم الراحمين، متوسّلاً بها. إن الذين اتخذوا العجل إلهاً سينالهم غضب من ربهم وذلة في الحياة الدنيا، وكذلك نجزي المفترين. والذين عملوا السيئات، وهي هنا سيئة الشرك، ثم تابوا من بعدها وآمنوا صادقين، إن ربك من بعدها لغفور رحيم. ولما سكت عن موسى الغضب أخذ الألواح، وفي نسختها هدى ورحمة للذين هم لربهم يرهبون، وخُصّوا بالذكر لأنهم الذين يجدون فيها الهدى والرحمة لإيمانهم وتقواهم.", "h": ["الغضب من طباع البشر، فلا يُلام عليه المرء مهما بلغ من الكمال كالأنبياء، ولكن أهل الكمال لا يخرج بهم الغضب إلى حد أن يقولوا أو يعملوا ما ليس بخير وصلاح.", "مشروعية الاعتذار، وقبول العذر من أهل المروءات.", "مشروعية التوسّل بأسماء الله وصفاته.", "كل وعيد لله تعالى توعّد به عبداً من عباده مقيّد بعدم توبة المتوعَّد.", "كل رحمة وهدى ونور في كتاب الله لا ينتفع به إلا أهل الإيمان والتقوى."], "k": "«ولما سكت عن موسى الغضب»… ماذا أفعل حين أغضب: أتركه يقودني، أم أنتظر حتى يسكت ثم أعود إلى الحق؟"}, {"lbl": "الآيات ١٥٥ – ١٥٧", "q": "وَٱخۡتَارَ مُوسَىٰ قَوۡمَهُۥ سَبۡعِينَ رَجُلٗا لِّمِيقَٰتِنَاۖ فَلَمَّآ أَخَذَتۡهُمُ ٱلرَّجۡفَةُ قَالَ رَبِّ لَوۡ شِئۡتَ أَهۡلَكۡتَهُم مِّن قَبۡلُ وَإِيَّـٰيَۖ أَتُهۡلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآۖ إِنۡ هِيَ إِلَّا فِتۡنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهۡدِي مَن تَشَآءُۖ أَنتَ وَلِيُّنَا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَاۖ وَأَنتَ خَيۡرُ ٱلۡغَٰفِرِينَ ﴿١٥٥﴾ ۞وَٱكۡتُبۡ لَنَا فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ إِنَّا هُدۡنَآ إِلَيۡكَۚ قَالَ عَذَابِيٓ أُصِيبُ بِهِۦ مَنۡ أَشَآءُۖ وَرَحۡمَتِي وَسِعَتۡ كُلَّ شَيۡءٖۚ فَسَأَكۡتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤۡمِنُونَ ﴿١٥٦﴾ ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِيَّ ٱلۡأُمِّيَّ ٱلَّذِي يَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ يَأۡمُرُهُم بِٱلۡمَعۡرُوفِ وَيَنۡهَىٰهُمۡ عَنِ ٱلۡمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيۡهِمُ ٱلۡخَبَـٰٓئِثَ وَيَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَٱلۡأَغۡلَٰلَ ٱلَّتِي كَانَتۡ عَلَيۡهِمۡۚ فَٱلَّذِينَ ءَامَنُواْ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُواْ ٱلنُّورَ ٱلَّذِيٓ أُنزِلَ مَعَهُۥٓ أُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿١٥٧﴾", "w": [["واختار موسى قومه سبعين رجلاً", "أخذ خيار قومه، وهم سبعون رجلاً."], ["أخذتهم الرجفة", "الصاعقة التي رجفت لها القلوب."], ["السفهاء", "جمع سفيه، وهو الذي لا رشد له في سائر تصرّفاته."], ["إن هي إلا فتنتك", "ما هي إلا اختبارك لأهل الطاعة من أهل المعصية."], ["أنت ولينا", "المتولّي أمرنا، وليس لنا من ولي سواك."], ["هُدنا إليك", "رجعنا إليك وتبنا."], ["الأمي", "الذي لا يقرأ ولا يكتب."], ["المعروف والمنكر", "المعروف: ما عرفه الشرع، والمنكر: ما أنكره الشرع."], ["ويحرّم عليهم الخبائث", "بإذن الله، والخبائث جمع خبيثة كالميتة."], ["ويضع عنهم إصرهم والأغلال", "الإصر: العهد، والأغلال: الشدائد في الدين."], ["وعزّروه", "وقّروه وعظّموه."], ["واتبعوا النور الذي أُنزل معه", "القرآن الكريم."], ["هم المفلحون", "الفائزون، أي الناجون من النار الداخلون الجنة."]], "m": "بعد عبادة العجل وقّت الله لموسى وقتاً يأتيه فيه مع خيار بني إسرائيل يطلب لهم التوبة، فاختار موسى قومه سبعين رجلاً، فلما انتهى بهم إلى جبل الطور وأخذ يناجي ربه وهم يسمعون، قالوا: لن نؤمن لك حتى نرى الله جهرة، فأخذتهم صيحة رجفت لها قلوبهم فماتوا كلهم. فأسف موسى وقال: رب لو شئت أهلكتهم من قبل وإياي، أتهلكنا بما فعل السفهاء منا؟ إن هي إلا فتنتك تضل بها من تشاء وتهدي من تشاء، أنت ولينا فاغفر لنا وارحمنا وأنت خير الغافرين، واكتب لنا في هذه الدنيا حسنة بتوفيقنا للصالحات، وفي الآخرة، إنا هُدنا إليك. قال: عذابي أصيب به من أشاء ممن يفسقون عن أمري، ورحمتي وسعت كل شيء، فسأكتبها للذين يتقون ويؤتون الزكاة والذين هم بآياتنا يؤمنون، وبهذا القيد خرج إبليس واليهود وسائر أهل الملل، ودخلت أمة الإسلام، إلا من آمن من أهل الكتاب: الذين يتبعون الرسول النبي الأمي محمداً ﷺ، الذي يجدونه مكتوباً عندهم في التوراة والإنجيل بصفاته، يأمرهم بالمعروف وينهاهم عن المنكر، ويحل لهم الطيبات التي حُرّمت عليهم بظلمهم، ويحرّم عليهم الخبائث، ويضع عنهم إصرهم والأغلال التي كانت عليهم من التكاليف الشاقة، كقتل النفس بالنفس بلا عفو ولا دية، فالذين آمنوا به وعزّروه ونصروه واتبعوا القرآن أولئك هم المفلحون.", "h": ["وجوب التوبة من كل ذنب، ومشروعية صلاة ركعتين وسؤال الله تعالى عقبها أن يقبل توبة التائب ويغفر ذنبه.", "كل سلوك ينافي الشرع فهو من السفه المذموم، وصاحبه قد يوصف بأنه سفيه.", "الهداية والإضلال كلاهما بيد الله تعالى، فعلى العبد أن يطلب الهداية من الله ويسأله ألا يُضلّه.", "رحمة الله تعالى بأمة محمد ﷺ، فلا تنال اليهود ولا النصارى ولا غيرهم.", "بيان شرف النبي محمد ﷺ وأمته.", "بيان فضل تزكية النفس بعمل الصالحات وإبعادها عن المدسّيات من الذنوب.", "بيان فضل التقوى، والأمر بالمعروف والنهي عن المنكر.", "وجوب توقير النبي ﷺ وتعظيمه ونصرته، واتباع الكتاب الذي جاء به والسنن التي سنّها."], "k": "«ورحمتي وسعت كل شيء»… رحمة واسعة؛ فهل أتّصف بما يُدخلني فيها: التقوى والزكاة والإيمان بالآيات؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (111, 7, 158, 170, 'سورة الأعراف ١٥٨ – ١٧٠', '«إني رسول الله إليكم جميعاً»، أصحاب السبت، و«والذين يُمسّكون بالكتاب»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 111) = $j$[{"lbl": "الآيات ١٥٨ – ١٦٢", "q": "قُلۡ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡ جَمِيعًا ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ لَآ إِلَٰهَ إِلَّا هُوَ يُحۡيِۦ وَيُمِيتُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِيِّ ٱلۡأُمِّيِّ ٱلَّذِي يُؤۡمِنُ بِٱللَّهِ وَكَلِمَٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمۡ تَهۡتَدُونَ ﴿١٥٨﴾ وَمِن قَوۡمِ مُوسَىٰٓ أُمَّةٞ يَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ ﴿١٥٩﴾ وَقَطَّعۡنَٰهُمُ ٱثۡنَتَيۡ عَشۡرَةَ أَسۡبَاطًا أُمَمٗاۚ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسۡتَسۡقَىٰهُ قَوۡمُهُۥٓ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنۢبَجَسَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَيۡنٗاۖ قَدۡ عَلِمَ كُلُّ أُنَاسٖ مَّشۡرَبَهُمۡۚ وَظَلَّلۡنَا عَلَيۡهِمُ ٱلۡغَمَٰمَ وَأَنزَلۡنَا عَلَيۡهِمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿١٦٠﴾ وَإِذۡ قِيلَ لَهُمُ ٱسۡكُنُواْ هَٰذِهِ ٱلۡقَرۡيَةَ وَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ وَقُولُواْ حِطَّةٞ وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا نَّغۡفِرۡ لَكُمۡ خَطِيٓـَٰٔتِكُمۡۚ سَنَزِيدُ ٱلۡمُحۡسِنِينَ ﴿١٦١﴾ فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَظۡلِمُونَ ﴿١٦٢﴾", "w": [["لا إله إلا هو", "لا معبود بحق إلا الله."], ["النبي الأمي", "النبي: المنبئ عن الله والمنبَّأ من قبله، والأمي: الذي لم يقرأ ولم يكتب، نسبة إلى الأم كأنه لم يفارق أمه فلم يتعلّم."], ["يؤمن بالله وكلماته", "يؤمن بالله رباً وإلهاً، وبكلماته التشريعية والكونية."], ["تهتدون", "تُرشدون إلى طريق كمالكم وسعادتكم في الحياتين."], ["أمة يهدون بالحق", "جماعة يهدون أنفسهم وغيرهم بالدين الحق، وبه يعدلون في قضائهم وحكمهم."], ["أسباطاً", "جمع سبط، بمعنى القبيلة عند العرب."], ["استسقاه قومه", "طلبوا منه الماء لعطشهم."], ["فانبجست", "فانفجرت."], ["المنّ والسلوى", "المنّ: حلوى كالعسل تنزل على أوراق الأشجار، والسلوى: طائر لذيذ لحمه."], ["اسكنوا هذه القرية", "هي حاضرة فلسطين."], ["حطّة", "احطط عنا خطايانا، إعلاناً عن توبتهم."], ["رجزاً من السماء", "عذاباً من عند الله تعالى."]], "m": "بعد الإشادة بالنبي الأمي، قد يظن ظانّ أنه نبي قومه خاصة، فرفع الله هذا الوهم: قل يا أيها الناس إني رسول الله إليكم جميعاً، الذي له ملك السماوات والأرض، لا إله إلا هو يحيي ويميت، فآمنوا بالله ورسوله النبي الأمي الذي يؤمن بالله وكلماته، واتبعوه لعلكم تهتدون. ومن قوم موسى أمة يهدون بالحق وبه يعدلون، احتراس من أن يُظن أنه لم يكن فيهم من هو على هدى. ثم عاد إلى أحداثهم: وقطّعناهم اثنتي عشرة أسباطاً أمماً، كالقبائل في العرب، وأوحينا إلى موسى إذ استسقاه قومه في صحراء سيناء أن اضرب بعصاك الحجر، فانفجرت منه اثنتا عشرة عيناً، لكل سبط عينه حتى لا يقع تدافع، وظلّلنا عليهم الغمام، وأنزلنا عليهم المنّ والسلوى: كلوا من طيبات ما رزقناكم، وما ظلمونا ولكن كانوا أنفسهم يظلمون. وبعد التيه أربعين سنة ووفاة موسى وهارون، غزا يوشع بن نون العمالقة وفتح الله عليه، فقيل لهم: اسكنوا هذه القرية وكلوا منها حيث شئتم، وقولوا حطّة، وادخلوا الباب سجّداً منحنين شكراً، نغفر لكم خطيئاتكم سنزيد المحسنين. فبدّل الذين ظلموا قولاً غير الذي قيل لهم، فقالوا: حنطة، ودخلوا يزحفون على أستاههم، فأرسلنا عليهم وباءً من السماء كاد يقضي عليهم بما كانوا يظلمون.", "h": ["عموم رسالة النبي محمد ﷺ لكافة الناس، عربهم وعجمهم.", "هداية الإنسان، فرداً أو جماعة أو أمة، إلى الكمال والإسعاد متوقّفة على اتباع النبي ﷺ.", "إنصاف القرآن للأمم والجماعات، فقد صرّح أن في بني إسرائيل أمة قائمة على الحق، وذلك قبل مبعث النبي الخاتم، أما بعد البعثة المحمدية فلم يبق أحد على الحق إلا من آمن به واتبعه، لنسخ سائر الشرائع بشريعته.", "إذا أنعم الله على عبد أو أمة نعمة ثم لم يشكرها تُسلب منه، أحب أم كره، وكائناً من كان."], "k": "«قل يا أيها الناس إني رسول الله إليكم جميعاً»… رسالة للناس جميعاً؛ فماذا أوصلت منها لمن حولي؟"}, {"lbl": "الآيات ١٦٣ – ١٦٦", "q": "وَسۡـَٔلۡهُمۡ عَنِ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَتۡ حَاضِرَةَ ٱلۡبَحۡرِ إِذۡ يَعۡدُونَ فِي ٱلسَّبۡتِ إِذۡ تَأۡتِيهِمۡ حِيتَانُهُمۡ يَوۡمَ سَبۡتِهِمۡ شُرَّعٗا وَيَوۡمَ لَا يَسۡبِتُونَ لَا تَأۡتِيهِمۡۚ كَذَٰلِكَ نَبۡلُوهُم بِمَا كَانُواْ يَفۡسُقُونَ ﴿١٦٣﴾ وَإِذۡ قَالَتۡ أُمَّةٞ مِّنۡهُمۡ لِمَ تَعِظُونَ قَوۡمًا ٱللَّهُ مُهۡلِكُهُمۡ أَوۡ مُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗاۖ قَالُواْ مَعۡذِرَةً إِلَىٰ رَبِّكُمۡ وَلَعَلَّهُمۡ يَتَّقُونَ ﴿١٦٤﴾ فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦٓ أَنجَيۡنَا ٱلَّذِينَ يَنۡهَوۡنَ عَنِ ٱلسُّوٓءِ وَأَخَذۡنَا ٱلَّذِينَ ظَلَمُواْ بِعَذَابِۭ بَـِٔيسِۭ بِمَا كَانُواْ يَفۡسُقُونَ ﴿١٦٥﴾ فَلَمَّا عَتَوۡاْ عَن مَّا نُهُواْ عَنۡهُ قُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ ﴿١٦٦﴾", "w": [["حاضرة البحر", "على شاطئه، وهي مدينة من مدن أرض القدس."], ["يعدون", "يعتدون، وذلك بالصيد المحرّم عليهم فيه."], ["في السبت", "يوم راحتهم من أعمال الدنيا، وهو يوم السبت."], ["شُرّعاً", "جمع شارع، أي ظاهرة بارزة تغريهم بنفسها."], ["نبلوهم", "نمتحنهم ونختبرهم."], ["بما كانوا يفسقون", "بسبب ما أعلنوه من الفسق، وهو العصيان."], ["معذرة إلى ربكم", "ننهاهم، فإن انتهوا فذاك، وإلا فنهينا يكون عذراً لنا عند ربنا."], ["فلما نسوا ما ذُكّروا به", "أهملوه وتركوه فلم يمتثلوا."], ["السوء", "كل ما يسيء إلى النفس من سائر الذنوب والآثام."], ["بعذاب بئيس", "ذي بأس شديد."]], "m": "واسأل اليهود عن القرية التي كانت حاضرة البحر، على شاطئه من مدن أرض القدس والشام، كيف كانت عاقبتهم؟ مُسخوا قردة جزاء فسقهم: إذ يعتدون في السبت، وهو يوم عبادة لا يوم لهو وصيد، إذ تأتيهم حيتانهم يوم سبتهم شُرّعاً ظاهرة على سطح الماء، ويوم لا يسبتون لا تأتيهم، كذلك نبلوهم بما كانوا يفسقون، إذ ما من مصيبة إلا بذنب. وإذ قالت أمة منهم لطائفة كانت تعظ المعتدين: لم تعظون قوماً الله مهلكهم أو معذّبهم عذاباً شديداً؟ قول دالّ على يأسهم من رجوعهم، فقال الواعظون: معذرة إلى ربكم، ولعلهم يتقون فيتوبوا. فلما تركوا ما ذُكّروا به وواصلوا اعتداءهم، أنجينا الذين ينهون عن السوء، وأخذنا الذين ظلموا بعذاب بئيس شديد بما كانوا يفسقون، فلما عتوا عما نُهوا عنه قلنا لهم: كونوا قردة خاسئين، فكانوا قردة ذليلين صاغرين، ثم لم يلبثوا إلا ثلاثة أيام وماتوا.", "h": ["تقرير الوحي والنبوة لرسول الله محمد ﷺ، إذ مثل هذا القصص لن يتم إلا عن طريق الوحي، وقد مضى عليه زمن طويل.", "إذا أنعم الله على أمة نعمة ثم أعرضت عن شكرها تعرّضت للبلاء أولاً، ثم العذاب ثانياً.", "جدوى الأمر بالمعروف والنهي عن المنكر، فقد نجّى الله الناهين عن المنكر، وأهلك الذين باشروه ولم ينتهوا منه.", "إطلاق لفظ السوء على المعصية مؤذن بأن المعصية مهما كانت صغيرة تُحدث السوء."], "k": "«معذرة إلى ربكم ولعلهم يتقون»… هل أترك النصيحة يأساً من الناس، أم أنصح معذرة إلى ربي؟"}, {"lbl": "الآيات ١٦٧ – ١٧٠", "q": "وَإِذۡ تَأَذَّنَ رَبُّكَ لَيَبۡعَثَنَّ عَلَيۡهِمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَن يَسُومُهُمۡ سُوٓءَ ٱلۡعَذَابِۗ إِنَّ رَبَّكَ لَسَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمٞ ﴿١٦٧﴾ وَقَطَّعۡنَٰهُمۡ فِي ٱلۡأَرۡضِ أُمَمٗاۖ مِّنۡهُمُ ٱلصَّـٰلِحُونَ وَمِنۡهُمۡ دُونَ ذَٰلِكَۖ وَبَلَوۡنَٰهُم بِٱلۡحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿١٦٨﴾ فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٞ وَرِثُواْ ٱلۡكِتَٰبَ يَأۡخُذُونَ عَرَضَ هَٰذَا ٱلۡأَدۡنَىٰ وَيَقُولُونَ سَيُغۡفَرُ لَنَا وَإِن يَأۡتِهِمۡ عَرَضٞ مِّثۡلُهُۥ يَأۡخُذُوهُۚ أَلَمۡ يُؤۡخَذۡ عَلَيۡهِم مِّيثَٰقُ ٱلۡكِتَٰبِ أَن لَّا يَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّ وَدَرَسُواْ مَا فِيهِۗ وَٱلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ ﴿١٦٩﴾ وَٱلَّذِينَ يُمَسِّكُونَ بِٱلۡكِتَٰبِ وَأَقَامُواْ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجۡرَ ٱلۡمُصۡلِحِينَ ﴿١٧٠﴾", "w": [["وقطّعناهم", "فرّقناهم جماعات جماعات."], ["بلوناهم بالحسنات والسيئات", "اختبرناهم بالخير والشر، أو النعم والنقم."], ["فخلف من بعدهم خلْف", "الخلْف بإسكان اللام: خلف سوء، وبالتحريك: خلف صالح."], ["ورثوا الكتاب", "أي التوراة."], ["عرض هذا الأدنى", "حطام الدنيا الفاني، وهو المال."], ["يُمسّكون بالكتاب", "يتمسّكون بما في التوراة، فيحلّون ما أحل الله فيها ويحرّمون ما حرّم."]], "m": "وإذ تأذّن ربك: أعلم بكل تأكيد ليبعثنّ على اليهود إلى يوم القيامة من يذلّهم ويسومهم سوء العذاب، عقوبة لخبث طواياهم وسوء أفعالهم، وهذا الوعيد مقيّد بأحد أمرين: توبة من تاب، لقوله: إن ربك لسريع العقاب وإنه لغفور رحيم، أو جوار دولة قوية لهم وحمايتها، لقوله في آل عمران: «إلا بحبل من الله وحبل من الناس». وقطّعناهم في الأرض أمماً، منهم الصالحون ومنهم دون ذلك، وبلوناهم بالحسنات والسيئات لعلهم يرجعون. فخلف من بعدهم خلف سوء ورثوا التوراة عن أسلافهم، ولم يلتزموا بعهودها، فآثروا الدنيا واستباحوا الربا والرشا وسائر المحرمات، ويقولون: سيُغفر لنا، وكلما أتاهم مال حرام أخذوه ومنّوا أنفسهم بالمغفرة كذباً على الله، ألم يؤخذ عليهم ميثاق الكتاب ألّا يقولوا على الله إلا الحق، وقد درسوا ما فيه؟ والدار الآخرة خير للذين يتقون أفلا تعقلون؟ ثم فتح لهم باب الرجاء: والذين يُمسّكون بالكتاب، يعملون بحرص بما فيه، وأقاموا الصلاة، إنا لا نضيع أجر المصلحين لأنفسهم ولغيرهم.", "h": ["بيان موجز لتاريخ اليهود في هذه الآيات الأربع.", "من أهل الكتاب الصالحون، ومنهم دون ذلك.", "التنديد بإيثار الدنيا على الآخرة، وبتمنّي المغفرة مع الإصرار على الإجرام.", "تفضيل الآخرة على الدنيا بالنسبة للمتقين.", "الحث على التمسّك بالكتاب، قراءة وتعلّماً وعملاً، بإحلال حلاله وتحريم حرامه."], "k": "«ويقولون سيُغفر لنا»… هل أتمنّى المغفرة وأنا مقيم على الذنب، أم أطلبها بالتوبة والعمل؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 111;
insert into public.tdb_cards(topic, i, body) select 111, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٥٨ – ١٦٢", "q": "قُلۡ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡ جَمِيعًا ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ لَآ إِلَٰهَ إِلَّا هُوَ يُحۡيِۦ وَيُمِيتُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِيِّ ٱلۡأُمِّيِّ ٱلَّذِي يُؤۡمِنُ بِٱللَّهِ وَكَلِمَٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمۡ تَهۡتَدُونَ ﴿١٥٨﴾ وَمِن قَوۡمِ مُوسَىٰٓ أُمَّةٞ يَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ ﴿١٥٩﴾ وَقَطَّعۡنَٰهُمُ ٱثۡنَتَيۡ عَشۡرَةَ أَسۡبَاطًا أُمَمٗاۚ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسۡتَسۡقَىٰهُ قَوۡمُهُۥٓ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنۢبَجَسَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَيۡنٗاۖ قَدۡ عَلِمَ كُلُّ أُنَاسٖ مَّشۡرَبَهُمۡۚ وَظَلَّلۡنَا عَلَيۡهِمُ ٱلۡغَمَٰمَ وَأَنزَلۡنَا عَلَيۡهِمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿١٦٠﴾ وَإِذۡ قِيلَ لَهُمُ ٱسۡكُنُواْ هَٰذِهِ ٱلۡقَرۡيَةَ وَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ وَقُولُواْ حِطَّةٞ وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا نَّغۡفِرۡ لَكُمۡ خَطِيٓـَٰٔتِكُمۡۚ سَنَزِيدُ ٱلۡمُحۡسِنِينَ ﴿١٦١﴾ فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَظۡلِمُونَ ﴿١٦٢﴾", "w": [["لا إله إلا هو", "لا معبود بحق إلا الله."], ["النبي الأمي", "النبي: المنبئ عن الله والمنبَّأ من قبله، والأمي: الذي لم يقرأ ولم يكتب، نسبة إلى الأم كأنه لم يفارق أمه فلم يتعلّم."], ["يؤمن بالله وكلماته", "يؤمن بالله رباً وإلهاً، وبكلماته التشريعية والكونية."], ["تهتدون", "تُرشدون إلى طريق كمالكم وسعادتكم في الحياتين."], ["أمة يهدون بالحق", "جماعة يهدون أنفسهم وغيرهم بالدين الحق، وبه يعدلون في قضائهم وحكمهم."], ["أسباطاً", "جمع سبط، بمعنى القبيلة عند العرب."], ["استسقاه قومه", "طلبوا منه الماء لعطشهم."], ["فانبجست", "فانفجرت."], ["المنّ والسلوى", "المنّ: حلوى كالعسل تنزل على أوراق الأشجار، والسلوى: طائر لذيذ لحمه."], ["اسكنوا هذه القرية", "هي حاضرة فلسطين."], ["حطّة", "احطط عنا خطايانا، إعلاناً عن توبتهم."], ["رجزاً من السماء", "عذاباً من عند الله تعالى."]], "m": "بعد الإشادة بالنبي الأمي، قد يظن ظانّ أنه نبي قومه خاصة، فرفع الله هذا الوهم: قل يا أيها الناس إني رسول الله إليكم جميعاً، الذي له ملك السماوات والأرض، لا إله إلا هو يحيي ويميت، فآمنوا بالله ورسوله النبي الأمي الذي يؤمن بالله وكلماته، واتبعوه لعلكم تهتدون. ومن قوم موسى أمة يهدون بالحق وبه يعدلون، احتراس من أن يُظن أنه لم يكن فيهم من هو على هدى. ثم عاد إلى أحداثهم: وقطّعناهم اثنتي عشرة أسباطاً أمماً، كالقبائل في العرب، وأوحينا إلى موسى إذ استسقاه قومه في صحراء سيناء أن اضرب بعصاك الحجر، فانفجرت منه اثنتا عشرة عيناً، لكل سبط عينه حتى لا يقع تدافع، وظلّلنا عليهم الغمام، وأنزلنا عليهم المنّ والسلوى: كلوا من طيبات ما رزقناكم، وما ظلمونا ولكن كانوا أنفسهم يظلمون. وبعد التيه أربعين سنة ووفاة موسى وهارون، غزا يوشع بن نون العمالقة وفتح الله عليه، فقيل لهم: اسكنوا هذه القرية وكلوا منها حيث شئتم، وقولوا حطّة، وادخلوا الباب سجّداً منحنين شكراً، نغفر لكم خطيئاتكم سنزيد المحسنين. فبدّل الذين ظلموا قولاً غير الذي قيل لهم، فقالوا: حنطة، ودخلوا يزحفون على أستاههم، فأرسلنا عليهم وباءً من السماء كاد يقضي عليهم بما كانوا يظلمون.", "h": ["عموم رسالة النبي محمد ﷺ لكافة الناس، عربهم وعجمهم.", "هداية الإنسان، فرداً أو جماعة أو أمة، إلى الكمال والإسعاد متوقّفة على اتباع النبي ﷺ.", "إنصاف القرآن للأمم والجماعات، فقد صرّح أن في بني إسرائيل أمة قائمة على الحق، وذلك قبل مبعث النبي الخاتم، أما بعد البعثة المحمدية فلم يبق أحد على الحق إلا من آمن به واتبعه، لنسخ سائر الشرائع بشريعته.", "إذا أنعم الله على عبد أو أمة نعمة ثم لم يشكرها تُسلب منه، أحب أم كره، وكائناً من كان."], "k": "«قل يا أيها الناس إني رسول الله إليكم جميعاً»… رسالة للناس جميعاً؛ فماذا أوصلت منها لمن حولي؟"}, {"lbl": "الآيات ١٦٣ – ١٦٦", "q": "وَسۡـَٔلۡهُمۡ عَنِ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَتۡ حَاضِرَةَ ٱلۡبَحۡرِ إِذۡ يَعۡدُونَ فِي ٱلسَّبۡتِ إِذۡ تَأۡتِيهِمۡ حِيتَانُهُمۡ يَوۡمَ سَبۡتِهِمۡ شُرَّعٗا وَيَوۡمَ لَا يَسۡبِتُونَ لَا تَأۡتِيهِمۡۚ كَذَٰلِكَ نَبۡلُوهُم بِمَا كَانُواْ يَفۡسُقُونَ ﴿١٦٣﴾ وَإِذۡ قَالَتۡ أُمَّةٞ مِّنۡهُمۡ لِمَ تَعِظُونَ قَوۡمًا ٱللَّهُ مُهۡلِكُهُمۡ أَوۡ مُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗاۖ قَالُواْ مَعۡذِرَةً إِلَىٰ رَبِّكُمۡ وَلَعَلَّهُمۡ يَتَّقُونَ ﴿١٦٤﴾ فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦٓ أَنجَيۡنَا ٱلَّذِينَ يَنۡهَوۡنَ عَنِ ٱلسُّوٓءِ وَأَخَذۡنَا ٱلَّذِينَ ظَلَمُواْ بِعَذَابِۭ بَـِٔيسِۭ بِمَا كَانُواْ يَفۡسُقُونَ ﴿١٦٥﴾ فَلَمَّا عَتَوۡاْ عَن مَّا نُهُواْ عَنۡهُ قُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ ﴿١٦٦﴾", "w": [["حاضرة البحر", "على شاطئه، وهي مدينة من مدن أرض القدس."], ["يعدون", "يعتدون، وذلك بالصيد المحرّم عليهم فيه."], ["في السبت", "يوم راحتهم من أعمال الدنيا، وهو يوم السبت."], ["شُرّعاً", "جمع شارع، أي ظاهرة بارزة تغريهم بنفسها."], ["نبلوهم", "نمتحنهم ونختبرهم."], ["بما كانوا يفسقون", "بسبب ما أعلنوه من الفسق، وهو العصيان."], ["معذرة إلى ربكم", "ننهاهم، فإن انتهوا فذاك، وإلا فنهينا يكون عذراً لنا عند ربنا."], ["فلما نسوا ما ذُكّروا به", "أهملوه وتركوه فلم يمتثلوا."], ["السوء", "كل ما يسيء إلى النفس من سائر الذنوب والآثام."], ["بعذاب بئيس", "ذي بأس شديد."]], "m": "واسأل اليهود عن القرية التي كانت حاضرة البحر، على شاطئه من مدن أرض القدس والشام، كيف كانت عاقبتهم؟ مُسخوا قردة جزاء فسقهم: إذ يعتدون في السبت، وهو يوم عبادة لا يوم لهو وصيد، إذ تأتيهم حيتانهم يوم سبتهم شُرّعاً ظاهرة على سطح الماء، ويوم لا يسبتون لا تأتيهم، كذلك نبلوهم بما كانوا يفسقون، إذ ما من مصيبة إلا بذنب. وإذ قالت أمة منهم لطائفة كانت تعظ المعتدين: لم تعظون قوماً الله مهلكهم أو معذّبهم عذاباً شديداً؟ قول دالّ على يأسهم من رجوعهم، فقال الواعظون: معذرة إلى ربكم، ولعلهم يتقون فيتوبوا. فلما تركوا ما ذُكّروا به وواصلوا اعتداءهم، أنجينا الذين ينهون عن السوء، وأخذنا الذين ظلموا بعذاب بئيس شديد بما كانوا يفسقون، فلما عتوا عما نُهوا عنه قلنا لهم: كونوا قردة خاسئين، فكانوا قردة ذليلين صاغرين، ثم لم يلبثوا إلا ثلاثة أيام وماتوا.", "h": ["تقرير الوحي والنبوة لرسول الله محمد ﷺ، إذ مثل هذا القصص لن يتم إلا عن طريق الوحي، وقد مضى عليه زمن طويل.", "إذا أنعم الله على أمة نعمة ثم أعرضت عن شكرها تعرّضت للبلاء أولاً، ثم العذاب ثانياً.", "جدوى الأمر بالمعروف والنهي عن المنكر، فقد نجّى الله الناهين عن المنكر، وأهلك الذين باشروه ولم ينتهوا منه.", "إطلاق لفظ السوء على المعصية مؤذن بأن المعصية مهما كانت صغيرة تُحدث السوء."], "k": "«معذرة إلى ربكم ولعلهم يتقون»… هل أترك النصيحة يأساً من الناس، أم أنصح معذرة إلى ربي؟"}, {"lbl": "الآيات ١٦٧ – ١٧٠", "q": "وَإِذۡ تَأَذَّنَ رَبُّكَ لَيَبۡعَثَنَّ عَلَيۡهِمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَن يَسُومُهُمۡ سُوٓءَ ٱلۡعَذَابِۗ إِنَّ رَبَّكَ لَسَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمٞ ﴿١٦٧﴾ وَقَطَّعۡنَٰهُمۡ فِي ٱلۡأَرۡضِ أُمَمٗاۖ مِّنۡهُمُ ٱلصَّـٰلِحُونَ وَمِنۡهُمۡ دُونَ ذَٰلِكَۖ وَبَلَوۡنَٰهُم بِٱلۡحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿١٦٨﴾ فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٞ وَرِثُواْ ٱلۡكِتَٰبَ يَأۡخُذُونَ عَرَضَ هَٰذَا ٱلۡأَدۡنَىٰ وَيَقُولُونَ سَيُغۡفَرُ لَنَا وَإِن يَأۡتِهِمۡ عَرَضٞ مِّثۡلُهُۥ يَأۡخُذُوهُۚ أَلَمۡ يُؤۡخَذۡ عَلَيۡهِم مِّيثَٰقُ ٱلۡكِتَٰبِ أَن لَّا يَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّ وَدَرَسُواْ مَا فِيهِۗ وَٱلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ ﴿١٦٩﴾ وَٱلَّذِينَ يُمَسِّكُونَ بِٱلۡكِتَٰبِ وَأَقَامُواْ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجۡرَ ٱلۡمُصۡلِحِينَ ﴿١٧٠﴾", "w": [["وقطّعناهم", "فرّقناهم جماعات جماعات."], ["بلوناهم بالحسنات والسيئات", "اختبرناهم بالخير والشر، أو النعم والنقم."], ["فخلف من بعدهم خلْف", "الخلْف بإسكان اللام: خلف سوء، وبالتحريك: خلف صالح."], ["ورثوا الكتاب", "أي التوراة."], ["عرض هذا الأدنى", "حطام الدنيا الفاني، وهو المال."], ["يُمسّكون بالكتاب", "يتمسّكون بما في التوراة، فيحلّون ما أحل الله فيها ويحرّمون ما حرّم."]], "m": "وإذ تأذّن ربك: أعلم بكل تأكيد ليبعثنّ على اليهود إلى يوم القيامة من يذلّهم ويسومهم سوء العذاب، عقوبة لخبث طواياهم وسوء أفعالهم، وهذا الوعيد مقيّد بأحد أمرين: توبة من تاب، لقوله: إن ربك لسريع العقاب وإنه لغفور رحيم، أو جوار دولة قوية لهم وحمايتها، لقوله في آل عمران: «إلا بحبل من الله وحبل من الناس». وقطّعناهم في الأرض أمماً، منهم الصالحون ومنهم دون ذلك، وبلوناهم بالحسنات والسيئات لعلهم يرجعون. فخلف من بعدهم خلف سوء ورثوا التوراة عن أسلافهم، ولم يلتزموا بعهودها، فآثروا الدنيا واستباحوا الربا والرشا وسائر المحرمات، ويقولون: سيُغفر لنا، وكلما أتاهم مال حرام أخذوه ومنّوا أنفسهم بالمغفرة كذباً على الله، ألم يؤخذ عليهم ميثاق الكتاب ألّا يقولوا على الله إلا الحق، وقد درسوا ما فيه؟ والدار الآخرة خير للذين يتقون أفلا تعقلون؟ ثم فتح لهم باب الرجاء: والذين يُمسّكون بالكتاب، يعملون بحرص بما فيه، وأقاموا الصلاة، إنا لا نضيع أجر المصلحين لأنفسهم ولغيرهم.", "h": ["بيان موجز لتاريخ اليهود في هذه الآيات الأربع.", "من أهل الكتاب الصالحون، ومنهم دون ذلك.", "التنديد بإيثار الدنيا على الآخرة، وبتمنّي المغفرة مع الإصرار على الإجرام.", "تفضيل الآخرة على الدنيا بالنسبة للمتقين.", "الحث على التمسّك بالكتاب، قراءة وتعلّماً وعملاً، بإحلال حلاله وتحريم حرامه."], "k": "«ويقولون سيُغفر لنا»… هل أتمنّى المغفرة وأنا مقيم على الذنب، أم أطلبها بالتوبة والعمل؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (112, 7, 171, 186, 'سورة الأعراف ١٧١ – ١٨٦', '«ألست بربكم»، «فانسلخ منها»، «ولله الأسماء الحسنى»، و«أوَلم ينظروا في ملكوت السماوات»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 112) = $j$[{"lbl": "الآيات ١٧١ – ١٧٤", "q": "۞وَإِذۡ نَتَقۡنَا ٱلۡجَبَلَ فَوۡقَهُمۡ كَأَنَّهُۥ ظُلَّةٞ وَظَنُّوٓاْ أَنَّهُۥ وَاقِعُۢ بِهِمۡ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ ﴿١٧١﴾ وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ وَأَشۡهَدَهُمۡ عَلَىٰٓ أَنفُسِهِمۡ أَلَسۡتُ بِرَبِّكُمۡۖ قَالُواْ بَلَىٰ شَهِدۡنَآۚ أَن تَقُولُواْ يَوۡمَ ٱلۡقِيَٰمَةِ إِنَّا كُنَّا عَنۡ هَٰذَا غَٰفِلِينَ ﴿١٧٢﴾ أَوۡ تَقُولُوٓاْ إِنَّمَآ أَشۡرَكَ ءَابَآؤُنَا مِن قَبۡلُ وَكُنَّا ذُرِّيَّةٗ مِّنۢ بَعۡدِهِمۡۖ أَفَتُهۡلِكُنَا بِمَا فَعَلَ ٱلۡمُبۡطِلُونَ ﴿١٧٣﴾ وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلَعَلَّهُمۡ يَرۡجِعُونَ ﴿١٧٤﴾", "w": [["وإذ نتقنا الجبل", "رفعناه من أصله فوق رؤوسهم."], ["خذوا ما آتيناكم بقوة", "التزموا بالقيام بما عُهد إليكم من أحكام التوراة بقوة."], ["واذكروا ما فيه", "لا تنسوا ما التزمتم به من النهوض بأحكام التوراة."], ["من ظهورهم ذريتهم", "أخرجهم من ظهر آدم ﵇ بأرض نعمان من عرفات."], ["وأشهدهم على أنفسهم", "أي بأنه تعالى ربهم وإلههم، ولا رب لهم غيره، ولا إله لهم سواه."], ["المبطلون", "العاملون بالشرك والمعاصي، إذ كلها باطل لا حق فيه."], ["نفصّل الآيات", "نبيّنها ونوضّحها بتنويع الأساليب وتكرار الحجج وضرب الأمثال وذكر القصص."]], "m": "خاتمة الحديث عن اليهود: واذكر إذ رفعنا جبل الطور من أصله فوقهم كأنه ظلة، وظنّوا أنه ساقط عليهم، وقلنا: خذوا ما آتيناكم من أحكام التوراة بقوة، والتزموا بكل ما أمرت به ونهت عنه، واذكروا ما فيه ولا تنسوه لعلكم تتقون. ثم ذكر حادثة جديرة بالاعتبار: إن الله أخرج من صلب آدم ذريته، فأنطقها بقدرته فنطقت وعقلت الخطاب، واستشهدها فشهدت: ألست بربكم؟ قالوا: بلى شهدنا، وهذا العهد العام الذي أُخذ على بني آدم وسيُطالبون به، أن تقولوا يوم القيامة: إنا كنا عن هذا غافلين، أو تقولوا: إنما أشرك آباؤنا من قبل وكنا ذرية من بعدهم، أفتهلكنا بما فعل المبطلون؟ والعبرة: أن الإنسان سرعان ما ينسى، ويعاهد ولا يفي، وما وُجد في بني إسرائيل من عدم الوفاء عائد إلى أصل الإنسان، والأعظم أن التوحيد أُخذ به العهد على كل آدمي، وأكثرهم ينكرونه. وكذلك نفصّل الآيات لعلهم يرجعون إلى الحق.", "h": ["بيان نفسيات اليهود، وأنها نفسية غريبة، وإلا كيف وهم بين يدي الله يرفضون الالتزام بما عُهد إليهم حتى يُرفع فوقهم الطور تهديداً، وعندئذ التزموا، ولم يلبثوا إلا قليلاً حتى نقضوا عهدهم.", "عجيب تدبير الله تعالى في خلقه.", "الكافر كفر مرتين: كفر بالعهد الذي أُخذ عليه وهو في عالم الذر، وكفر بالله وهو في عالم الشهادة، والمؤمن آمن مرتين، فلذا يضاعف للأول العذاب، ويضاعف للثاني الأجر.", "تقرير مبدأ الخليقة، ومبدأ المعاد الآخر."], "k": "«ألست بربكم؟ قالوا بلى»… شهدت بها قبل أن أولد؛ فهل حياتي اليوم تصدّق تلك الشهادة؟"}, {"lbl": "الآيات ١٧٥ – ١٧٨", "q": "وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱلَّذِيٓ ءَاتَيۡنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنۡهَا فَأَتۡبَعَهُ ٱلشَّيۡطَٰنُ فَكَانَ مِنَ ٱلۡغَاوِينَ ﴿١٧٥﴾ وَلَوۡ شِئۡنَا لَرَفَعۡنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخۡلَدَ إِلَى ٱلۡأَرۡضِ وَٱتَّبَعَ هَوَىٰهُۚ فَمَثَلُهُۥ كَمَثَلِ ٱلۡكَلۡبِ إِن تَحۡمِلۡ عَلَيۡهِ يَلۡهَثۡ أَوۡ تَتۡرُكۡهُ يَلۡهَثۚ ذَّـٰلِكَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۚ فَٱقۡصُصِ ٱلۡقَصَصَ لَعَلَّهُمۡ يَتَفَكَّرُونَ ﴿١٧٦﴾ سَآءَ مَثَلًا ٱلۡقَوۡمُ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَأَنفُسَهُمۡ كَانُواْ يَظۡلِمُونَ ﴿١٧٧﴾ مَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِيۖ وَمَن يُضۡلِلۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ﴿١٧٨﴾", "w": [["نبأ", "خبر ذو شأن."], ["فانسلخ منها", "ترك الآيات وابتعد عنها، فلم يتلها ولم يعمل بها."], ["فأتبعه الشيطان", "لحقه وأدركه."], ["من الغاوين", "من الضالين غير المهتدين، الهالكين غير الناجين."], ["أخلد إلى الأرض", "مال إلى الدنيا وركن إليها، وأصبح لا همّ له إلا الدنيا."], ["يلهث", "اللهث: التنفّس الشديد مع إخراج اللسان من التعب والإعياء."], ["ساء", "قبُح."], ["مثلاً", "أي صفة."]], "m": "واتلُ على قومك وعلى كل من يبلغه هذا الكتاب نبأ الذي آتيناه آياتنا تحمل الأدلة والشرائع والآداب، فانسلخ منها، فلم يتلها ولم يفكّر فيها ولم يعمل بها، فأتبعه الشيطان وتمكّن منه، إذ وجد بتخلّيه عن الآيات طريقاً إليه، فكان من الغاوين الهالكين. ولو شئنا لرفعناه بالآيات إلى قمم المجد والكمال وإلى الدرجات العلا، ولكنه أخلد إلى الأرض، فأكبّ على الشهوات والسرف في الملذّات، واتبع هواه وترك عقله ووحي ربه، فمثله كمثل الكلب في اللهث والإعياء والتبعية وعدم الاستقلال، إن تحمل عليه يلهث أو تتركه يلهث. ذلك مثل القوم الذين كذّبوا بآياتنا في كل زمان ومكان، فاقصص القصص لعلهم يتفكّرون فيرجعون إلى الحق. ساء مثلاً القوم الذين كذّبوا بآياتنا وأنفسهم كانوا يظلمون بتدنيسها بالشرك والمعاصي. من يهد الله فهو المهتدي بحق، ومن خذله لشدة إعراضه وتكبّره فأولئك هم الخاسرون.", "h": ["خطر شأن هذا الخبر الذي أمر الله رسوله أن يتلوه على الناس.", "ترك القرآن الكريم بعدم تلاوته والتدبّر فيه وترك العمل به مُفضٍ بالعبد إلى أن يكون هو صاحب المثل في هذه الآية: يتمكّن منه الشيطان فيصبح من الغواة، ثم يُخلد إلى الأرض فلا يكون له همّ إلا الدنيا، ثم يتبع هواه لا عقله ولا شرع الله، فإذا به صورة لكلب يلهث لا تنقطع حيرته واتباعه لغيره.", "لا رفعة ولا سيادة ولا كمال إلا بالعمل بالقرآن، لقوله تعالى: «ولو شئنا لرفعناه بها».", "الهداية بيد الله، فليطلبها من أرادها من الله بصدق القلب وإخلاص النية، فإن الله لا يحرمه منها، ومن أعرض عن الله أعرض الله عنه."], "k": "«ولكنه أخلد إلى الأرض واتبع هواه»… هل تشدّني الدنيا إلى الأرض كلما رفعني القرآن؟"}, {"lbl": "الآيات ١٧٩ – ١٨١", "q": "وَلَقَدۡ ذَرَأۡنَا لِجَهَنَّمَ كَثِيرٗا مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ لَهُمۡ قُلُوبٞ لَّا يَفۡقَهُونَ بِهَا وَلَهُمۡ أَعۡيُنٞ لَّا يُبۡصِرُونَ بِهَا وَلَهُمۡ ءَاذَانٞ لَّا يَسۡمَعُونَ بِهَآۚ أُوْلَـٰٓئِكَ كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّۚ أُوْلَـٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ ﴿١٧٩﴾ وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ وَذَرُواْ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ أَسۡمَـٰٓئِهِۦۚ سَيُجۡزَوۡنَ مَا كَانُواْ يَعۡمَلُونَ ﴿١٨٠﴾ وَمِمَّنۡ خَلَقۡنَآ أُمَّةٞ يَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ ﴿١٨١﴾", "w": [["ذرأنا لجهنم", "خلقنا لجهنم، أي للتعذيب بها والاستقرار فيها."], ["لا يفقهون بها", "كلام الله ولا كلام رسوله."], ["لا يبصرون بها", "آيات الله في الكون."], ["لا يسمعون بها", "الحق والمعروف."], ["كالأنعام", "البهائم في عدم الانتفاع بقلوبهم وأبصارهم وأسماعهم."], ["الغافلون", "عن آيات الله وما خُلقوا له وما يُراد لهم وبهم."], ["ولله الأسماء الحسنى", "الأسماء جمع اسم، والحسنى مؤنث الأحسن، والأسماء الحسنى لله خاصة، فلا يشاركه فيها أحد."], ["وذروا", "اتركوا."], ["يُلحدون", "يميلون بها إلى الباطل."], ["وممن خلقنا", "أي من الناس."]], "m": "على إثر ذكر الهدى والضلال، أخبر الله أنه خلق لجهنم كثيراً من الجن والإنس، علماً منه بأنهم يرفضون هدايته ويتكبّرون عن عبادته ويحاربون رسله، فعطّل ذلك حواسّهم: لهم قلوب لا يفقهون بها، وأعين لا يبصرون بها، وآذان لا يسمعون بها، أولئك كالأنعام بل هم أضل، لأن الأنعام لم تخرج عن الطريق الذي خُلقت له، وهؤلاء خرجوا عن الطريق الذي خُلقوا له، وهو عبادة الله وحده، أولئك هم الغافلون عن آيات الله الكونية فلا يتأمّلونها، والتنزيلية فلا يتدبّرونها. ولله الأسماء الحسنى، خاصة به، وأخبر النبي ﷺ أنها تسعة وتسعون اسماً، فادعوه بها: يا الله، يا رحمن، يا رحيم، يا حي يا قيوم، وذروا أهل الزيغ الذين يُلحدون في أسمائه فيؤوّلونها أو يعطّلونها أو يشبّهونها، سيُجزون ما كانوا يعملون. وممن خلقنا أمة كبيرة يهدون أنفسهم وغيرهم بالحق، وبه يعدلون في قضائهم فينصفون ولا يجورون، ومنها كل صالح في أمة الإسلام يعيش على الكتاب والسنة اعتقاداً وقولاً وعملاً وحكماً وخلقاً.", "h": ["تقرير مبدأ أن السعادة والشقاء سبق بهما قلم القضاء والقدر، فكلٌّ ميسّر لما خُلق له.", "هبوط الآدمي إلى درك أهبط من درك الحيوان، وذلك عندما يكفر بربه ويعطّل حواسّه عن الانتفاع بها، ويقصر همّه على الحياة الدنيا.", "بيان أن البلاء كامن في الغفلة عن آيات الله والإعراض عنها.", "الأمر بدعاء الله تعالى بأسمائه الحسنى، نحو: يا رب، يا رحمن، يا عزيز، يا جبار.", "حرمة تأويل أسماء الله وصفاته وتحريفها، كما قال المشركون في الله: اللات، وفي العزيز: العزى، سمّوا بها آلهتهم الباطلة، وهو الإلحاد الذي توعّد الله أهله بالجزاء عليه.", "أهل الجنة الذين خُلقوا لها هم الذين يهدون بالكتاب والسنة ويقضون بهما."], "k": "«ولله الأسماء الحسنى فادعوه بها»… بأي اسم من أسمائه أدعوه اليوم في حاجتي؟"}, {"lbl": "الآيات ١٨٢ – ١٨٦", "q": "وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ ﴿١٨٢﴾ وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ ﴿١٨٣﴾ أَوَلَمۡ يَتَفَكَّرُواْۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِيرٞ مُّبِينٌ ﴿١٨٤﴾ أَوَلَمۡ يَنظُرُواْ فِي مَلَكُوتِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا خَلَقَ ٱللَّهُ مِن شَيۡءٖ وَأَنۡ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقۡتَرَبَ أَجَلُهُمۡۖ فَبِأَيِّ حَدِيثِۭ بَعۡدَهُۥ يُؤۡمِنُونَ ﴿١٨٥﴾ مَن يُضۡلِلِ ٱللَّهُ فَلَا هَادِيَ لَهُۥۚ وَيَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ ﴿١٨٦﴾", "w": [["كذّبوا بآياتنا", "أي بآيات القرآن الكريم."], ["سنستدرجهم", "نستميلهم وهم هابطون إلى هوّة العذاب درجة بعد درجة، مع تماديهم في التكذيب، حتى يبلغوا الأجل المحدّد لهم ثم يُؤخذوا أخذة واحدة."], ["ما بصاحبهم من جِنّة", "صاحبهم هو محمد ﷺ، والجِنّة: الجنون، والمتحدّث عنهم كفار قريش."], ["ملكوت السماوات", "ملك السماوات، إلا أن لفظ الملكوت أعظم من لفظ الملك."], ["فبأي حديث بعده", "أي بعد القرآن العظيم."], ["ونذرهم في طغيانهم", "نتركهم في كفرهم وظلمهم."], ["يعمهون", "حيارى يتردّدون لا يعرفون مخرجاً ولا سبيلاً للنجاة."]], "m": "يخبر الله أن الذين كذّبوا بآياته وأصرّوا على الشرك سيستدرجهم شيئاً فشيئاً حتى يحق عليهم العذاب، ويُملي لهم كيداً بهم، فيطيل زمن كفرهم ويزيد في أرزاقهم وأموالهم حتى يفقدوا الاستعداد للتوبة، ثم يأخذهم أخذ عزيز مقتدر، إن كيدي متين قوي. أوَلم يتفكّروا في سلوك الرسول ﷺ وتصرّفاته الرشيدة الحكيمة فيعلموا أنه ما به من جنون كما يزعمون، إن هو إلا نذير مبين؟ أوَلم ينظروا في ملكوت السماوات والأرض وما فيه من مظاهر القدرة والعلم والحكمة، وما خلق الله من شيء، من النملة إلى النخلة ومن الحبة إلى القبة، فيعلموا أن المستحق للعبادة خالقه لا الأصنام، وأن عسى أن يكون قد اقترب أجلهم، فيعجّلوا بالتوبة؟ فبأي حديث بعد القرآن، وكله حجج وبراهين، يؤمنون؟ من يضلل الله فلا هادي له، ويذرهم في طغيانهم حيارى لا يدرون أين يتّجهون حتى يهلكوا.", "h": ["عظم خطر التكذيب بالقرآن الكريم، حتى إن المكذّب ليُستدرج حتى يهلك وهو لا يشعر.", "أكبر موعظة: أن على الإنسان أن يذكر دائماً أن أجله قد يكون قريباً وهو لا يدري، فيأخذ بالحذر والحيطة حتى لا يُؤخذ على غير توبة فيخسر.", "من لا يتّعظ بالقرآن وما فيه من الزواجر والعظات والعبر لا يتّعظ بغيره.", "من أعرض عن كتاب الله مكذّباً بما فيه من الهدى ضلّ، لا تُرجى له هداية أبداً."], "k": "«وأن عسى أن يكون قد اقترب أجلهم»… لو كان أجلي قريباً، فما الذي أعجّل به اليوم؟"}]$j$::jsonb then 0 else 1 end;
