insert into public.tdb_cards(topic, i, body) select 112, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٧١ – ١٧٤", "q": "۞وَإِذۡ نَتَقۡنَا ٱلۡجَبَلَ فَوۡقَهُمۡ كَأَنَّهُۥ ظُلَّةٞ وَظَنُّوٓاْ أَنَّهُۥ وَاقِعُۢ بِهِمۡ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ ﴿١٧١﴾ وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ وَأَشۡهَدَهُمۡ عَلَىٰٓ أَنفُسِهِمۡ أَلَسۡتُ بِرَبِّكُمۡۖ قَالُواْ بَلَىٰ شَهِدۡنَآۚ أَن تَقُولُواْ يَوۡمَ ٱلۡقِيَٰمَةِ إِنَّا كُنَّا عَنۡ هَٰذَا غَٰفِلِينَ ﴿١٧٢﴾ أَوۡ تَقُولُوٓاْ إِنَّمَآ أَشۡرَكَ ءَابَآؤُنَا مِن قَبۡلُ وَكُنَّا ذُرِّيَّةٗ مِّنۢ بَعۡدِهِمۡۖ أَفَتُهۡلِكُنَا بِمَا فَعَلَ ٱلۡمُبۡطِلُونَ ﴿١٧٣﴾ وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلَعَلَّهُمۡ يَرۡجِعُونَ ﴿١٧٤﴾", "w": [["وإذ نتقنا الجبل", "رفعناه من أصله فوق رؤوسهم."], ["خذوا ما آتيناكم بقوة", "التزموا بالقيام بما عُهد إليكم من أحكام التوراة بقوة."], ["واذكروا ما فيه", "لا تنسوا ما التزمتم به من النهوض بأحكام التوراة."], ["من ظهورهم ذريتهم", "أخرجهم من ظهر آدم ﵇ بأرض نعمان من عرفات."], ["وأشهدهم على أنفسهم", "أي بأنه تعالى ربهم وإلههم، ولا رب لهم غيره، ولا إله لهم سواه."], ["المبطلون", "العاملون بالشرك والمعاصي، إذ كلها باطل لا حق فيه."], ["نفصّل الآيات", "نبيّنها ونوضّحها بتنويع الأساليب وتكرار الحجج وضرب الأمثال وذكر القصص."]], "m": "خاتمة الحديث عن اليهود: واذكر إذ رفعنا جبل الطور من أصله فوقهم كأنه ظلة، وظنّوا أنه ساقط عليهم، وقلنا: خذوا ما آتيناكم من أحكام التوراة بقوة، والتزموا بكل ما أمرت به ونهت عنه، واذكروا ما فيه ولا تنسوه لعلكم تتقون. ثم ذكر حادثة جديرة بالاعتبار: إن الله أخرج من صلب آدم ذريته، فأنطقها بقدرته فنطقت وعقلت الخطاب، واستشهدها فشهدت: ألست بربكم؟ قالوا: بلى شهدنا، وهذا العهد العام الذي أُخذ على بني آدم وسيُطالبون به، أن تقولوا يوم القيامة: إنا كنا عن هذا غافلين، أو تقولوا: إنما أشرك آباؤنا من قبل وكنا ذرية من بعدهم، أفتهلكنا بما فعل المبطلون؟ والعبرة: أن الإنسان سرعان ما ينسى، ويعاهد ولا يفي، وما وُجد في بني إسرائيل من عدم الوفاء عائد إلى أصل الإنسان، والأعظم أن التوحيد أُخذ به العهد على كل آدمي، وأكثرهم ينكرونه. وكذلك نفصّل الآيات لعلهم يرجعون إلى الحق.", "h": ["بيان نفسيات اليهود، وأنها نفسية غريبة، وإلا كيف وهم بين يدي الله يرفضون الالتزام بما عُهد إليهم حتى يُرفع فوقهم الطور تهديداً، وعندئذ التزموا، ولم يلبثوا إلا قليلاً حتى نقضوا عهدهم.", "عجيب تدبير الله تعالى في خلقه.", "الكافر كفر مرتين: كفر بالعهد الذي أُخذ عليه وهو في عالم الذر، وكفر بالله وهو في عالم الشهادة، والمؤمن آمن مرتين، فلذا يضاعف للأول العذاب، ويضاعف للثاني الأجر.", "تقرير مبدأ الخليقة، ومبدأ المعاد الآخر."], "k": "«ألست بربكم؟ قالوا بلى»… شهدت بها قبل أن أولد؛ فهل حياتي اليوم تصدّق تلك الشهادة؟"}, {"lbl": "الآيات ١٧٥ – ١٧٨", "q": "وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱلَّذِيٓ ءَاتَيۡنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنۡهَا فَأَتۡبَعَهُ ٱلشَّيۡطَٰنُ فَكَانَ مِنَ ٱلۡغَاوِينَ ﴿١٧٥﴾ وَلَوۡ شِئۡنَا لَرَفَعۡنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخۡلَدَ إِلَى ٱلۡأَرۡضِ وَٱتَّبَعَ هَوَىٰهُۚ فَمَثَلُهُۥ كَمَثَلِ ٱلۡكَلۡبِ إِن تَحۡمِلۡ عَلَيۡهِ يَلۡهَثۡ أَوۡ تَتۡرُكۡهُ يَلۡهَثۚ ذَّـٰلِكَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۚ فَٱقۡصُصِ ٱلۡقَصَصَ لَعَلَّهُمۡ يَتَفَكَّرُونَ ﴿١٧٦﴾ سَآءَ مَثَلًا ٱلۡقَوۡمُ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَأَنفُسَهُمۡ كَانُواْ يَظۡلِمُونَ ﴿١٧٧﴾ مَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِيۖ وَمَن يُضۡلِلۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ﴿١٧٨﴾", "w": [["نبأ", "خبر ذو شأن."], ["فانسلخ منها", "ترك الآيات وابتعد عنها، فلم يتلها ولم يعمل بها."], ["فأتبعه الشيطان", "لحقه وأدركه."], ["من الغاوين", "من الضالين غير المهتدين، الهالكين غير الناجين."], ["أخلد إلى الأرض", "مال إلى الدنيا وركن إليها، وأصبح لا همّ له إلا الدنيا."], ["يلهث", "اللهث: التنفّس الشديد مع إخراج اللسان من التعب والإعياء."], ["ساء", "قبُح."], ["مثلاً", "أي صفة."]], "m": "واتلُ على قومك وعلى كل من يبلغه هذا الكتاب نبأ الذي آتيناه آياتنا تحمل الأدلة والشرائع والآداب، فانسلخ منها، فلم يتلها ولم يفكّر فيها ولم يعمل بها، فأتبعه الشيطان وتمكّن منه، إذ وجد بتخلّيه عن الآيات طريقاً إليه، فكان من الغاوين الهالكين. ولو شئنا لرفعناه بالآيات إلى قمم المجد والكمال وإلى الدرجات العلا، ولكنه أخلد إلى الأرض، فأكبّ على الشهوات والسرف في الملذّات، واتبع هواه وترك عقله ووحي ربه، فمثله كمثل الكلب في اللهث والإعياء والتبعية وعدم الاستقلال، إن تحمل عليه يلهث أو تتركه يلهث. ذلك مثل القوم الذين كذّبوا بآياتنا في كل زمان ومكان، فاقصص القصص لعلهم يتفكّرون فيرجعون إلى الحق. ساء مثلاً القوم الذين كذّبوا بآياتنا وأنفسهم كانوا يظلمون بتدنيسها بالشرك والمعاصي. من يهد الله فهو المهتدي بحق، ومن خذله لشدة إعراضه وتكبّره فأولئك هم الخاسرون.", "h": ["خطر شأن هذا الخبر الذي أمر الله رسوله أن يتلوه على الناس.", "ترك القرآن الكريم بعدم تلاوته والتدبّر فيه وترك العمل به مُفضٍ بالعبد إلى أن يكون هو صاحب المثل في هذه الآية: يتمكّن منه الشيطان فيصبح من الغواة، ثم يُخلد إلى الأرض فلا يكون له همّ إلا الدنيا، ثم يتبع هواه لا عقله ولا شرع الله، فإذا به صورة لكلب يلهث لا تنقطع حيرته واتباعه لغيره.", "لا رفعة ولا سيادة ولا كمال إلا بالعمل بالقرآن، لقوله تعالى: «ولو شئنا لرفعناه بها».", "الهداية بيد الله، فليطلبها من أرادها من الله بصدق القلب وإخلاص النية، فإن الله لا يحرمه منها، ومن أعرض عن الله أعرض الله عنه."], "k": "«ولكنه أخلد إلى الأرض واتبع هواه»… هل تشدّني الدنيا إلى الأرض كلما رفعني القرآن؟"}, {"lbl": "الآيات ١٧٩ – ١٨١", "q": "وَلَقَدۡ ذَرَأۡنَا لِجَهَنَّمَ كَثِيرٗا مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ لَهُمۡ قُلُوبٞ لَّا يَفۡقَهُونَ بِهَا وَلَهُمۡ أَعۡيُنٞ لَّا يُبۡصِرُونَ بِهَا وَلَهُمۡ ءَاذَانٞ لَّا يَسۡمَعُونَ بِهَآۚ أُوْلَـٰٓئِكَ كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّۚ أُوْلَـٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ ﴿١٧٩﴾ وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ وَذَرُواْ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ أَسۡمَـٰٓئِهِۦۚ سَيُجۡزَوۡنَ مَا كَانُواْ يَعۡمَلُونَ ﴿١٨٠﴾ وَمِمَّنۡ خَلَقۡنَآ أُمَّةٞ يَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ ﴿١٨١﴾", "w": [["ذرأنا لجهنم", "خلقنا لجهنم، أي للتعذيب بها والاستقرار فيها."], ["لا يفقهون بها", "كلام الله ولا كلام رسوله."], ["لا يبصرون بها", "آيات الله في الكون."], ["لا يسمعون بها", "الحق والمعروف."], ["كالأنعام", "البهائم في عدم الانتفاع بقلوبهم وأبصارهم وأسماعهم."], ["الغافلون", "عن آيات الله وما خُلقوا له وما يُراد لهم وبهم."], ["ولله الأسماء الحسنى", "الأسماء جمع اسم، والحسنى مؤنث الأحسن، والأسماء الحسنى لله خاصة، فلا يشاركه فيها أحد."], ["وذروا", "اتركوا."], ["يُلحدون", "يميلون بها إلى الباطل."], ["وممن خلقنا", "أي من الناس."]], "m": "على إثر ذكر الهدى والضلال، أخبر الله أنه خلق لجهنم كثيراً من الجن والإنس، علماً منه بأنهم يرفضون هدايته ويتكبّرون عن عبادته ويحاربون رسله، فعطّل ذلك حواسّهم: لهم قلوب لا يفقهون بها، وأعين لا يبصرون بها، وآذان لا يسمعون بها، أولئك كالأنعام بل هم أضل، لأن الأنعام لم تخرج عن الطريق الذي خُلقت له، وهؤلاء خرجوا عن الطريق الذي خُلقوا له، وهو عبادة الله وحده، أولئك هم الغافلون عن آيات الله الكونية فلا يتأمّلونها، والتنزيلية فلا يتدبّرونها. ولله الأسماء الحسنى، خاصة به، وأخبر النبي ﷺ أنها تسعة وتسعون اسماً، فادعوه بها: يا الله، يا رحمن، يا رحيم، يا حي يا قيوم، وذروا أهل الزيغ الذين يُلحدون في أسمائه فيؤوّلونها أو يعطّلونها أو يشبّهونها، سيُجزون ما كانوا يعملون. وممن خلقنا أمة كبيرة يهدون أنفسهم وغيرهم بالحق، وبه يعدلون في قضائهم فينصفون ولا يجورون، ومنها كل صالح في أمة الإسلام يعيش على الكتاب والسنة اعتقاداً وقولاً وعملاً وحكماً وخلقاً.", "h": ["تقرير مبدأ أن السعادة والشقاء سبق بهما قلم القضاء والقدر، فكلٌّ ميسّر لما خُلق له.", "هبوط الآدمي إلى درك أهبط من درك الحيوان، وذلك عندما يكفر بربه ويعطّل حواسّه عن الانتفاع بها، ويقصر همّه على الحياة الدنيا.", "بيان أن البلاء كامن في الغفلة عن آيات الله والإعراض عنها.", "الأمر بدعاء الله تعالى بأسمائه الحسنى، نحو: يا رب، يا رحمن، يا عزيز، يا جبار.", "حرمة تأويل أسماء الله وصفاته وتحريفها، كما قال المشركون في الله: اللات، وفي العزيز: العزى، سمّوا بها آلهتهم الباطلة، وهو الإلحاد الذي توعّد الله أهله بالجزاء عليه.", "أهل الجنة الذين خُلقوا لها هم الذين يهدون بالكتاب والسنة ويقضون بهما."], "k": "«ولله الأسماء الحسنى فادعوه بها»… بأي اسم من أسمائه أدعوه اليوم في حاجتي؟"}, {"lbl": "الآيات ١٨٢ – ١٨٦", "q": "وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ ﴿١٨٢﴾ وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ ﴿١٨٣﴾ أَوَلَمۡ يَتَفَكَّرُواْۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِيرٞ مُّبِينٌ ﴿١٨٤﴾ أَوَلَمۡ يَنظُرُواْ فِي مَلَكُوتِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا خَلَقَ ٱللَّهُ مِن شَيۡءٖ وَأَنۡ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقۡتَرَبَ أَجَلُهُمۡۖ فَبِأَيِّ حَدِيثِۭ بَعۡدَهُۥ يُؤۡمِنُونَ ﴿١٨٥﴾ مَن يُضۡلِلِ ٱللَّهُ فَلَا هَادِيَ لَهُۥۚ وَيَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ ﴿١٨٦﴾", "w": [["كذّبوا بآياتنا", "أي بآيات القرآن الكريم."], ["سنستدرجهم", "نستميلهم وهم هابطون إلى هوّة العذاب درجة بعد درجة، مع تماديهم في التكذيب، حتى يبلغوا الأجل المحدّد لهم ثم يُؤخذوا أخذة واحدة."], ["ما بصاحبهم من جِنّة", "صاحبهم هو محمد ﷺ، والجِنّة: الجنون، والمتحدّث عنهم كفار قريش."], ["ملكوت السماوات", "ملك السماوات، إلا أن لفظ الملكوت أعظم من لفظ الملك."], ["فبأي حديث بعده", "أي بعد القرآن العظيم."], ["ونذرهم في طغيانهم", "نتركهم في كفرهم وظلمهم."], ["يعمهون", "حيارى يتردّدون لا يعرفون مخرجاً ولا سبيلاً للنجاة."]], "m": "يخبر الله أن الذين كذّبوا بآياته وأصرّوا على الشرك سيستدرجهم شيئاً فشيئاً حتى يحق عليهم العذاب، ويُملي لهم كيداً بهم، فيطيل زمن كفرهم ويزيد في أرزاقهم وأموالهم حتى يفقدوا الاستعداد للتوبة، ثم يأخذهم أخذ عزيز مقتدر، إن كيدي متين قوي. أوَلم يتفكّروا في سلوك الرسول ﷺ وتصرّفاته الرشيدة الحكيمة فيعلموا أنه ما به من جنون كما يزعمون، إن هو إلا نذير مبين؟ أوَلم ينظروا في ملكوت السماوات والأرض وما فيه من مظاهر القدرة والعلم والحكمة، وما خلق الله من شيء، من النملة إلى النخلة ومن الحبة إلى القبة، فيعلموا أن المستحق للعبادة خالقه لا الأصنام، وأن عسى أن يكون قد اقترب أجلهم، فيعجّلوا بالتوبة؟ فبأي حديث بعد القرآن، وكله حجج وبراهين، يؤمنون؟ من يضلل الله فلا هادي له، ويذرهم في طغيانهم حيارى لا يدرون أين يتّجهون حتى يهلكوا.", "h": ["عظم خطر التكذيب بالقرآن الكريم، حتى إن المكذّب ليُستدرج حتى يهلك وهو لا يشعر.", "أكبر موعظة: أن على الإنسان أن يذكر دائماً أن أجله قد يكون قريباً وهو لا يدري، فيأخذ بالحذر والحيطة حتى لا يُؤخذ على غير توبة فيخسر.", "من لا يتّعظ بالقرآن وما فيه من الزواجر والعظات والعبر لا يتّعظ بغيره.", "من أعرض عن كتاب الله مكذّباً بما فيه من الهدى ضلّ، لا تُرجى له هداية أبداً."], "k": "«وأن عسى أن يكون قد اقترب أجلهم»… لو كان أجلي قريباً، فما الذي أعجّل به اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (113, 7, 187, 206, 'سورة الأعراف ١٨٧ – ٢٠٦', '«يسألونك عن الساعة»، «خذ العفو وأمر بالعرف»، و«وإذا قُرئ القرآن فاستمعوا له وأنصتوا»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 113) = $j$[{"lbl": "الآيتان ١٨٧ – ١٨٨", "q": "يَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرۡسَىٰهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ رَبِّيۖ لَا يُجَلِّيهَا لِوَقۡتِهَآ إِلَّا هُوَۚ ثَقُلَتۡ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ لَا تَأۡتِيكُمۡ إِلَّا بَغۡتَةٗۗ يَسۡـَٔلُونَكَ كَأَنَّكَ حَفِيٌّ عَنۡهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿١٨٧﴾ قُل لَّآ أَمۡلِكُ لِنَفۡسِي نَفۡعٗا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُۚ وَلَوۡ كُنتُ أَعۡلَمُ ٱلۡغَيۡبَ لَٱسۡتَكۡثَرۡتُ مِنَ ٱلۡخَيۡرِ وَمَا مَسَّنِيَ ٱلسُّوٓءُۚ إِنۡ أَنَا۠ إِلَّا نَذِيرٞ وَبَشِيرٞ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿١٨٨﴾", "w": [["الساعة", "الوقت الذي تنتهي فيه الحياة الدنيا بالفناء."], ["أيّان مرساها", "متى وقت قيامها؟"], ["لا يجلّيها لوقتها", "لا يظهرها في وقتها المحدّد لها إلا هو سبحانه وتعالى."], ["بغتة", "فجأة، بدون توقّع أو انتظار."], ["حفيّ عنها", "ملحف مبالغ في السؤال عنها حتى أصبحت تعرف وقت مجيئها."], ["الغيب", "ما غاب عن حواسنا وعقولنا فلم يُدرك بحاسة ولا بعقل، والمراد به هنا ما سيحدث في المستقبل القريب أو البعيد."], ["السوء", "كل ما يسوء العبد في روحه أو بدنه."], ["إن أنا إلا نذير", "ما أنا إلا نذير وبشير، فلست بإله يدبّر الأمر ويعلم الغيب."]], "m": "سأل أفراد من قريش أو غيرهم النبي ﷺ عن الساعة متى قيامها، فعلّمه ربه الجواب: يسألونك عن الساعة أيّان مرساها؟ قل إنما علمها عند ربي خاصة، لا يجلّيها لوقتها إلا هو، ثقُلت في السماوات والأرض، ثقل أمر علمها على أهلها، لا تأتيكم إلا بغتة. يسألونك كأنك حفيّ عنها، ملحف في السؤال حتى عرفتها، قل إنما علمها عند الله، ولكن أكثر الناس لا يعلمون أن إخفاءها لحكم عالية، ولولا الجهل ما سألوا. وأمره أن يقول: لا أملك لنفسي نفعاً ولا ضراً إلا ما شاء الله، ولو كنت أعلم الغيب لاستكثرت من الخير وما مسّني السوء، فلست بإله أعلم الغيب، إن أنا إلا نذير وبشير لقوم يؤمنون، ووظيفتي البشارة والنذارة ينتفع بها المؤمنون خاصة.", "h": ["مردّ علم الساعة إلى الله وحده، فكل مسؤول عنها غير الله ليس أعلم من السائل.", "للساعة أشراط، بعضها في الكتاب وبعضها في السنة، وليس معنى ذلك أنه تحديد لوقتها، وإنما هي مقدّمات تدل على قربها فقط.", "استأثر الله بعلم الغيب، فلا يعلم الغيب إلا الله، ومن علّمه الله شيئاً منه علم، كما علّم نبيه ﷺ بعض المغيّبات، والمعلَّم بالشيء لا يقال فيه يعلم الغيب، وإنما يقال: علّمه ربه غيب كذا وكذا فعلمه.", "إذا كان الرسول لا يملك لنفسه نفعاً ولا ضراً فكيف يُطلب منه ذلك؟ وإذا كان الرسول لا يملك فهل من دونه من العباد يملك؟ إذا عرفت هذا ظهر لك ضلال أقوام يدعون الموتى سائلين ضارعين عند قبورهم، ويقولون إنهم لا يدعونهم ولكن يتوسّلون بهم فقط."], "k": "«يسألونك عن الساعة أيّان مرساها»… السؤال المهم ليس «متى»، بل: ماذا أعددت لها؟"}, {"lbl": "الآيات ١٨٩ – ١٩٣", "q": "۞هُوَ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَجَعَلَ مِنۡهَا زَوۡجَهَا لِيَسۡكُنَ إِلَيۡهَاۖ فَلَمَّا تَغَشَّىٰهَا حَمَلَتۡ حَمۡلًا خَفِيفٗا فَمَرَّتۡ بِهِۦۖ فَلَمَّآ أَثۡقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنۡ ءَاتَيۡتَنَا صَٰلِحٗا لَّنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ ﴿١٨٩﴾ فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحٗا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَاۚ فَتَعَٰلَى ٱللَّهُ عَمَّا يُشۡرِكُونَ ﴿١٩٠﴾ أَيُشۡرِكُونَ مَا لَا يَخۡلُقُ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ ﴿١٩١﴾ وَلَا يَسۡتَطِيعُونَ لَهُمۡ نَصۡرٗا وَلَآ أَنفُسَهُمۡ يَنصُرُونَ ﴿١٩٢﴾ وَإِن تَدۡعُوهُمۡ إِلَى ٱلۡهُدَىٰ لَا يَتَّبِعُوكُمۡۚ سَوَآءٌ عَلَيۡكُمۡ أَدَعَوۡتُمُوهُمۡ أَمۡ أَنتُمۡ صَٰمِتُونَ ﴿١٩٣﴾", "w": [["من نفس واحدة", "هي نفس آدم ﵇."], ["وجعل منها زوجها", "خلق منها زوجها، وهي حواء، خلقها من ضلع آدم."], ["ليسكن إليها", "ليألفها ويأنس بها لكونها من جنسه."], ["فلما تغشّاها", "أي وطئها."], ["فمرّت به", "ذاهبة جائية تقضي حوائجها لخفّة الحمل في الأشهر الأولى."], ["فلما أثقلت", "أصبح الحمل ثقيلاً في بطنها."], ["لئن آتيتنا صالحاً", "ولداً صالحاً، ليس حيواناً بل إنساناً."], ["جعلا له شركاء", "سمّياه عبد الحارث، وهو عبد الله جل جلاله."], ["فتعالى الله عما يشركون", "أي أهل مكة، حيث أشركوا في عبادة الله أصناماً."], ["وإن تدعوهم إلى الهدى", "أي الأصنام، لا يتبعوكم."]], "m": "يقول الله للسائلين عن الساعة عناداً من أهل الشرك: هو الذي خلقكم من نفس واحدة، آدم، وخلق منها زوجها حواء، هو المستحق للعبادة دون الأصنام، ليسكن إليها، إذ لو كانت من جنس آخر لما حصلت الألفة والأنس. فلما تغشّاها حملت حملاً خفيفاً فمرّت به، فلما أثقلت دعوا الله ربهما: لئن آتيتنا غلاماً صالحاً لنكوننّ من الشاكرين، فاستجاب لهما، فلما آتاهما صالحاً جعلا له شركاء فيما آتاهما، حيث سمّته حواء عبد الحارث بتغرير من إبليس، وهو من الشرك الخفي المعفوّ عنه، نحو: لولا الطبيب هلك فلان. فتعالى الله عما يشركون، عائد إلى كفار قريش، بدليل ما بعده: أيشركون ما لا يخلق شيئاً وهم يُخلقون، ولا يستطيعون لهم نصراً ولا أنفسهم ينصرون، لأنهم جمادات؟ وإن تدعوهم إلى الهدى لا يتبعوكم، سواء عليكم أدعوتموهم أم أنتم صامتون، فهل يصح أن يُعبد هذا، وتُقرّب له القرابين، ويُحلف به، ويُعكف عنده، ويُستغاث به؟", "h": ["بيان أصل خلق البشر، وهو آدم وحواء ﵉.", "بيان السر في كون الزوج من جنس الزوج، وهو الألفة والأنس والتعاون.", "بيان خداع إبليس وتضليله للإنسان، حيث زيّن لحواء تسمية ولدها بعبد الحارث.", "الشرك في التسمية شرك خفي معفوّ عنه، وتركه أولى.", "التنديد بالشرك والمشركين، وبيان جهل المشركين وسفههم، إذ يعبدون ما لا يسمع ولا يبصر ولا يجيب ولا يتبع."], "k": "«لئن آتيتنا صالحاً لنكوننّ من الشاكرين»… كم وعدت ربي بالشكر في الشدة، ثم نسيته بعد العطاء؟"}, {"lbl": "الآيات ١٩٤ – ١٩٨", "q": "إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمۡثَالُكُمۡۖ فَٱدۡعُوهُمۡ فَلۡيَسۡتَجِيبُواْ لَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٩٤﴾ أَلَهُمۡ أَرۡجُلٞ يَمۡشُونَ بِهَآۖ أَمۡ لَهُمۡ أَيۡدٖ يَبۡطِشُونَ بِهَآۖ أَمۡ لَهُمۡ أَعۡيُنٞ يُبۡصِرُونَ بِهَآۖ أَمۡ لَهُمۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۗ قُلِ ٱدۡعُواْ شُرَكَآءَكُمۡ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ ﴿١٩٥﴾ إِنَّ وَلِـِّۧيَ ٱللَّهُ ٱلَّذِي نَزَّلَ ٱلۡكِتَٰبَۖ وَهُوَ يَتَوَلَّى ٱلصَّـٰلِحِينَ ﴿١٩٦﴾ وَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ لَا يَسۡتَطِيعُونَ نَصۡرَكُمۡ وَلَآ أَنفُسَهُمۡ يَنصُرُونَ ﴿١٩٧﴾ وَإِن تَدۡعُوهُمۡ إِلَى ٱلۡهُدَىٰ لَا يَسۡمَعُواْۖ وَتَرَىٰهُمۡ يَنظُرُونَ إِلَيۡكَ وَهُمۡ لَا يُبۡصِرُونَ ﴿١٩٨﴾", "w": [["عباد أمثالكم", "مملوكون مخلوقون أمثالكم لمالك واحد هو الله رب العالمين."], ["شركاءكم", "أصنامكم التي تشركون بها."], ["ثم كيدون", "بما استطعتم من أنواع الكيد."], ["فلا تُنظرون", "فلا تمهلون، لأني لا أبالي بكم."], ["إن وليّي الله", "المتولّي أموري وحمايتي ونصرتي الله الذي نزّل القرآن."], ["وتراهم ينظرون", "ترى الأصنام المنحوتة على شكل رجال ينظرون إليك وهم لا يبصرون."]], "m": "هذه الآيات مقرّرة لمبدأ التوحيد مندّدة بالشرك: إن الذين تدعون من دون الله دعاء عبادة عباد أمثالكم، مملوكون لله كما أنتم مملوكون، لا يملكون لكم ولا لأنفسهم نفعاً، فادعوهم فليستجيبوا لكم إن كنتم صادقين أنهم آلهة، وكيف يستجيبون وهم جماد؟ ألهم أرجل يمشون بها؟ أم لهم أيد يبطشون بها؟ أم لهم أعين يبصرون بها؟ أم لهم آذان يسمعون بها؟ لا شيء من ذلك، فبأي حق يُعبدون؟ ثم أمر رسوله أن يعلن أنه لا يخافهم ولا يعبأ بهم: قل ادعوا شركاءكم ثم كيدون فلا تُنظرون ساعة، إن وليّي الله الذي نزّل الكتاب، وهو يتولّى الصالحين، فينصرني منكم ويحميني من كيدكم، والذين تدعون من دونه لا يستطيعون نصركم ولا أنفسهم ينصرون، وإن تدعوهم إلى الهدى لا يسمعوا، وتراهم، تماثيل من حجارة، ينظرون إليك بأعينهم المفتوحة دائماً وهم لا يبصرون.", "h": ["إقامة الحجة على المشركين بالكشف عن حقيقة ما يدّعون أنها آلهة، فإذا بها أصنام لا تسمع ولا تجيب، لا أيد لها ولا أرجل ولا آذان ولا أعين.", "وجوب التوكل على الله تعالى، وطرد الخوف من النفس، والوقوف أمام الباطل وأهله في شجاعة وصبر وثبات، اعتماداً على الله تعالى وولايته، إذ هو يتولّى الصالحين.", "جواز المبالغة في التنفير من الباطل والشر بذكر العيوب والنقائص."], "k": "«إن وليّي الله الذي نزّل الكتاب وهو يتولّى الصالحين»… هل أطلب ولاية الله بأن أكون من الصالحين؟"}, {"lbl": "الآيات ١٩٩ – ٢٠٢", "q": "خُذِ ٱلۡعَفۡوَ وَأۡمُرۡ بِٱلۡعُرۡفِ وَأَعۡرِضۡ عَنِ ٱلۡجَٰهِلِينَ ﴿١٩٩﴾ وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَٰنِ نَزۡغٞ فَٱسۡتَعِذۡ بِٱللَّهِۚ إِنَّهُۥ سَمِيعٌ عَلِيمٌ ﴿٢٠٠﴾ إِنَّ ٱلَّذِينَ ٱتَّقَوۡاْ إِذَا مَسَّهُمۡ طَـٰٓئِفٞ مِّنَ ٱلشَّيۡطَٰنِ تَذَكَّرُواْ فَإِذَا هُم مُّبۡصِرُونَ ﴿٢٠١﴾ وَإِخۡوَٰنُهُمۡ يَمُدُّونَهُمۡ فِي ٱلۡغَيِّ ثُمَّ لَا يُقۡصِرُونَ ﴿٢٠٢﴾", "w": [["خذ العفو", "ما سهل عليهم قوله وتيسّر لهم فعله، ولا تطالبهم بما لا يملكون أو لا يعلمون."], ["وأمر بالعرف", "بالمعروف."], ["ينزغنّك", "يصيبك منه نزغ بإثارة غضبك."], ["فاستعذ بالله", "قل: أعوذ بالله، يدفعه عنك، إنه سميع عليم."], ["اتقوا", "أي الشرك والمعاصي."], ["طائف من الشيطان", "ألمّ بهم شيء من وسوسته."], ["وإخوانهم يمدّونهم في الغي", "إخوان الشياطين من أهل الشرك والمعاصي يمدّهم الشياطين في الغي."], ["ثم لا يُقصرون", "لا يكفّون عن الغي الذي هو الضلال والشر."]], "m": "لما علّم الله رسوله كيف يحاجّ المشركين، علّمه أسمى الآداب وأكمل الأخلاق: خذ العفو، خذ من أخلاق الناس ما سهل عليهم وتيسّر لهم، ولا تطالبهم بما لا يملكون، وأمر بالمعروف، وأعرض عن الجاهلين فلا تؤاخذهم، وقد سأل رسول الله ﷺ جبريل عن معناها فقال: «تعفو عمن ظلمك، وتصل من قطعك، وتعطي من حرمك». وإما ينزغنّك من الشيطان نزغ فأثار غضبك حتى لا تلتزم بهذا الأدب فاستعذ بالله يدفعه عنك، إنه سميع لأقوالك عليم بأحوالك. ثم بيّن جدوى الاستعاذة: إن الذين اتقوا ربهم إذا مسّهم طائف من الشيطان بإثارة الغضب أو الشهوة تذكّروا أمر الله ونهيه ووعده ووعيده، فإذا هم مبصرون قبح المعصية وسوء عاقبتها فكفّوا عنها. وإخوان الشياطين من أهل الشرك والمعاصي يمدّهم الشياطين في الغي ويزيّنونه لهم، ثم لا يُقصرون عنه ولا يكفّون.", "h": ["الأمر بالتزام الآداب والتحلّي بأكمل الأخلاق، ومن أرقاها: العفو عمن ظلم، وإعطاء من حرم، وصلة من قطع.", "وجوب الاستعاذة بالله عند الشعور بالوسوسة أو الغضب أو تزيين الباطل.", "فضيلة التقوى، وهي فعل الفرائض وترك المحرمات.", "شؤم أخوّة الشياطين، حيث لا يُقصر صاحبها، بمدّ الشياطين له، عن الغي الذي هو الشر والفساد."], "k": "«تذكّروا فإذا هم مبصرون»… حين يغلبني الغضب، هل أتذكّر ربي فأُبصر، أم أترك الشيطان يقودني؟"}, {"lbl": "الآيات ٢٠٣ – ٢٠٦", "q": "وَإِذَا لَمۡ تَأۡتِهِم بِـَٔايَةٖ قَالُواْ لَوۡلَا ٱجۡتَبَيۡتَهَاۚ قُلۡ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَيَّ مِن رَّبِّيۚ هَٰذَا بَصَآئِرُ مِن رَّبِّكُمۡ وَهُدٗى وَرَحۡمَةٞ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٢٠٣﴾ وَإِذَا قُرِئَ ٱلۡقُرۡءَانُ فَٱسۡتَمِعُواْ لَهُۥ وَأَنصِتُواْ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿٢٠٤﴾ وَٱذۡكُر رَّبَّكَ فِي نَفۡسِكَ تَضَرُّعٗا وَخِيفَةٗ وَدُونَ ٱلۡجَهۡرِ مِنَ ٱلۡقَوۡلِ بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ وَلَا تَكُن مِّنَ ٱلۡغَٰفِلِينَ ﴿٢٠٥﴾ إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسۡجُدُونَۤ۩ ﴿٢٠٦﴾", "w": [["لولا اجتبيتها", "هلّا اخترعتها واختلقتها من نفسك وأتيتنا بها؟"], ["هذا بصائر من ربكم", "هذا القرآن حجج وبراهين وأدلة على ما جئت به وأدعوكم إليه، فهو أقوى حجة من الآية التي تطالبون بها."], ["فاستمعوا له وأنصتوا", "اطلبوا سماعه وتكلّفوا له، وأنصتوا: اسكتوا حتى تسمعوا سماعاً ينفعكم."], ["وخيفة", "خوفاً."], ["بالغدو والآصال", "الغدو: أول النهار، والآصال: أواخره."], ["من الغافلين", "عن ذكر الله تعالى."], ["إن الذين عند ربك", "أي الملائكة."], ["يسبّحونه", "ينزّهونه بألسنتهم بنحو: سبحان الله وبحمده."]], "m": "وإذا لم تأتِ المشركين بآية كما طلبوا قالوا: هلّا اخترعتها من نفسك؟ قل: إنما أنا عبد الله ورسوله لا أفتات عليه، إنما أتبع ما يوحى إليّ من ربي، هذا القرآن بصائر من ربكم على صدق رسالتي، وهدى ورحمة لقوم يؤمنون، أفتؤمنون بالآية الواحدة ولا تؤمنون بالآيات الكثيرة؟ وعلى ذكر حجج القرآن أمر الله المؤمنين إذا قُرئ عليهم أن يستمعوا وينصتوا، سواء في الجمعة على المنبر أو غيرها: وإذا قُرئ القرآن فاستمعوا له وأنصتوا لعلكم تُرحمون بهداه. ثم أمر رسوله، وأمته تبع له: واذكر ربك في نفسك سراً، تضرّعاً وخيفة، ودون الجهر من القول، بأن يُسمع نفسه أو من يليه، بالغدو والآصال، ولا تكن من الغافلين، وتأسَّ بالملائكة: إن الذين عند ربك لا يستكبرون عن عبادته، ويسبّحونه وله يسجدون.", "h": ["القرآن أكبر آية، بل هو أعظم من كل الآيات التي أعطيها الرسل ﵈.", "وجوب الإنصات عند تلاوة القرآن، وخاصة في خطبة الجمعة على المنبر، وعند قراءة الإمام في الصلاة الجهرية.", "وجوب ذكر الله بالغدو والآصال.", "بيان آداب الذكر، ومنها: الإسرار به وعدم رفع الصوت به.", "مشروعية الائتساء بالصالحين والاقتداء بهم في فعل الخيرات وترك المنكرات.", "عزيمة السجود عند قوله: «وله يسجدون»، وهذه أول سجدات القرآن، ويسجد القارئ والمستمع له، أما السامع فليس عليه سجود، ويستقبل بها القبلة، ويكبّر عند السجود وعند الرفع منه، ولا يسلّم، وكونه متوضئاً أفضل."], "k": "«فاستمعوا له وأنصتوا لعلكم ترحمون»… هل أسمع القرآن وقلبي حاضر، أم وأنا منشغل بغيره؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 113;
insert into public.tdb_cards(topic, i, body) select 113, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١٨٧ – ١٨٨", "q": "يَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرۡسَىٰهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ رَبِّيۖ لَا يُجَلِّيهَا لِوَقۡتِهَآ إِلَّا هُوَۚ ثَقُلَتۡ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ لَا تَأۡتِيكُمۡ إِلَّا بَغۡتَةٗۗ يَسۡـَٔلُونَكَ كَأَنَّكَ حَفِيٌّ عَنۡهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿١٨٧﴾ قُل لَّآ أَمۡلِكُ لِنَفۡسِي نَفۡعٗا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُۚ وَلَوۡ كُنتُ أَعۡلَمُ ٱلۡغَيۡبَ لَٱسۡتَكۡثَرۡتُ مِنَ ٱلۡخَيۡرِ وَمَا مَسَّنِيَ ٱلسُّوٓءُۚ إِنۡ أَنَا۠ إِلَّا نَذِيرٞ وَبَشِيرٞ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿١٨٨﴾", "w": [["الساعة", "الوقت الذي تنتهي فيه الحياة الدنيا بالفناء."], ["أيّان مرساها", "متى وقت قيامها؟"], ["لا يجلّيها لوقتها", "لا يظهرها في وقتها المحدّد لها إلا هو سبحانه وتعالى."], ["بغتة", "فجأة، بدون توقّع أو انتظار."], ["حفيّ عنها", "ملحف مبالغ في السؤال عنها حتى أصبحت تعرف وقت مجيئها."], ["الغيب", "ما غاب عن حواسنا وعقولنا فلم يُدرك بحاسة ولا بعقل، والمراد به هنا ما سيحدث في المستقبل القريب أو البعيد."], ["السوء", "كل ما يسوء العبد في روحه أو بدنه."], ["إن أنا إلا نذير", "ما أنا إلا نذير وبشير، فلست بإله يدبّر الأمر ويعلم الغيب."]], "m": "سأل أفراد من قريش أو غيرهم النبي ﷺ عن الساعة متى قيامها، فعلّمه ربه الجواب: يسألونك عن الساعة أيّان مرساها؟ قل إنما علمها عند ربي خاصة، لا يجلّيها لوقتها إلا هو، ثقُلت في السماوات والأرض، ثقل أمر علمها على أهلها، لا تأتيكم إلا بغتة. يسألونك كأنك حفيّ عنها، ملحف في السؤال حتى عرفتها، قل إنما علمها عند الله، ولكن أكثر الناس لا يعلمون أن إخفاءها لحكم عالية، ولولا الجهل ما سألوا. وأمره أن يقول: لا أملك لنفسي نفعاً ولا ضراً إلا ما شاء الله، ولو كنت أعلم الغيب لاستكثرت من الخير وما مسّني السوء، فلست بإله أعلم الغيب، إن أنا إلا نذير وبشير لقوم يؤمنون، ووظيفتي البشارة والنذارة ينتفع بها المؤمنون خاصة.", "h": ["مردّ علم الساعة إلى الله وحده، فكل مسؤول عنها غير الله ليس أعلم من السائل.", "للساعة أشراط، بعضها في الكتاب وبعضها في السنة، وليس معنى ذلك أنه تحديد لوقتها، وإنما هي مقدّمات تدل على قربها فقط.", "استأثر الله بعلم الغيب، فلا يعلم الغيب إلا الله، ومن علّمه الله شيئاً منه علم، كما علّم نبيه ﷺ بعض المغيّبات، والمعلَّم بالشيء لا يقال فيه يعلم الغيب، وإنما يقال: علّمه ربه غيب كذا وكذا فعلمه.", "إذا كان الرسول لا يملك لنفسه نفعاً ولا ضراً فكيف يُطلب منه ذلك؟ وإذا كان الرسول لا يملك فهل من دونه من العباد يملك؟ إذا عرفت هذا ظهر لك ضلال أقوام يدعون الموتى سائلين ضارعين عند قبورهم، ويقولون إنهم لا يدعونهم ولكن يتوسّلون بهم فقط."], "k": "«يسألونك عن الساعة أيّان مرساها»… السؤال المهم ليس «متى»، بل: ماذا أعددت لها؟"}, {"lbl": "الآيات ١٨٩ – ١٩٣", "q": "۞هُوَ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَجَعَلَ مِنۡهَا زَوۡجَهَا لِيَسۡكُنَ إِلَيۡهَاۖ فَلَمَّا تَغَشَّىٰهَا حَمَلَتۡ حَمۡلًا خَفِيفٗا فَمَرَّتۡ بِهِۦۖ فَلَمَّآ أَثۡقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنۡ ءَاتَيۡتَنَا صَٰلِحٗا لَّنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ ﴿١٨٩﴾ فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحٗا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَاۚ فَتَعَٰلَى ٱللَّهُ عَمَّا يُشۡرِكُونَ ﴿١٩٠﴾ أَيُشۡرِكُونَ مَا لَا يَخۡلُقُ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ ﴿١٩١﴾ وَلَا يَسۡتَطِيعُونَ لَهُمۡ نَصۡرٗا وَلَآ أَنفُسَهُمۡ يَنصُرُونَ ﴿١٩٢﴾ وَإِن تَدۡعُوهُمۡ إِلَى ٱلۡهُدَىٰ لَا يَتَّبِعُوكُمۡۚ سَوَآءٌ عَلَيۡكُمۡ أَدَعَوۡتُمُوهُمۡ أَمۡ أَنتُمۡ صَٰمِتُونَ ﴿١٩٣﴾", "w": [["من نفس واحدة", "هي نفس آدم ﵇."], ["وجعل منها زوجها", "خلق منها زوجها، وهي حواء، خلقها من ضلع آدم."], ["ليسكن إليها", "ليألفها ويأنس بها لكونها من جنسه."], ["فلما تغشّاها", "أي وطئها."], ["فمرّت به", "ذاهبة جائية تقضي حوائجها لخفّة الحمل في الأشهر الأولى."], ["فلما أثقلت", "أصبح الحمل ثقيلاً في بطنها."], ["لئن آتيتنا صالحاً", "ولداً صالحاً، ليس حيواناً بل إنساناً."], ["جعلا له شركاء", "سمّياه عبد الحارث، وهو عبد الله جل جلاله."], ["فتعالى الله عما يشركون", "أي أهل مكة، حيث أشركوا في عبادة الله أصناماً."], ["وإن تدعوهم إلى الهدى", "أي الأصنام، لا يتبعوكم."]], "m": "يقول الله للسائلين عن الساعة عناداً من أهل الشرك: هو الذي خلقكم من نفس واحدة، آدم، وخلق منها زوجها حواء، هو المستحق للعبادة دون الأصنام، ليسكن إليها، إذ لو كانت من جنس آخر لما حصلت الألفة والأنس. فلما تغشّاها حملت حملاً خفيفاً فمرّت به، فلما أثقلت دعوا الله ربهما: لئن آتيتنا غلاماً صالحاً لنكوننّ من الشاكرين، فاستجاب لهما، فلما آتاهما صالحاً جعلا له شركاء فيما آتاهما، حيث سمّته حواء عبد الحارث بتغرير من إبليس، وهو من الشرك الخفي المعفوّ عنه، نحو: لولا الطبيب هلك فلان. فتعالى الله عما يشركون، عائد إلى كفار قريش، بدليل ما بعده: أيشركون ما لا يخلق شيئاً وهم يُخلقون، ولا يستطيعون لهم نصراً ولا أنفسهم ينصرون، لأنهم جمادات؟ وإن تدعوهم إلى الهدى لا يتبعوكم، سواء عليكم أدعوتموهم أم أنتم صامتون، فهل يصح أن يُعبد هذا، وتُقرّب له القرابين، ويُحلف به، ويُعكف عنده، ويُستغاث به؟", "h": ["بيان أصل خلق البشر، وهو آدم وحواء ﵉.", "بيان السر في كون الزوج من جنس الزوج، وهو الألفة والأنس والتعاون.", "بيان خداع إبليس وتضليله للإنسان، حيث زيّن لحواء تسمية ولدها بعبد الحارث.", "الشرك في التسمية شرك خفي معفوّ عنه، وتركه أولى.", "التنديد بالشرك والمشركين، وبيان جهل المشركين وسفههم، إذ يعبدون ما لا يسمع ولا يبصر ولا يجيب ولا يتبع."], "k": "«لئن آتيتنا صالحاً لنكوننّ من الشاكرين»… كم وعدت ربي بالشكر في الشدة، ثم نسيته بعد العطاء؟"}, {"lbl": "الآيات ١٩٤ – ١٩٨", "q": "إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمۡثَالُكُمۡۖ فَٱدۡعُوهُمۡ فَلۡيَسۡتَجِيبُواْ لَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٩٤﴾ أَلَهُمۡ أَرۡجُلٞ يَمۡشُونَ بِهَآۖ أَمۡ لَهُمۡ أَيۡدٖ يَبۡطِشُونَ بِهَآۖ أَمۡ لَهُمۡ أَعۡيُنٞ يُبۡصِرُونَ بِهَآۖ أَمۡ لَهُمۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۗ قُلِ ٱدۡعُواْ شُرَكَآءَكُمۡ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ ﴿١٩٥﴾ إِنَّ وَلِـِّۧيَ ٱللَّهُ ٱلَّذِي نَزَّلَ ٱلۡكِتَٰبَۖ وَهُوَ يَتَوَلَّى ٱلصَّـٰلِحِينَ ﴿١٩٦﴾ وَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ لَا يَسۡتَطِيعُونَ نَصۡرَكُمۡ وَلَآ أَنفُسَهُمۡ يَنصُرُونَ ﴿١٩٧﴾ وَإِن تَدۡعُوهُمۡ إِلَى ٱلۡهُدَىٰ لَا يَسۡمَعُواْۖ وَتَرَىٰهُمۡ يَنظُرُونَ إِلَيۡكَ وَهُمۡ لَا يُبۡصِرُونَ ﴿١٩٨﴾", "w": [["عباد أمثالكم", "مملوكون مخلوقون أمثالكم لمالك واحد هو الله رب العالمين."], ["شركاءكم", "أصنامكم التي تشركون بها."], ["ثم كيدون", "بما استطعتم من أنواع الكيد."], ["فلا تُنظرون", "فلا تمهلون، لأني لا أبالي بكم."], ["إن وليّي الله", "المتولّي أموري وحمايتي ونصرتي الله الذي نزّل القرآن."], ["وتراهم ينظرون", "ترى الأصنام المنحوتة على شكل رجال ينظرون إليك وهم لا يبصرون."]], "m": "هذه الآيات مقرّرة لمبدأ التوحيد مندّدة بالشرك: إن الذين تدعون من دون الله دعاء عبادة عباد أمثالكم، مملوكون لله كما أنتم مملوكون، لا يملكون لكم ولا لأنفسهم نفعاً، فادعوهم فليستجيبوا لكم إن كنتم صادقين أنهم آلهة، وكيف يستجيبون وهم جماد؟ ألهم أرجل يمشون بها؟ أم لهم أيد يبطشون بها؟ أم لهم أعين يبصرون بها؟ أم لهم آذان يسمعون بها؟ لا شيء من ذلك، فبأي حق يُعبدون؟ ثم أمر رسوله أن يعلن أنه لا يخافهم ولا يعبأ بهم: قل ادعوا شركاءكم ثم كيدون فلا تُنظرون ساعة، إن وليّي الله الذي نزّل الكتاب، وهو يتولّى الصالحين، فينصرني منكم ويحميني من كيدكم، والذين تدعون من دونه لا يستطيعون نصركم ولا أنفسهم ينصرون، وإن تدعوهم إلى الهدى لا يسمعوا، وتراهم، تماثيل من حجارة، ينظرون إليك بأعينهم المفتوحة دائماً وهم لا يبصرون.", "h": ["إقامة الحجة على المشركين بالكشف عن حقيقة ما يدّعون أنها آلهة، فإذا بها أصنام لا تسمع ولا تجيب، لا أيد لها ولا أرجل ولا آذان ولا أعين.", "وجوب التوكل على الله تعالى، وطرد الخوف من النفس، والوقوف أمام الباطل وأهله في شجاعة وصبر وثبات، اعتماداً على الله تعالى وولايته، إذ هو يتولّى الصالحين.", "جواز المبالغة في التنفير من الباطل والشر بذكر العيوب والنقائص."], "k": "«إن وليّي الله الذي نزّل الكتاب وهو يتولّى الصالحين»… هل أطلب ولاية الله بأن أكون من الصالحين؟"}, {"lbl": "الآيات ١٩٩ – ٢٠٢", "q": "خُذِ ٱلۡعَفۡوَ وَأۡمُرۡ بِٱلۡعُرۡفِ وَأَعۡرِضۡ عَنِ ٱلۡجَٰهِلِينَ ﴿١٩٩﴾ وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَٰنِ نَزۡغٞ فَٱسۡتَعِذۡ بِٱللَّهِۚ إِنَّهُۥ سَمِيعٌ عَلِيمٌ ﴿٢٠٠﴾ إِنَّ ٱلَّذِينَ ٱتَّقَوۡاْ إِذَا مَسَّهُمۡ طَـٰٓئِفٞ مِّنَ ٱلشَّيۡطَٰنِ تَذَكَّرُواْ فَإِذَا هُم مُّبۡصِرُونَ ﴿٢٠١﴾ وَإِخۡوَٰنُهُمۡ يَمُدُّونَهُمۡ فِي ٱلۡغَيِّ ثُمَّ لَا يُقۡصِرُونَ ﴿٢٠٢﴾", "w": [["خذ العفو", "ما سهل عليهم قوله وتيسّر لهم فعله، ولا تطالبهم بما لا يملكون أو لا يعلمون."], ["وأمر بالعرف", "بالمعروف."], ["ينزغنّك", "يصيبك منه نزغ بإثارة غضبك."], ["فاستعذ بالله", "قل: أعوذ بالله، يدفعه عنك، إنه سميع عليم."], ["اتقوا", "أي الشرك والمعاصي."], ["طائف من الشيطان", "ألمّ بهم شيء من وسوسته."], ["وإخوانهم يمدّونهم في الغي", "إخوان الشياطين من أهل الشرك والمعاصي يمدّهم الشياطين في الغي."], ["ثم لا يُقصرون", "لا يكفّون عن الغي الذي هو الضلال والشر."]], "m": "لما علّم الله رسوله كيف يحاجّ المشركين، علّمه أسمى الآداب وأكمل الأخلاق: خذ العفو، خذ من أخلاق الناس ما سهل عليهم وتيسّر لهم، ولا تطالبهم بما لا يملكون، وأمر بالمعروف، وأعرض عن الجاهلين فلا تؤاخذهم، وقد سأل رسول الله ﷺ جبريل عن معناها فقال: «تعفو عمن ظلمك، وتصل من قطعك، وتعطي من حرمك». وإما ينزغنّك من الشيطان نزغ فأثار غضبك حتى لا تلتزم بهذا الأدب فاستعذ بالله يدفعه عنك، إنه سميع لأقوالك عليم بأحوالك. ثم بيّن جدوى الاستعاذة: إن الذين اتقوا ربهم إذا مسّهم طائف من الشيطان بإثارة الغضب أو الشهوة تذكّروا أمر الله ونهيه ووعده ووعيده، فإذا هم مبصرون قبح المعصية وسوء عاقبتها فكفّوا عنها. وإخوان الشياطين من أهل الشرك والمعاصي يمدّهم الشياطين في الغي ويزيّنونه لهم، ثم لا يُقصرون عنه ولا يكفّون.", "h": ["الأمر بالتزام الآداب والتحلّي بأكمل الأخلاق، ومن أرقاها: العفو عمن ظلم، وإعطاء من حرم، وصلة من قطع.", "وجوب الاستعاذة بالله عند الشعور بالوسوسة أو الغضب أو تزيين الباطل.", "فضيلة التقوى، وهي فعل الفرائض وترك المحرمات.", "شؤم أخوّة الشياطين، حيث لا يُقصر صاحبها، بمدّ الشياطين له، عن الغي الذي هو الشر والفساد."], "k": "«تذكّروا فإذا هم مبصرون»… حين يغلبني الغضب، هل أتذكّر ربي فأُبصر، أم أترك الشيطان يقودني؟"}, {"lbl": "الآيات ٢٠٣ – ٢٠٦", "q": "وَإِذَا لَمۡ تَأۡتِهِم بِـَٔايَةٖ قَالُواْ لَوۡلَا ٱجۡتَبَيۡتَهَاۚ قُلۡ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَيَّ مِن رَّبِّيۚ هَٰذَا بَصَآئِرُ مِن رَّبِّكُمۡ وَهُدٗى وَرَحۡمَةٞ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٢٠٣﴾ وَإِذَا قُرِئَ ٱلۡقُرۡءَانُ فَٱسۡتَمِعُواْ لَهُۥ وَأَنصِتُواْ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿٢٠٤﴾ وَٱذۡكُر رَّبَّكَ فِي نَفۡسِكَ تَضَرُّعٗا وَخِيفَةٗ وَدُونَ ٱلۡجَهۡرِ مِنَ ٱلۡقَوۡلِ بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ وَلَا تَكُن مِّنَ ٱلۡغَٰفِلِينَ ﴿٢٠٥﴾ إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسۡجُدُونَۤ۩ ﴿٢٠٦﴾", "w": [["لولا اجتبيتها", "هلّا اخترعتها واختلقتها من نفسك وأتيتنا بها؟"], ["هذا بصائر من ربكم", "هذا القرآن حجج وبراهين وأدلة على ما جئت به وأدعوكم إليه، فهو أقوى حجة من الآية التي تطالبون بها."], ["فاستمعوا له وأنصتوا", "اطلبوا سماعه وتكلّفوا له، وأنصتوا: اسكتوا حتى تسمعوا سماعاً ينفعكم."], ["وخيفة", "خوفاً."], ["بالغدو والآصال", "الغدو: أول النهار، والآصال: أواخره."], ["من الغافلين", "عن ذكر الله تعالى."], ["إن الذين عند ربك", "أي الملائكة."], ["يسبّحونه", "ينزّهونه بألسنتهم بنحو: سبحان الله وبحمده."]], "m": "وإذا لم تأتِ المشركين بآية كما طلبوا قالوا: هلّا اخترعتها من نفسك؟ قل: إنما أنا عبد الله ورسوله لا أفتات عليه، إنما أتبع ما يوحى إليّ من ربي، هذا القرآن بصائر من ربكم على صدق رسالتي، وهدى ورحمة لقوم يؤمنون، أفتؤمنون بالآية الواحدة ولا تؤمنون بالآيات الكثيرة؟ وعلى ذكر حجج القرآن أمر الله المؤمنين إذا قُرئ عليهم أن يستمعوا وينصتوا، سواء في الجمعة على المنبر أو غيرها: وإذا قُرئ القرآن فاستمعوا له وأنصتوا لعلكم تُرحمون بهداه. ثم أمر رسوله، وأمته تبع له: واذكر ربك في نفسك سراً، تضرّعاً وخيفة، ودون الجهر من القول، بأن يُسمع نفسه أو من يليه، بالغدو والآصال، ولا تكن من الغافلين، وتأسَّ بالملائكة: إن الذين عند ربك لا يستكبرون عن عبادته، ويسبّحونه وله يسجدون.", "h": ["القرآن أكبر آية، بل هو أعظم من كل الآيات التي أعطيها الرسل ﵈.", "وجوب الإنصات عند تلاوة القرآن، وخاصة في خطبة الجمعة على المنبر، وعند قراءة الإمام في الصلاة الجهرية.", "وجوب ذكر الله بالغدو والآصال.", "بيان آداب الذكر، ومنها: الإسرار به وعدم رفع الصوت به.", "مشروعية الائتساء بالصالحين والاقتداء بهم في فعل الخيرات وترك المنكرات.", "عزيمة السجود عند قوله: «وله يسجدون»، وهذه أول سجدات القرآن، ويسجد القارئ والمستمع له، أما السامع فليس عليه سجود، ويستقبل بها القبلة، ويكبّر عند السجود وعند الرفع منه، ولا يسلّم، وكونه متوضئاً أفضل."], "k": "«فاستمعوا له وأنصتوا لعلكم ترحمون»… هل أسمع القرآن وقلبي حاضر، أم وأنا منشغل بغيره؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;